local config = {
  ui_story_5089_50890100_1_dialog_content = "(날씨 진짜 좋네. 간만에 혼자 호진성을 둘러보는 것도 좋겠어.)",
  ui_story_5089_50890100_2_dialog_content = "(근데 아까부터 왠지 누가 쳐다보는 것 같은데...)",
  ui_story_5089_50890100_3_dialog_content = "(악의가 느껴지는 건 아니지만, 그래도 좀 싸늘한 느낌이란 말이지...\n외국인이 여기 있는 게 이상한가?)",
  ui_story_5089_50890100_4_dialog_content = "크흠, 혹시 아스트라 대륙에서 온 사절님 아니십니까?",
  ui_story_5089_50890100_5_dialog_content = "아마... 그럴걸요. 혹시 무슨 일 있으신가요?",
  ui_story_5089_50890100_6_dialog_content = "마침 잘 됐군요! 소인은 한미한 재능으로 제나라 곳곳에서\n요릿집과 주점을 차려서 먹고사는 사람입니다.",
  ui_story_5089_50890100_7_dialog_content = "듣자 하니 사절님께선 건두부를 좋아하신다던데, 마침 소인 가게의 특산품입니다.\n선물이라 하기도 민망하지만 부디 받아주십시오.",
  ui_story_5089_50890100_8_dialog_content = "드실 만하시거든 말씀만 하십시오. 또 가져다드리겠습니다.",
  ui_story_5089_50890100_9_dialog_content = "엥? 제가 건두부를 좋아한다고요? 아니, 잠깐만요! 아직 그쪽이 누군지도 모르는데...",
  ui_story_5089_50890100_10_dialog_content = "사절님께서 오셨군요! 뵙게 되어 정말 영광입니다.\n저는 연해 일대에서 비단과 포목을 파는 사람입니다.",
  ui_story_5089_50890100_11_dialog_content = "여봐라! 얼른 가게에 가서 귀한 쌍봉오복팔길상비단을 가져와 사절님께 보여드려라!",
  ui_story_5089_50890100_12_dialog_content = "아, 아니에요! 괜찮아요!",
  ui_story_5089_50890100_13_dialog_content = "사절 나리, 저희 주인께서 근처 가게에 연회 자리를 마련했으니 왕림해 주십시오!",
  ui_story_5089_50890100_14_dialog_content = "사절 나리, 저희 아가씨가 내일 집에서 시회를 여는데요.\n나리를 위해 특별히 초대장도 쓰셨습니다.",
  ui_story_5089_50890100_15_dialog_content = "저기 저 사람 누구야? 뭐가 이렇게 시끌벅적해?",
  ui_story_5089_50890100_16_dialog_content = "서쪽 대륙에서 온 사절이래!",
  ui_story_5089_50890100_17_dialog_content = "용녀낭랑님의 총애를 받는 분이고, 호진성의 물난리도 해결해 주셨고,\n악행을 일삼는 교룡까지 진압해 주신 데다가, 이제 곧 세자님과 결혼하실 그분 말이야!",
  ui_story_5089_50890100_18_dialog_content = "뭐? 나도 얼른 가서 봐야겠다!",
  ui_story_5089_50890100_19_dialog_content = "사절 나리! 사절 나리...",
  ui_story_5089_50890100_20_dialog_content = "이, 이런... 일단 튀자!",
  ui_story_5089_50890100_21_dialog_content = "하아... 휴... 드디어 돌아왔네.",
  ui_story_5089_50890100_22_dialog_content = "내가 전에 좀 도와준 건 맞지만, 다들 열정이 좀 과한 거 아니냐고...",
  ui_story_5089_50890100_23_dialog_content = "설마 앞으로는 외출할 때마다 진예한테 신통력으로 모습을 숨겨달라고 해야 되는 건가...",
  ui_story_5089_50890100_24_dialog_content = "아니, 그리고 방금 뭔가 말도 안 되는 소문도 하나 들은 것 같은데...",
  ui_story_5089_50890100_25_dialog_content = "<color=#e8d9bb>똑똑.</color>",
  ui_story_5089_50890100_26_dialog_content = "(저번에 선극 씨한테 편지를 보내러 갔던 기관조구나. 어디 보자...)",
  ui_story_5089_50890100_27_dialog_content = "어라?",
  ui_story_5089_50890100_28_dialog_content = "(이건 내가 보낸 편지잖아? 심지어 뜯지도 않았어. 설마 선극 씨를 못 찾은 건가?)",
  ui_story_5089_50890100_29_dialog_content = "똑.",
  ui_story_5089_50890100_30_dialog_content = "(이상하네. 춘삭절 때 선극 씨는 업나라로 가서 마저 할 일이 있다고 했었잖아.)",
  ui_story_5089_50890100_31_dialog_content = "(근데 대체 어디로 가버린 거야?)",
  ui_story_5089_50890100_32_dialog_content = "(그러고 보면 내가 용주에 처음 왔을 때부터 선극 씨는 계속\n뭔가 조사하고 있었어. 설마...)",
  ui_story_5089_50890100_33_dialog_content = "사절 나리, 손님이 오셨습니다.",
  ui_story_5089_50890100_34_dialog_content = "(...영빈관까지 쫓아온 거냐고!)",
  ui_story_5089_50890100_35_dialog_content = "안 만날래요. 아이테르는 겨울잠을 잔다고 가서 전해 주세요.",
  ui_story_5089_50890100_36_dialog_content = "하지만... 겨울은 이제 막 지나지 않았는지요.",
  ui_story_5089_50890100_37_dialog_content = "봄엔 막 겨울잠에서 깨서 적응이 잘 안돼요. 그리고 가을엔 겨울잠 준비 때문에 시간이 없죠.\n아무튼 그러니까 거절할 거예요.",
  ui_story_5089_50890100_38_dialog_content = "이제 PlayerName 공자를 만나는 것이 이토록 어려운 일이 되었을 줄은 몰랐구나.",
  ui_story_5089_50890100_39_dialog_content = "다, 단당 씨?! 아, 아니, 저기, 방금 그건 단당 씨인 줄 모르고...",
  ui_story_5089_50890100_40_dialog_content = "알고 있다.",
  ui_story_5089_50890100_41_dialog_content = "지금의 그대는 비단 이국의 사절이 아니라 제나라의 위기를 해결한 일등 공신이다.",
  ui_story_5089_50890100_42_dialog_content = "게다가 「세자가 아스트라의 대사와 결혼을 하려 한다」는 소문까지 더해져,\n최근 호진성에 의론이 분분하다.",
  ui_story_5089_50890100_43_dialog_content = "제나라 상인들의 기풍이라면, 저들은 필시 앞다투어 그대와 교분을 쌓고자 할 게다.",
  ui_story_5089_50890100_44_dialog_content = "그럼 온 호진성이 다 알았단 거잖아요!\n그런 말도 안 되는 소리를 아무도 의심을 안 한단 말이에요?!",
  ui_story_5089_50890100_45_dialog_content = "공연한 소문은 없는 법이 아니더냐.",
  ui_story_5089_50890100_46_dialog_content = "...저 좀 살려 주세요.",
  ui_story_5089_50890100_47_dialog_content = "차라리 세자의 마음을 받아주는 것은 어떠한가.",
  ui_story_5089_50890100_48_dialog_content = "세자는 비록 다소 짓궂은 면이 있으나, 심성은 순수하다.\n지금까지도 춘삭절 때 용감히 나섰던 그대의 늠름한 자태를 잊지 못하고 있지.",
  ui_story_5089_50890100_49_dialog_content = "세자비가 되어 왕궁에 들어가면 저들도 어쩔 수 없이 자중하게 될 게야.",
  ui_story_5089_50890100_50_dialog_content = "단당 씨 지금 저 놀리려고 일부러 온 건가요?!",
  ui_story_5089_50890100_51_dialog_content = "설마 PlayerName 공자의 눈에는 내가 그런 사람인 게냐?",
  ui_story_5089_50890100_52_dialog_content = "아니요! 그런 뜻이 아니라...",
  ui_story_5089_50890100_53_dialog_content = "후훗, 농을 친 것이니 긴장할 필요 없다.",
  ui_story_5089_50890100_54_dialog_content = "다만 오늘 내가 공자를 찾은 이유는... 구야.",
  ui_story_5089_50890100_55_dialog_content = "예.",
  ui_story_5089_50890100_56_dialog_content = "으앗! 구 씨도 있었어요?! 지금까지 전혀 몰랐다구요...",
  ui_story_5089_50890100_57_dialog_content = "군주 전하께서 사절님과 긴히 상의할 일이 있으십니다.\n제가 두 분을 모실 테니, 모두 물러가세요.",
  ui_story_5089_50890100_58_dialog_content = "네.",
  ui_story_5089_50890100_59_dialog_content = "제가 차를 준비하겠습니다.",
  ui_story_5089_50890100_60_dialog_content = "아, 괜찮아요. 제가 하면 돼요!",
  ui_story_5089_50890100_61_dialog_content = "궁에서 만든 간식도 있으니 같이 드시지요.\n다른 분부가 없으시다면, 저는 잠시 물러가 있겠습니다.",
  ui_story_5089_50890100_62_dialog_content = "어라? 구 씨는 같이 안 먹어요?",
  ui_story_5089_50890100_63_dialog_content = "PlayerName 공자도 권하는데 구도 같이 앉아서 드는 게 좋겠구나.",
  ui_story_5089_50890100_64_dialog_content = "...그것은 규율에 어긋나는 일입니다.\n저는 문밖을 지키고 있을 테니, 필요하시면 불러 주십시오.",
  ui_story_5089_50890100_65_dialog_content = "......",
  ui_story_5089_50890100_66_dialog_content = "...혹시 싸웠어요?",
  ui_story_5089_50890100_67_dialog_content = "구 씨는 평소에도 말이 별로 없긴 하지만, 오늘은 유독 거리감이 심하네요.",
  ui_story_5089_50890100_68_dialog_content = "외려 나와 다투었으면 더 좋았을 것이다.",
  ui_story_5089_50890100_69_dialog_content = "?",
  ui_story_5089_50890100_70_dialog_content = "그 일은 우선 제쳐두고, 나는 오늘 PlayerName 공자에게 작별 인사를 하려고 온 것이다.",
  ui_story_5089_50890100_71_dialog_content = "작별 인사요...? 어디 가는데요?",
  ui_story_5089_50890100_72_dialog_content = "숙부, 즉 지금의 업나라 대왕께서 조서를 내려 내게 귀국을 명하셨다.",
  ui_story_5089_50890100_73_dialog_content = "그럼 잘된 거 아닌가요? 단당 씨도 드디어 집에 갈 수 있게 된 거잖아요!",
  ui_story_5089_50890100_74_dialog_content = "근데 정말 일이 그렇게 쉽게 풀린 건가요?\n단당 씨는 제나라에... 으음... 유학 온 거잖아요.",
  ui_story_5089_50890100_75_dialog_content = "솔직하게 말해도 된다.\n오늘날까지도 내가 「볼모」라는 말 한 마디로 PlayerName 공자와 의가 상할 성싶으냐?",
  ui_story_5089_50890100_76_dialog_content = "물론 그대가 염려하는 바는 옳다. 볼모인 내가 귀국하는 것은 결코 쉬운 일이 아니야.",
  ui_story_5089_50890100_77_dialog_content = "하여 제와 업 양국은 대외적으로는 새로운 조건을 논의하고 있다.",
  ui_story_5089_50890100_78_dialog_content = "그럼 내부적으로는요?",
  ui_story_5089_50890100_79_dialog_content = "스승님께서는 제나라가 나의 귀국을 막지 않을 것이라고 약조하셨다.",
  ui_story_5089_50890100_80_dialog_content = "「상인은 이익을 중히 여기나, 결코 배은망덕한 무리는 아니다」.\n제나라 국군의 뜻도 이와 같아 보이더구나.",
  ui_story_5089_50890100_81_dialog_content = "배은망덕이라 하면...?",
  ui_story_5089_50890100_82_dialog_content = "춘삭절의 소란 이후 궁에서는 특별히 용녀낭랑을 위하여 사당을 수리하고 신상을 만들었다.",
  ui_story_5089_50890100_83_dialog_content = "린 가문은 다시 가세를 일으켜 나날이 번창하고 있고,\nPlayerName 공자는 제나라의 명예 국민이 되어 백성들의 추앙을 받고 있지.",
  ui_story_5089_50890100_84_dialog_content = "심지어 나 역시도 후한 상을 적지 않게 받았느니라.",
  ui_story_5089_50890100_85_dialog_content = "오직 한 사람만이 힘을 쓰고도 아직 사례를 받지 못했다.",
  ui_story_5089_50890100_86_dialog_content = "...선극 씨 말이죠? 참, 요즘 계속 연락이 안 되던데, 혹시 뭔가 아시는 거 있으세요?",
  ui_story_5089_50890100_87_dialog_content = "바로 그것이 내가 말하려 하는 두 번째 일이다.",
  ui_story_5089_50890100_88_dialog_content = "업나라의 서신에서 이르기를, 선기경은 춘삭절 이후 대왕의 명에 따라\n체포하여 투옥되었다고 하더구나.",
  ui_story_5089_50890100_89_dialog_content = "선기경이 독단으로 병기를 전용한 것은 반역죄와 같다.",
  ui_story_5089_50890100_90_dialog_content = "네?!",
  ui_story_5089_50890100_91_dialog_content = "하여 나는 내일 업으로 돌아가기로 결정했다.",
  ui_story_5089_50890100_92_dialog_content = "하루라도 빨리 정세를 파악하고, 선기경의 사면을 도울 것이야.",
  ui_story_5089_50890100_93_dialog_content = "PlayerName 공자는──",
  ui_story_5089_50890100_94_dialog_content = "저도 같이 갈래요!",
  ui_story_5089_50890100_95_dialog_content = "알겠다.",
  ui_story_5089_50890100_96_dialog_content = "사실 단당 씨가 작별 인사를 하러 왔다고 했을 때부터,\n전 같이 데려가 달라고 부탁하고 싶었어요.",
  ui_story_5089_50890100_97_dialog_content = "제가 무슨 신도 아니고, 이렇게 사람들 공물 받으려고 용주에 온 것도 아니잖아요.\n진짜 신도 그렇게 안 하는데 말이에요.",
  ui_story_5089_50890100_98_dialog_content = "어차피 호진성에 더 있어 봤자 이젠 딱히 할 것도 없으니까, 마침 떠나려던 참이었어요.",
  ui_story_5089_50890100_99_dialog_content = "게다가 선극 씨도 제 친구예요. 단당 씨가 안 된다고 해도 전 방법을 찾을...\n잠깐만요, 방금 뭐라구요?",
  ui_story_5089_50890100_100_dialog_content = "알겠다고 하였다만.",
  ui_story_5089_50890100_101_dialog_content = "...전 분명히 단당 씨가 이 일은 저랑 관계가 없다면서 남으라고 할 줄 알았는데요.",
  ui_story_5089_50890100_102_dialog_content = "자고로 인간은 홀로 살아갈 수 없는 법, 무리를 이루는 자는 번영하고,\n도움을 적게 받는 자는 망한다.",
  ui_story_5089_50890100_103_dialog_content = "PlayerName 공자의 이 가르침은 아직도 내게 생생하여 감히 잊을 수가 없구나.",
  ui_story_5089_50890100_104_dialog_content = "...제가 그렇게 심오한 말을 했었나요?",
  ui_story_5089_50890100_105_dialog_content = "후훗, 하면 나는 이제 궁으로 돌아가 마지막 준비를 할 터이니,\nPlayerName 공자, 내일 보자꾸나.",
  ui_story_5089_50890100_106_dialog_content = "그럼 나도 짐을 좀 싸야겠네...",
  ui_story_5089_50890100_107_dialog_content = "가는 게냐?",
  ui_story_5089_50890100_108_dialog_content = "으앗! 진예 너 언제부터 여기 있었어?",
  ui_story_5089_50890100_109_dialog_content = "PlayerName 그대가 이 몸이 신통력으로 모습을 숨겨주길 원했을 때부터 있었느니라~",
  ui_story_5089_50890100_110_dialog_content = "그럼 처음부터 쭉 있었다는 소리잖아!",
  ui_story_5089_50890100_111_dialog_content = "...그럼 너도 들었겠지만, 난 내일 업나라로 갈 거야.\n그래서 당분간은 같이 못 놀 것 같아.",
  ui_story_5089_50890100_112_dialog_content = "하면 이 몸도 같이 가서 길을 막는 녀석들을 날려주마.",
  ui_story_5089_50890100_113_dialog_content = "「오직 그 주먹으로, 천하를 개벽하리!」",
  ui_story_5089_50890100_114_dialog_content = "무슨 소리야?! 그건 「용녀진해」 내용이 전혀 아니잖아! 왜 하필 그 구절인 건데?!",
  ui_story_5089_50890100_115_dialog_content = "무슨 상관이냐. 어차피 신명이니 보살이니 하는 것들은 시간이 흐르면\n사람들 입에서 오르내리는 전설도 변하기 마련이다.",
  ui_story_5089_50890100_116_dialog_content = "결정했다. 나중에 아무 도장에 가서 무술을 좀 배워야겠구나.",
  ui_story_5089_50890100_117_dialog_content = "그, 그래... 대신 그땐 힘 좀 많이 빼야 될걸. 내가 옆에 없어도 너무 막 나가진 마...",
  ui_story_5089_50890100_118_dialog_content = "정말 이 몸이 함께 업나라에 가 주지 않아도 괜찮은 게냐?\nPlayerName 네가 소원만 빈다면...",
  ui_story_5089_50890100_119_dialog_content = "그렇게 되면 진예 네가 내 친구로 남을 수 있을까?",
  ui_story_5089_50890100_120_dialog_content = "......",
  ui_story_5089_50890100_121_dialog_content = "난 진예 네가 계속 내 친구였으면 좋겠어.",
  ui_story_5089_50890100_122_dialog_content = "그러니까 난 선녀용왕님을 필요할 때 이용하는 수단으로 삼고 싶진 않아.",
  ui_story_5089_50890100_123_dialog_content = "<color=#e8d9bb>진예가 갑자기 손을 들더니, 창밖에서 나뭇잎 하나를 잡아당겨 건넸다.</color>",
  ui_story_5089_50890100_124_dialog_content = "이건 왜?",
  ui_story_5089_50890100_125_dialog_content = "송별 선물이니라.",
  ui_story_5089_50890100_126_dialog_content = "광령에게는 이와 같은 예법이 있지 않더냐.",
  ui_story_5089_50890100_127_dialog_content = "PlayerName 네가 돌아오면 그때 같이 놀자꾸나~",
  ui_story_5089_50890100_128_dialog_content = "그냥 보통 버드나무 잎 같은데... 진예?",
  ui_story_5089_50890100_129_dialog_content = "(빨리도 가네... 뭐, 됐어. 일단 잘 놔뒀다가 나중에 말려서 책갈피라도 만들어야지.)",
  ui_story_5089_50890100_130_dialog_content = "(가서 다른 사람들이랑도 인사해야겠다.)",
  ui_story_5089_50890100_131_dialog_content = "<color=#e8d9bb>다음날</color>",
  ui_story_5089_50890100_132_dialog_content = "(단당 씨랑 약속한 곳이 여기가 맞겠지?)",
  ui_story_5089_50890100_133_dialog_content = "PlayerName! PlayerName! 드디어 왔구나! 정말 오랫동안 기다렸어!",
  ui_story_5089_50890100_134_dialog_content = "세, 세자...? 네가 왜 여기 있어? 그리고 그 큰 상자는 또 뭔데?",
  ui_story_5089_50890100_135_dialog_content = "당연히 그대들을 배웅하러 왔지. 이건 그대를 위해 준비한 송별 선물이야!",
  ui_story_5089_50890100_136_dialog_content = "전부 내가 엄선한 보물들이라구.",
  ui_story_5089_50890100_137_dialog_content = "봐, 이건 내가 어릴 때 늘 가지고 다녔던 인형이고, 이건 내가 명절에 직접 만든 꽃등이야.",
  ui_story_5089_50890100_138_dialog_content = "그리고 이건 내가 제일 좋아하는 소설! 스승님은 보면 안 된다고 하셨지만,\n내가 여러 사람들한테 부탁해서 겨우 산 거야!",
  ui_story_5089_50890100_139_dialog_content = "아, 그리고... 단당이랑 스승님한테 들었어.",
  ui_story_5089_50890100_140_dialog_content = "그대의 의견을 묻지도 않고 정혼자로 삼아서 곤란하게 만들었다고. 미안해.",
  ui_story_5089_50890100_141_dialog_content = "세자...",
  ui_story_5089_50890100_142_dialog_content = "PlayerName 님, 배가 곧 떠납니다.",
  ui_story_5089_50890100_143_dialog_content = "아, 네. 그럼... 이건 다 세자의 성의니까 잘 받을게.",
  ui_story_5089_50890100_144_dialog_content = "고마워!",
  ui_story_5089_50890100_145_dialog_content = "여봐라. 남은 것들도 전부 가져오거라.",
  ui_story_5089_50890100_146_dialog_content = "자, 잠깐만... 저 산더미 같은 상자는 다 뭔데?!",
  ui_story_5089_50890100_147_dialog_content = "별거 아냐. 겸사겸사 주는 거야. 시간이 너무 촉박해서 이 상자만 내가 직접 골랐어.",
  ui_story_5089_50890100_148_dialog_content = "하지만 믿어줘! 내 진심은 진짜니까!",
  ui_story_5089_50890100_149_dialog_content = "난 이제 세상 물정도 알고 성숙한 대장부가 됐어. 지금까지 내가 얼마나 무모했는지도 알았고.",
  ui_story_5089_50890100_150_dialog_content = "결혼 전에 먼저 「청혼」해야 하는 것도 몰랐다니 말이야.",
  ui_story_5089_50890100_151_dialog_content = "...하아?",
  ui_story_5089_50890100_152_dialog_content = "닻 올라가오──",
  ui_story_5089_50890100_153_dialog_content = "출항이오──",
  ui_story_5089_50890100_154_dialog_content = "<color=#e8d9bb>해안에서 손을 흔드는 세자를 뒤로한 채, 배는 서서히 출항했다.</color>",
  ui_story_5089_50890100_155_dialog_content = "앞으로도 계속 선물을 보낼 거야! 그대가 내 정혼자가 되겠다고 약속할 때까지──!",
  ui_story_5089_50890100_156_dialog_content = "......",
  ui_story_5089_50890100_157_dialog_content = "...역시 호진성을 떠나길 잘했어!",
  ui_story_5089_50890100_158_dialog_content = "세자가 PlayerName 공자를 이렇게나 좋아할 줄은 몰랐구나.\n세자가 한 가지 저토록 열중하는 모습은 나도 본 적이 없었다.",
  ui_story_5089_50890100_159_dialog_content = "근데 이렇게 선물이 많아서야... 다 그냥 장난감이라 쳐도 이걸 받을 순 없어요...",
  ui_story_5089_50890100_160_dialog_content = "PlayerName 공자가 받고 싶지 않다면 업나라에 도착했을 때 다시 돌려주면 되지 않겠느냐.",
  ui_story_5089_50890100_161_dialog_content = "그래야겠네요. 지금은 선극 씨를 구하는 게 더 중요하니까요.",
  ui_story_5089_50890100_162_dialog_content = "그럼 가자꾸나... 아니지...",
  ui_story_5089_50890100_163_dialog_content = "돌아가자, 업나라로.",
  ui_story_5089_50890201_1_dialog_content = "PlayerName 님, 군주 전하, 곧 하선하실 시간입니다.",
  ui_story_5089_50890201_2_dialog_content = "제나라랑 업나라 경계를 지난 지 얼마 안 된 것 같았는데, 벌써 도착했어요?",
  ui_story_5089_50890201_3_dialog_content = "아직이다. 중원의 업나라는 제나라만큼 수계가 풍부하지 않아 수로를 통해서\n올 수 있는 것은 여기까지다.",
  ui_story_5089_50890201_4_dialog_content = "이 부두... 내 기억이 옳다면 이곳은 동리진이겠구나.",
  ui_story_5089_50890201_5_dialog_content = "예, 마을의 객잔을 예약했습니다. 이곳에서 하룻밤 쉬셔야 합니다.",
  ui_story_5089_50890201_6_dialog_content = "내일 마차가 준비되면 육로를 따라 도성으로 향할 것입니다.",
  ui_story_5089_50890201_7_dialog_content = "우린 계속 배를 타고 있었는데, 어떻게 그런 걸 다 준비한 거예요?",
  ui_story_5089_50890201_8_dialog_content = "배에 작은 배가 따로 있어서 빌려 타고 먼저 해안에 다녀왔습니다.",
  ui_story_5089_50890201_9_dialog_content = "이번 여정은 촉박하게 준비한 탓에 영접을 나올 사람이 없습니다.",
  ui_story_5089_50890201_10_dialog_content = "하여 전하를 누추한 곳에 모시는 죄를 범할 수밖에 없었습니다.\n그러니 적어도 주변의 안전은 꼭 확보해야겠지요.",
  ui_story_5089_50890201_11_dialog_content = "거의 다 왔다고 하지만... 아직도 육지가 전혀 안 보이네요.",
  ui_story_5089_50890201_12_dialog_content = "그나저나 혼자 노를 저어서 다녀오다니... 어쩐지 옷자락이 다 젖은 이유가 있었네요.",
  ui_story_5089_50890201_13_dialog_content = "어서 옷을 갈아입고 오거라. 계속 그렇게 있다가는 풍한에 걸릴 게야.",
  ui_story_5089_50890201_14_dialog_content = "괜찮습니다. 저는 어려서부터 무술을 익혀 몸이 건강한 편입니다.",
  ui_story_5089_50890201_15_dialog_content = "비록 육지에 다녀온 것은 길을 찾기 위해서였으나, 자신의 사소한 일로 전하의 곁을 떠난 것은\n직분을 다하지 못한 처신입니다.",
  ui_story_5089_50890201_16_dialog_content = "게다가 전하 앞에서 몸가짐이 단정하지 못한 것은 있어서는 안 될 일입니다.\n지금 바로 몸을 숨기도록 하겠습니다.",
  ui_story_5089_50890201_17_dialog_content = "잠깐만요, 전 그런 뜻이 아니라...",
  ui_story_5089_50890201_18_dialog_content = "되었다, PlayerName 공자, 그냥 내버려두거라.",
  ui_story_5089_50890201_19_dialog_content = "지금 구는 근래 통틀어 모습을 가장 오래 드러낸 것이니 말이다.",
  ui_story_5089_50890201_20_dialog_content = "궁에서조차 그러했지. 고개를 숙이고 서신을 정리하다 고개를 들면,\n어느새 차가 따라져 있고, 간식이 준비되어 있었다.",
  ui_story_5089_50890201_21_dialog_content = "간혹 밖에 나가서 사람들과 한두 마디 주고받고 방에 들어가면\n모든 것이 깔끔해져 있었고 말이야.",
  ui_story_5089_50890201_22_dialog_content = "근자에 구는 평소보다 훨씬 더 많은 일을 하였지만, 정작 모습은 도통 볼 수가 없었다.",
  ui_story_5089_50890201_23_dialog_content = "(우, 우렁각시?)",
  ui_story_5089_50890201_24_dialog_content = "두 사람 사이에 대체 무슨 일이 있었던 건가요?",
  ui_story_5089_50890201_25_dialog_content = "PlayerName 공자, 일전에 호진성에서 소란을 일으켰던 자들을 기억하느냐.",
  ui_story_5089_50890201_26_dialog_content = "자칭 「천명을 받은 자」라던 그 녀석들요?",
  ui_story_5089_50890201_27_dialog_content = "선녀용왕께서 도움을 주신 덕택으로 제나라 순검사는 잠복해 있던\n수많은 「천명」들을 일거에 체포했다.",
  ui_story_5089_50890201_28_dialog_content = "그중 제나라 조정에서 관직을 지내던 자만 해도 수십 명이 넘었지.",
  ui_story_5089_50890201_29_dialog_content = "비록 대개 미관말직에 지나지 않는 자들이었으나,\n시간이 지나 이처럼 암약하는 자들이 그물을 이룬다면...",
  ui_story_5089_50890201_30_dialog_content = "각 방면에서 국군과 조정에 영향을 미칠 수 있는 이러한 세력은\n국본을 흔들 수 있다고 하여도 과언이 아니다.",
  ui_story_5089_50890201_31_dialog_content = "다행히 이번에 저들을 다 잡았고, 제나라 국왕님도 모두 대비를 했으니까,\n더는 녀석들 뜻대로 되진 않겠죠.",
  ui_story_5089_50890201_32_dialog_content = "허나... PlayerName 공자, 그러한 조직이 과연 제나라에 국한된 일이겠느냐.",
  ui_story_5089_50890201_33_dialog_content = "그 말은...",
  ui_story_5089_50890201_34_dialog_content = "호진성의 소란이 있었던 날, 나는 그대를 찾아갔으나,\n궁문을 나서자마자 나를 가로막는 자들이 있었다.",
  ui_story_5089_50890201_35_dialog_content = "그런 얘기는 처음 듣는데요?! 다치거나 그랬던 건 아니죠?\n왜 다른 사람들한테 말 안 했어요?",
  ui_story_5089_50890201_36_dialog_content = "나를 막은 자들이 업나라의 밀정이었기 때문이다.",
  ui_story_5089_50890201_37_dialog_content = "?!",
  ui_story_5089_50890201_38_dialog_content = "작금의 조나라 황제는 아직 어리고, 8대 제후들은 저마다 다른 뜻을 품고 있다.",
  ui_story_5089_50890201_39_dialog_content = "서로 밀정을 보내는 것도 모두 익히 아는 바이나, 그렇다고 입에 담을 수 있는 일도 아니지.",
  ui_story_5089_50890201_40_dialog_content = "업나라의 밀정은 비록 나를 군주로 대했으나, 실상은 오직 숙부의 명에만 따를 뿐이야.",
  ui_story_5089_50890201_41_dialog_content = "하면 저들이 나를 가로막고, 「천명」의 일을 도운 것은...",
  ui_story_5089_50890201_42_dialog_content = "업나라 국왕님이 배후에서 지시하고 있다는 가능성밖에 없겠네요.",
  ui_story_5089_50890201_43_dialog_content = "...숙부께서는 비록 과거의 명성은 높지 않으나, 즉위 후에는 인재를 등용하고,\n인의로써 백성을 대하는 명군의 기풍을 보이셨다.",
  ui_story_5089_50890201_44_dialog_content = "이번 소행은 필시 「천명」의 소인배들에게 속으신 연유일 터.",
  ui_story_5089_50890201_45_dialog_content = "알겠어요. 역시 이렇게 급하게 출발한 이유가 있었네요.",
  ui_story_5089_50890201_46_dialog_content = "「천명」의 눈을 피해서 최대한 자유롭게 움직이고,\n업나라 국왕님한테 진실을 알릴 기회를 얻기 위해서겠죠.",
  ui_story_5089_50890201_47_dialog_content = "그리고 우릴 도와주느라 감옥에 간 선극 씨도 구하고 말이에요!",
  ui_story_5089_50890201_48_dialog_content = "역시 나를 이해하는 이는 PlayerName 공자뿐이로구나.",
  ui_story_5089_50890201_49_dialog_content = "근데 이 일들이 구 씨랑은 또 무슨 상관인데요?",
  ui_story_5089_50890201_50_dialog_content = "PlayerName 공자는 몰랐던 것이냐.",
  ui_story_5089_50890201_51_dialog_content = "구가 바로 업나라 밀정의 수장이니라.",
  ui_story_5089_50890201_52_dialog_content = "하...하지만 단당 씨의 호위무사잖아요?",
  ui_story_5089_50890201_53_dialog_content = "구는 본래 숙부 휘하의 측근이었고, 내가 제나라에 볼모로 보내지기 전 즈음에야\n나의 호위로 명해졌다.",
  ui_story_5089_50890201_54_dialog_content = "구는 숙부께 큰 은혜를 입어 숙부의 명이라면 그 어떤 것도 어기지 않을 것이야.",
  ui_story_5089_50890201_55_dialog_content = "하여 숙부께서 구에게 나를 지키라 명하시면, 구는 이를 위해 제 목숨조차 버릴 수 있다.",
  ui_story_5089_50890201_56_dialog_content = "숙부께서는 나의 안위가 걱정되신다며 구에게 매달 서신으로 근황을 보고하라 하셨고,\n구는 어떤 일이 있어도 늘 기한을 지켜 서신을 보냈다.",
  ui_story_5089_50890201_57_dialog_content = "그건...",
  ui_story_5089_50890201_58_dialog_content = "그렇지, 숙부의 관심은 이해하나, 다른 관점에서 본다면 이는 감시나 다를 바 없다.",
  ui_story_5089_50890201_59_dialog_content = "잠깐만요, 그럼 지금 우리 움직임이 여전히 「천명」 녀석들 손바닥 안에\n있다는 거잖아요?! 구 씨가...",
  ui_story_5089_50890201_60_dialog_content = "...아니다.",
  ui_story_5089_50890201_61_dialog_content = "PlayerName 공자도 알지 않느냐. 구는 참으로 융통성이 없다는 점을 말이야.",
  ui_story_5089_50890201_62_dialog_content = "구는 숙부의 명을 어기지 않을 것이다. 허나 우리의 이번 출행의 의미 또한 알고 있다.\n하여 제 눈과 귀, 입을 닫을 수밖에 없는 게야.",
  ui_story_5089_50890201_63_dialog_content = "최소한의 호위 임무만 수행하고, 스스로 나의 곁에서 물러서면,\n자신이 모르는 일은 보고하지 않아도 되는 게지.",
  ui_story_5089_50890201_64_dialog_content = "이는 이미 구가 할 수 있는 최대한의 노력이다.",
  ui_story_5089_50890201_65_dialog_content = "게다가 저 완고한 구가 흔들리는 모습을 볼 수 있어 나는 사실 다소 기뻤다.",
  ui_story_5089_50890201_66_dialog_content = "적어도 우리가 함께 제나라에서 보낸 오 년이 헛되지는 않았다는 것이니.",
  ui_story_5089_50890201_67_dialog_content = "단당 씨.",
  ui_story_5089_50890201_68_dialog_content = "무에냐, PlayerName 공자는 내가 불행하다 생각하는 것이냐.",
  ui_story_5089_50890201_69_dialog_content = "단당 씨는 제나라에 있는 동안 괴로웠죠?",
  ui_story_5089_50890201_70_dialog_content = "...아?",
  ui_story_5089_50890201_71_dialog_content = "아, 그게... 제 말은 그러니까...",
  ui_story_5089_50890201_72_dialog_content = "제나라 국왕님이나 세자, 그리고 국사님도 다 좋은 사람인 건 저도 알아요.\n하지만... 그래도 제나라가 단당 씨 집은 아니잖아요.",
  ui_story_5089_50890201_73_dialog_content = "휴...",
  ui_story_5089_50890201_74_dialog_content = "왜, 왜 한숨 쉬는 건데요? 제가 뭐 잘못 말했나요?",
  ui_story_5089_50890201_75_dialog_content = "혹여 PlayerName 공자가 병졸을 이끌고 싸우는 장수라면, 필시 기습에 능한 지장일 게야.",
  ui_story_5089_50890201_76_dialog_content = "엥? 갑자기 왜 그런 얘기로 넘어가는데요?",
  ui_story_5089_50890201_77_dialog_content = "잠시 실례해야겠다. 하선을 하려거든 화장을 고쳐야 하니 말이야.",
  ui_story_5089_50890201_78_dialog_content = "아, 네...",
  ui_story_5089_50890201_79_dialog_content = "휴.",
  ui_story_5089_50890201_80_dialog_content = "휴.",
  ui_story_5089_50890201_81_dialog_content = "썩은 나무는 조각할 수 없어.",
  ui_story_5089_50890201_82_dialog_content = "소철나무엔 꽃이 피지 않아.",
  ui_story_5089_50890201_83_dialog_content = "「썩은 나무」...? 설마 나 말하는 거야? 아니, 잠깐만...\n너희 다언이랑 다어 아냐? 너희가 왜 여기 있어?",
  ui_story_5089_50890201_84_dialog_content = "가르침을 얻으려면 금과를 줘야지!",
  ui_story_5089_50890201_85_dialog_content = "해답을 얻으려면 은대추를 줘야지!",
  ui_story_5089_50890201_86_dialog_content = "미안하지만 난 금과도, 은대추도 없어.",
  ui_story_5089_50890201_87_dialog_content = "배가 고프면 너희 주인한테 가. 천간 씨도 여기 있는 거지?\n뭐, 그 사람 불쑥불쑥 나타났다 사라지는 것도 이젠 익숙해.",
  ui_story_5089_50890201_88_dialog_content = "천간 씨, 있는 거 맞죠?",
  ui_story_5089_50890201_89_dialog_content = "주인 없어졌어.",
  ui_story_5089_50890201_90_dialog_content = "물밑에 가라앉았어.",
  ui_story_5089_50890201_91_dialog_content = "바로 저기!",
  ui_story_5089_50890201_92_dialog_content = "...뭐라고?!",
  ui_story_5089_50890201_93_dialog_content = "부글부글... 사... 부글부글... 소생 좀... 살려... 주십시오...",
  ui_story_5089_50890201_94_dialog_content = "천간 씨가 왜 물속에 있어요? 아니지...",
  ui_story_5089_50890201_95_dialog_content = "사람 살려!",
  ui_story_5089_50890202_1_dialog_content = "에엣취!",
  ui_story_5089_50890202_2_dialog_content = "휴, 덕분에 살았습니다.",
  ui_story_5089_50890202_3_dialog_content = "왜 이런 곳에서 물에 빠진 건데요? 또 용궁에 초대받았다는 소리는 하지 말고요.",
  ui_story_5089_50890202_4_dialog_content = "말하자면... 길진 않겠군요.",
  ui_story_5089_50890202_5_dialog_content = "소생은 제나라를 돌아다니는 게 지겨워서 다른 곳을 보러 가고 싶었습니다.\n허나 아시다시피 제 주머니 사정이 좋지 않아서 말이지요.",
  ui_story_5089_50890202_6_dialog_content = "큰 배는 탈 돈이 없어서 상단의 배를 여러 대 얻어 타면서 가다 서다 했지만,\n그래도 어찌저찌 업나라까지 잘 도착했지요.",
  ui_story_5089_50890202_7_dialog_content = "근데 어떻게 됐을 것 같습니까? 길을 서두르다 뜻밖에도 요마를 만났지 뭡니까!",
  ui_story_5089_50890202_8_dialog_content = "이는 무척 드문 일입니다. 조정에서 매해 대법을 펼쳐 사악한 힘을 억누르고 있고,\n제와 업의 접경은 연해 지대도 아닙니다.",
  ui_story_5089_50890202_9_dialog_content = "아마 어느 산에 숨어 있던 요마가 배가 고파서 나왔다가\n하필 재수도 없게 소생과 마주친 모양입니다.",
  ui_story_5089_50890202_10_dialog_content = "그래서 계속 쫓기고 쫓기다 방심한 순간 물에 빠지고 말았지요.",
  ui_story_5089_50890202_11_dialog_content = "여러분 덕분에 살았으니, 생명의 은혜는 갚아야겠지요. 허나 소생은 지금 가진 게 없으니...",
  ui_story_5089_50890202_12_dialog_content = "아무래도 제 몸을 바치는 수밖에 없을 것 같습니다.",
  ui_story_5089_50890202_13_dialog_content = "필요 없어요!",
  ui_story_5089_50890202_14_dialog_content = "천간 씨는 다른 할 일 없어요?",
  ui_story_5089_50890202_15_dialog_content = "소생의 이름을 기억하십니까?",
  ui_story_5089_50890202_16_dialog_content = "이천간이잖아요!",
  ui_story_5089_50890202_17_dialog_content = "그렇습니다. 「천간」이라는 단어에는 시간의 의미가 담겨 있지요.\n다시 말해서 전 시간이 아주 많은 사람인 것입니다.",
  ui_story_5089_50890202_18_dialog_content = "서둘러 거절하지 마십시오. 소생이 가기 전에 스스로 점을 쳐 보았는데,\n물난리를 당하기는 해도 부유한 자의 도움을 받을 수 있다더군요.",
  ui_story_5089_50890202_19_dialog_content = "그러나 그 부유한 자는... 자, 손 좀 내밀어 보십시오.",
  ui_story_5089_50890202_20_dialog_content = "이렇게요?",
  ui_story_5089_50890202_21_dialog_content = "<color=#e8d9bb>촤악──</color>",
  ui_story_5089_50890202_22_dialog_content = "...왜 산통을 제 손에 엎는데요?",
  ui_story_5089_50890202_23_dialog_content = "이런, 큰일이로군요. 음의 용과 음의 쥐라니.",
  ui_story_5089_50890202_24_dialog_content = "용과 쥐가 뛰는 것은 본디 크게 길한 괘상인데, 하필 둘 다 음의 괘라니,\n이는 진룡이 숨고 소인이 훼방을 놓아 큰 재앙이 있을 징조입니다.",
  ui_story_5089_50890202_25_dialog_content = "본디 이런 괘가 나오면 소생은 발바닥에 기름칠을 하고 멀리 도망쳤어야 했는데,\n하필 생명의 은혜를 아직 못 갚아서 그럴 수가 없겠습니다.",
  ui_story_5089_50890202_26_dialog_content = "뭐, 됐습니다. 그럼 소생이 오늘 목숨을 걸고 군자를 모시겠습니다. 함께 이 재앙을 막읍시다.",
  ui_story_5089_50890202_27_dialog_content = "전 천간 씨가 하는 말도 그렇고, 생명의 은혜라는 것도 의심스러운데요.",
  ui_story_5089_50890202_28_dialog_content = "아니, 직접 소생을 구해주셔놓고 무슨 말씀을 그리 섭섭하게 하십니까.",
  ui_story_5089_50890202_29_dialog_content = "근데 천간 씨는 「부유한 자」한테 구해질 거라고 그랬잖아요.",
  ui_story_5089_50890202_30_dialog_content = "농담이 아니고, 전 살면서 부유한 게 어떤 느낌인지 경험해 본 적도 없다구요!",
  ui_story_5089_50890202_31_dialog_content = "그건 이상하군요. 괘상에 따르면 당신은 지금 한 국가보다 더 부유해야 마땅한데 말이지요.",
  ui_story_5089_50890202_32_dialog_content = "그런 좋은 일은 꿈에서나 가능할 것 같은데요...",
  ui_story_5089_50890202_33_dialog_content = "PlayerName 님, 배가 접안을 마쳤습니다. 먼저 하선하시지요.\n짐은 선원들이 옮겨드릴 것입니다.",
  ui_story_5089_50890202_34_dialog_content = "은혜를 갚겠다고 한 이상, 이런 일은 소생도 응당 도와야지요.\n이 상자는 소생이 들겠습니다...",
  ui_story_5089_50890202_35_dialog_content = "...어이쿠, 뭐가 이리 무거운... 쓰읍...",
  ui_story_5089_50890202_36_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5089_50890202_37_dialog_content = "<color=#e8d9bb>상자가 우수수 떨어지자, 뚜껑이 헐거워지면서 열리고 말았고,\n안에서는 눈을 찌를 듯한 황금빛이 드러났다.</color>",
  ui_story_5089_50890202_38_dialog_content = "PlayerName 공자, 하선 준비는...",
  ui_story_5089_50890202_39_dialog_content = "......",
  ui_story_5089_50890202_40_dialog_content = "......",
  ui_story_5089_50890202_41_dialog_content = "......",
  ui_story_5089_50890202_42_dialog_content = "안 깨졌겠죠?! 아이고, 아이고야, 여긴 좀 깨졌네! 소생을 내다 팔아도 못 갚을 텐데요!",
  ui_story_5089_50890202_43_dialog_content = "단당 씨, 천간 씨, 저기... 저 눈에 문제가 좀 생긴 것 같아요.",
  ui_story_5089_50890202_44_dialog_content = "세자가 준 상자 안에 왜 금이 있죠? 아하하하...",
  ui_story_5089_50890202_45_dialog_content = "...구야.",
  ui_story_5089_50890202_46_dialog_content = "<color=#e8d9bb>구는 곧바로 나서서 신속하게 모든 상자를 검사했다.</color>",
  ui_story_5089_50890202_47_dialog_content = "전하, 검사를 마쳤습니다. 장난감과 비취, 주옥이 든 두 상자를 제외하고, 모두 황금입니다.",
  ui_story_5089_50890301_1_dialog_content = "한참 걸었는데 왜 아직도 도착을 못 한 거죠? 객잔이 부두에서 이렇게 먼가요...?",
  ui_story_5089_50890301_2_dialog_content = "그거야 방금 재물신을 만나셔서 그런 거 아닙니까.\n부자가 되니 강도를 만날까 무서워 인적 드문 길로 가니 느린 것이지요.",
  ui_story_5089_50890301_3_dialog_content = "돌려줘야 되니까 그렇죠! 누구라도 갑자기 금이 생기면 다 이럴 거라구요!",
  ui_story_5089_50890301_4_dialog_content = "세자는 분명히 나머지는 「별거 아니고 겸사겸사 주는 거」라고 했는데...",
  ui_story_5089_50890301_5_dialog_content = "제나라의 세자라면 금은보화가 가장 별거 아닌 것이라 할 수도 있겠지.",
  ui_story_5089_50890301_6_dialog_content = "허나 다른 이라면... 적어도 업나라에서는 PlayerName 공자가 이 금을 가지고\n성을 하나 사는 것도 거뜬할 것이야.",
  ui_story_5089_50890301_7_dialog_content = "걱정할 필요 없다. 구가 있는 한 평범한 도적들은 우리에게 다가오지 못할 터이니.",
  ui_story_5089_50890301_8_dialog_content = "객잔에 다 왔습니다. 거리의 끝에 있는 저 건물입니다.",
  ui_story_5089_50890301_9_dialog_content = "드디어 쉴 수 있겠네요. 오는 동안 정말 조마조마했다구요... 음? 단당 씨, 왜 그래요?",
  ui_story_5089_50890301_10_dialog_content = "아무 일도 아니다. 그저 제나라로 가던 그때 이곳을 지났던 기억이 났을 뿐이야.",
  ui_story_5089_50890301_11_dialog_content = "동리진은 업나라에서 가장 큰 곡물 생산지와 인접해 있고, 부두도 있지.\n하여 대도시엔 못 미쳐도 시끌벅적하다.",
  ui_story_5089_50890301_12_dialog_content = "허나 오늘 다시 오게 되었는데 왜인지 쓸쓸한 느낌이 드는구나.",
  ui_story_5089_50890301_13_dialog_content = "소저는 이곳에 꽤 오랫동안 안 오신 모양입니다.",
  ui_story_5089_50890301_14_dialog_content = "노인장이 연유를 알려줄 수 있겠는가.",
  ui_story_5089_50890301_15_dialog_content = "물론입니다. 누구나 아는 일이니 어려울 것도 없지요.",
  ui_story_5089_50890301_16_dialog_content = "근 수년 사이에 여러 큰 공방이 성안에 들어섰는데,\n급료가 두둑하여 젊은이들은 전부 성에 일하러 나갔습니다.",
  ui_story_5089_50890301_17_dialog_content = "그래서 저 같은 노인네들만 남게 되었지요.\n저도 젊었으면 비바람, 땡볕 맞을 일 없는 공방에서 돈을 벌었을 것입니다.",
  ui_story_5089_50890301_18_dialog_content = "그러한가, 참, 노인장, 짊고 가는 그 쌀은 값이 얼마인가.",
  ui_story_5089_50890301_19_dialog_content = "소저께서 사시렵니까? 근 두 달간 쌀값이 계속 올랐는데, 오늘은 좀 더 올랐습니다.\n가격은 여기 써 두었지요.",
  ui_story_5089_50890301_20_dialog_content = "...잘 보았네. 노인장. 알려주어 고맙네.",
  ui_story_5089_50890301_21_dialog_content = "저 쌀에 뭔가 문제라도 있나요?",
  ui_story_5089_50890301_22_dialog_content = "저도 전에 호진성에 있을 때 궁금해서 쌀값을 물어본 적 있는데,\n저 사람이 말한 거랑 비슷했어요. 그럼 괜찮은 거 아닌가요?",
  ui_story_5089_50890301_23_dialog_content = "이처럼 작은 마을의 쌀값이 번영하기가 천하에서 손꼽히는 호진성과 견줄 정도라니.",
  ui_story_5089_50890301_24_dialog_content = "이것만으로도 이미 가장 큰 문제다. 허나, 어째서...",
  ui_story_5089_50890301_25_dialog_content = "<color=#e8d9bb>쿵.</color>",
  ui_story_5089_50890301_26_dialog_content = "어이쿠, 미안, 앞을 못 봐서 부딪혔네. 괜찮아? ...어? 너 그거...",
  ui_story_5089_50890301_27_dialog_content = "......!",
  ui_story_5089_50890301_28_dialog_content = "손님! 어...얼른 그놈을 잡으세요!",
  ui_story_5089_50890301_29_dialog_content = "그놈이 손님 짐을 훔쳤습니다!",
  ui_story_5089_50890301_30_dialog_content = "!",
  ui_story_5089_50890301_31_dialog_content = "──!",
  ui_story_5089_50890301_32_dialog_content = "잡았다.",
  ui_story_5089_50890301_33_dialog_content = "이거 놔! 빨리... 놓으라고! 에잇!",
  ui_story_5089_50890301_34_dialog_content = "<color=#e8d9bb>소년은 자신을 붙잡은 구의 손을 매섭게 깨물었지만,\n구는 꿈쩍도 않았고, 표정조차 변하지 않았다.</color>",
  ui_story_5089_50890301_35_dialog_content = "물건을 내놔.",
  ui_story_5089_50890301_36_dialog_content = "<color=#e8d9bb>소년은 눈이 붉어졌고, 구의 손을 더 깊게 물었다.</color>",
  ui_story_5089_50890301_37_dialog_content = "구야!",
  ui_story_5089_50890301_38_dialog_content = "<color=#e8d9bb>구가 단당을 잠시 의식한 순간, 소년은 잽싸게 탈출했다.</color>",
  ui_story_5089_50890301_39_dialog_content = "흥!",
  ui_story_5089_50890301_40_dialog_content = "야! 너...",
  ui_story_5089_50890301_41_dialog_content = "살려주세요! 인신매매범이 어린애를 잡으려고 해요!",
  ui_story_5089_50890301_42_dialog_content = "뭐? 백주 대낮에 감히 애를 납치하려고 해?!",
  ui_story_5089_50890301_43_dialog_content = "저기 저 사람들 좀 봐! 옷도 이상한 게 딱 봐도 좋은 사람은 아니네!",
  ui_story_5089_50890301_44_dialog_content = "잡아! 관아에 신고해!",
  ui_story_5089_50890301_45_dialog_content = "뭐가 어떻게 된 겁니까? 자자, 진정들 하세요. 다들 같은 편인데 말로 합시다.",
  ui_story_5089_50890301_46_dialog_content = "누가 같은 편이야?!",
  ui_story_5089_50890301_47_dialog_content = "안 되겠어요, 사람이 너무 많아요. 이러다 놓치겠어요!",
  ui_story_5089_50890301_48_dialog_content = "모두 물러서라!",
  ui_story_5089_50890301_49_dialog_content = "구야, 괜찮다. 저들은 모두 평범한 백성들이야.",
  ui_story_5089_50890301_50_dialog_content = "허나 만에 하나라도...",
  ui_story_5089_50890301_51_dialog_content = "어서 PlayerName 공자를 데리고 가서 사람을 찾거라. 여긴 내가 해결하마.",
  ui_story_5089_50890301_52_dialog_content = "안 됩니다. 저는 전하를 지켜야 합니다.",
  ui_story_5089_50890301_53_dialog_content = "이것은 명령이다.",
  ui_story_5089_50890301_54_dialog_content = "...예.",
  ui_story_5089_50890301_55_dialog_content = "PlayerName 님, 따라오십시오.",
  ui_story_5089_50890301_56_dialog_content = "그 녀석, 갑자기 없어져 버렸네요.",
  ui_story_5089_50890301_57_dialog_content = "휴, 금더미를 봤을 때부터 이런 일이 생길 줄 알았다니까요.",
  ui_story_5089_50890301_58_dialog_content = "근데 상대가 어린애인 건 좀 의외였어요.",
  ui_story_5089_50890301_59_dialog_content = "그래도 옷이 허름한 애였으니까, 분명히 무슨 사정이 있었겠죠.",
  ui_story_5089_50890301_60_dialog_content = "......",
  ui_story_5089_50890301_61_dialog_content = "...구 씨도 필요한 경우 외에는 저랑 말 한 마디도 안 할 생각인가요?",
  ui_story_5089_50890301_62_dialog_content = "......",
  ui_story_5089_50890301_63_dialog_content = "전 일개 외부인일 뿐이고, 용주에 대해 아직 잘 몰라요.\n그리고 당신들의 처지를 이해한다고 큰소리칠 수도 없어요.",
  ui_story_5089_50890301_64_dialog_content = "하지만 지금까지 전 많은 사람들을 봐 왔어요.",
  ui_story_5089_50890301_65_dialog_content = "누군가는 자기 신념을 위해 모든 걸 바치고, 기꺼이 여명의 불빛이 되고자 했죠.",
  ui_story_5089_50890301_66_dialog_content = "또 누군가는 자기 꿈을 위해 모든 걸 파멸시키고,\n검은 심연으로 빠지는 것도 마다하지 않았어요.",
  ui_story_5089_50890301_67_dialog_content = "물론 전 사람들의 옳고 그름을 판단할 생각은 없어요.\n남의 인생을 말 몇 마디로 정의할 자격도 없죠. 제가 하고 싶은 말은...",
  ui_story_5089_50890301_68_dialog_content = "아무것도 하지 않는다면... 얻는 것도 없고, 그 무엇도 바꿀 수 없어요.",
  ui_story_5089_50890301_69_dialog_content = "저는 업나라 대왕 전하의 검객이자 군주 전하의 호위입니다.",
  ui_story_5089_50890301_70_dialog_content = "제 책임은 명령에 복종하고, 충성을 다하는 것입니다.",
  ui_story_5089_50890301_71_dialog_content = "제가 뭘 바꿔야 할 필요는 없습니다.",
  ui_story_5089_50890301_72_dialog_content = "그럼 다르게 물어볼게요. 국왕님이랑 단당 씨가 상반된 명령을 내리면 어떻게 할 건가요?",
  ui_story_5089_50890301_73_dialog_content = "...두 분께서는 모두 천하를 품고 업나라를 위해 최선을 다하고 계십니다.",
  ui_story_5089_50890301_74_dialog_content = "그런 대답은 아무도 설득할 수 없어요.",
  ui_story_5089_50890301_75_dialog_content = "......",
  ui_story_5089_50890301_76_dialog_content = "여전히 그 애 모습은 안 보이네요. 제가 감응해 볼게요.",
  ui_story_5089_50890301_77_dialog_content = "[감응한다]",
  ui_story_5089_50890301_78_dialog_content = "찾았어요. 남쪽 골목에... 어라?",
  ui_story_5089_50890301_79_dialog_content = "에베베~",
  ui_story_5089_50890301_80_dialog_content = "저 꼬맹이...",
  ui_story_5089_50890301_81_dialog_content = "(어? 발밑에 뭔가 걸린 것 같은데...)",
  ui_story_5089_50890301_82_dialog_content = "<color=#e8d9bb>와르르르──</color>",
  ui_story_5089_50890301_83_dialog_content = "<color=#e8d9bb>대나무 장대가 무더기로 떨어지기 시작했다.</color>",
  ui_story_5089_50890301_84_dialog_content = "함정?!",
  ui_story_5089_50890301_85_dialog_content = "(이, 일단 물러서자!)",
  ui_story_5089_50890301_86_dialog_content = "<color=#e8d9bb>그러나 침입자의 행동을 미리 예측한 듯, 뒤이어 밟은 벽돌 자리는 이미 아래가 비어 있었다.</color>",
  ui_story_5089_50890301_87_dialog_content = "<color=#e8d9bb>휘잉!</color>",
  ui_story_5089_50890301_88_dialog_content = "<color=#e8d9bb>물이 가득 찬 나무통이 하늘에서 떨어졌다.</color>",
  ui_story_5089_50890301_89_dialog_content = "으앗!",
  ui_story_5089_50890301_90_dialog_content = "조심하세요.",
  ui_story_5089_50890301_91_dialog_content = "<color=#e8d9bb>그 순간, 마치 보이지 않는 바람이 지나간 듯했다.</color>",
  ui_story_5089_50890301_92_dialog_content = "<color=#e8d9bb>구는 반걸음만 앞으로 내딛고, 검을 검집에서 뽑지 않은 채 통의 가운데를 찔러 돌려보냈다.</color>",
  ui_story_5089_50890301_93_dialog_content = "<color=#e8d9bb>나무통 안의 물은 한 방울도 떨어지지 않았고, 맞은편 소년의 발밑에 다시 떨어졌다.</color>",
  ui_story_5089_50890301_94_dialog_content = "<color=#e8d9bb>그와 동시에 골목 양쪽에서 떨어지던 대나무들이 공중에서 기이하게 잠시 멈추더니,\n힘을 잃고 바닥에 흩어졌다.</color>",
  ui_story_5089_50890301_95_dialog_content = "<color=#e8d9bb>떨어진 대나무들은 이미 중심부터 전부 양단된 채였다.</color>",
  ui_story_5089_50890301_96_dialog_content = "대...대단해.",
  ui_story_5089_50890301_97_dialog_content = "어떻게 그런...",
  ui_story_5089_50890301_98_dialog_content = "물건을 돌려줘.",
  ui_story_5089_50890301_99_dialog_content = "...무슨 소린지 모르겠는데?!",
  ui_story_5089_50890301_100_dialog_content = "거기 서.",
  ui_story_5089_50890301_101_dialog_content = "잠깐만요, 구 씨.",
  ui_story_5089_50890301_102_dialog_content = "저 녀석이 이렇게 함정을 잔뜩 만들어서 여길 지킨 건 분명히 다른 의미가 있을 거예요.",
  ui_story_5089_50890301_103_dialog_content = "아마 물건은 여기 방 어딘가에 숨겨 뒀겠죠.",
  ui_story_5089_50890301_104_dialog_content = "!",
  ui_story_5089_50890301_105_dialog_content = "멈춰! 야! 내가 물건을 훔쳤어! 그러니까 빨리 날 잡으라구!",
  ui_story_5089_50890301_106_dialog_content = "역시.",
  ui_story_5089_50890301_107_dialog_content = "일단 안 들어갈게. 대신 너도 진정하고 우리랑 대화를 좀 할 수 있겠어?",
  ui_story_5089_50890301_108_dialog_content = "우린 나쁜 사람이 아냐. 만약 무슨 곤란한 일이 있는 거면, 우리가 도울 수 있을지도 몰라.",
  ui_story_5089_50890301_109_dialog_content = "...사실, 난...",
  ui_story_5089_50890301_110_dialog_content = "물러서요!",
  ui_story_5089_50890301_111_dialog_content = "네...?!",
  ui_story_5089_50890301_112_dialog_content = "<color=#e8d9bb>스윽──</color>",
  ui_story_5089_50890301_113_dialog_content = "<color=#e8d9bb>시선에 잡힌 것은 한 줄기 섬광이었다.</color>",
  ui_story_5089_50890301_114_dialog_content = "<color=#e8d9bb>챙──!</color>",
  ui_story_5089_50890301_115_dialog_content = "<color=#e8d9bb>구의 검이 순식간에 검집을 빠져나왔다.\n그리고 공중에는 가늘지만 매우 질긴 금속 실 가닥이 여러 개 있었다.</color>",
  ui_story_5089_50890301_116_dialog_content = "드디어 찾았군요.",
  ui_story_5089_50890301_117_dialog_content = "너는...",
  ui_story_5089_50890301_118_dialog_content = "<color=#e8d9bb>상대는 답하지 않았고, 더 많은 실이 한기와 함께 몰려왔다.</color>",
  ui_story_5089_50890302_1_dialog_content = "구 씨! 지금이에요!",
  ui_story_5089_50890302_2_dialog_content = "쳇.",
  ui_story_5089_50890302_3_dialog_content = "<color=#e8d9bb>쓰러졌던 자객이 갑자기 손을 들자, 보이지 않을 정도로 얇은 실이 당신을 향해 날아왔다.</color>",
  ui_story_5089_50890302_4_dialog_content = "!",
  ui_story_5089_50890302_5_dialog_content = "<color=#e8d9bb>똑── 똑──</color>",
  ui_story_5089_50890302_6_dialog_content = "<color=#e8d9bb>핏방울이 고요하게 더러워진 바닥 위에 떨어져 선홍빛 흔적을 남겼다.</color>",
  ui_story_5089_50890302_7_dialog_content = "구 씨...!",
  ui_story_5089_50890302_8_dialog_content = "<color=#e8d9bb>당신의 앞을 막아선 구는 손으로 직접 상대의 날카로운 흉기를 막아냈다.</color>",
  ui_story_5089_50890302_9_dialog_content = "PlayerName 님을 놀라게 만들었군요. 죄송합니다.",
  ui_story_5089_50890302_10_dialog_content = "<color=#e8d9bb>그 후 그녀는 손바닥을 모아 힘껏 쥐었다.</color>",
  ui_story_5089_50890302_11_dialog_content = "<color=#e8d9bb>빈틈을 노려 공중으로 뛰어올라 탈출을 시도하던 자객은 핏빛 실에 휘말려 추락하고 말았다.</color>",
  ui_story_5089_50890302_12_dialog_content = "가서 잡아 오겠습니다.",
  ui_story_5089_50890302_13_dialog_content = "하필이면 마주친 게 귀면의 염라라니...",
  ui_story_5089_50890302_14_dialog_content = "지금 순순히 투항하면 목숨은 살려주마.",
  ui_story_5089_50890302_15_dialog_content = "...「상인」 님, 비록 소인은 일개 척후병일 뿐이나, 우리 모두 대왕 전하의 직속수하이니,\n감히 「상인」 님을 동료라 부를 수 있겠지요.",
  ui_story_5089_50890302_16_dialog_content = "소인은 지금 임무를 수행하고 있습니다. 대왕 전하의 명을 거역할 생각이십니까?",
  ui_story_5089_50890302_17_dialog_content = "......",
  ui_story_5089_50890302_18_dialog_content = "구 씨, 상처는 괜찮아요? 그 사람은...",
  ui_story_5089_50890302_19_dialog_content = "제 잘못입니다. 그자는... 놓쳤습니다.",
  ui_story_5089_50890302_20_dialog_content = "그렇군요, 괜찮아요. 구 씨만 별일 없으면... 아니지, 별일이 있잖아요.",
  ui_story_5089_50890302_21_dialog_content = "왜 아까 손으로 막은 거예요?! 아픈 것도 몰라요? 상처 좀 보여줘요.",
  ui_story_5089_50890302_22_dialog_content = "작은 상처일 뿐입니다. 제가 알아서 처리하겠습니다.\nPlayerName 님께 폐를 끼칠 순 없습니다.",
  ui_story_5089_50890302_23_dialog_content = "구 씨... 휴, 알겠어요. 지금 바로 치료부터 해 주세요.\n저 두 애들은 제가 보러 갈 테니까요.",
  ui_story_5089_50890302_24_dialog_content = "두 애들이라고 하셨습니까?",
  ui_story_5089_50890302_25_dialog_content = "네, 저기 집 안에 있거든요.",
  ui_story_5089_50890302_26_dialog_content = "흐아아아앙── 무서워... 흑흑...",
  ui_story_5089_50890302_27_dialog_content = "우, 울지 마! 참! 내가 좋은 물건을 가져왔어!",
  ui_story_5089_50890302_28_dialog_content = "봐, 여기 귀여운 인형이랑 예쁜 꽃등도 있어.",
  ui_story_5089_50890302_29_dialog_content = "그리고 소설도 많아! 내가 읽어줄게, 그러니까 울지 마...",
  ui_story_5089_50890302_30_dialog_content = "훌쩍...",
  ui_story_5089_50890302_31_dialog_content = "얘는 금을 훔친 게 아니라 세자가 준 장난감만 가져갔던 거예요.",
  ui_story_5089_50890302_32_dialog_content = "너희 금 같은 걸 누가 탐낸다고 그래!",
  ui_story_5089_50890302_33_dialog_content = "흐아아앙! 무서운 사람이야! 으아앙──",
  ui_story_5089_50890302_34_dialog_content = "너네들 때문에 얘가 놀랐잖아! 얼른 나가!\n야, 울지 마! 네가 갖고 싶은 건 내가 뭐든지 찾아줄 테니까!",
  ui_story_5089_50890302_35_dialog_content = "......",
  ui_story_5089_50890302_36_dialog_content = "구 씨?",
  ui_story_5089_50890302_37_dialog_content = "<color=#e8d9bb>구는 소녀 앞에 쪼그리고 앉아 어색하게 손을 들어 자신의 가면을 소녀의 머리에 덮어주었다.</color>",
  ui_story_5089_50890302_38_dialog_content = "뭐, 뭐 하는 거야?! 만에 하나 걔한테 손을 댄다면──",
  ui_story_5089_50890302_39_dialog_content = "바람이 불고, 비가 내려요. 용왕이 북을 지고 왔구나♪",
  ui_story_5089_50890302_40_dialog_content = "어디에 숨길까, 가면 밑에 숨기자, 꼬마 숙녀를 숨기자♪",
  ui_story_5089_50890302_41_dialog_content = "소녀야 소녀야 겁먹지 말아라, 방에는 큰 참외가 있단다♪",
  ui_story_5089_50890302_42_dialog_content = "<color=#e8d9bb>구가 부드럽게 읊조리는 노랫소리와 함께, 가면 너머 소녀의 울음소리가 점점 작아졌다.</color>",
  ui_story_5089_50890302_43_dialog_content = "(구 씨가 저렇게 자상한 표정도 지을 수 있었던 거구나.)",
  ui_story_5089_50890302_44_dialog_content = "PlayerName 공자, 구야, 드디어 찾았구나.",
  ui_story_5089_50890302_45_dialog_content = "어머나, 구가 스스로 나서서 가면을 벗는 것을 보게 되다니, 대관절 어찌 된 일이냐.",
  ui_story_5089_50890302_46_dialog_content = "전하, 이건...",
  ui_story_5089_50890302_47_dialog_content = "언니...",
  ui_story_5089_50890302_48_dialog_content = "응?",
  ui_story_5089_50890302_49_dialog_content = "방금 그 노래, 다시 불러주면 안 돼?",
  ui_story_5089_50890302_50_dialog_content = "비슷해... 엄마가 불러 준 노래랑...",
  ui_story_5089_50890302_51_dialog_content = "그래.",
  ui_story_5089_50890302_52_dialog_content = "정말?! 그럼 다른 애들도 불러서 같이 들어도 돼?!",
  ui_story_5089_50890302_53_dialog_content = "다른 애들...?",
  ui_story_5089_50890302_54_dialog_content = "이구 오빠, 애들 불러도 돼?!",
  ui_story_5089_50890302_55_dialog_content = "...나쁜 녀석들은 아닌 것 같으니까, 부르고 싶으면 불러.",
  ui_story_5089_50890302_56_dialog_content = "무슨 일이래? 소화가 갑자기 우릴 다 부르고.",
  ui_story_5089_50890302_57_dialog_content = "그게 뭐 중요해? 어차피 우린 할 일도 없잖아.",
  ui_story_5089_50890302_58_dialog_content = "...왜 어른들이 있어...?",
  ui_story_5089_50890302_59_dialog_content = "왜 애들이 이렇게 많아?",
  ui_story_5089_50890302_60_dialog_content = "소생이 알고 있습니다. 객잔 주인에게 방금 묻고 오는 길입니다.",
  ui_story_5089_50890302_61_dialog_content = "마을 사람들이 다들 공방에 가서 일한다고 전의 그 노인장이 그러지 않았습니까?\n그렇다면 어쨌든 결국 객지살이 신세 아닙니까.",
  ui_story_5089_50890302_62_dialog_content = "그래서 많이들 자식을 고향에 두고 노인들한테 부탁한 것이지요.\n허나 노인들은 나이가 들어서 돌보는 데는 한계가 있습니다.",
  ui_story_5089_50890302_63_dialog_content = "그래서 이 아이들은 함께 모여 산과 들판을 뛰어다닌다더군요.",
  ui_story_5089_50890302_64_dialog_content = "그럼 얘들이 사실은 친가족이 아니란 말인가요? 전 소화가 이구 동생인 줄 알았는데...",
  ui_story_5089_50890302_65_dialog_content = "소화는 내 동생 맞아. 우리 엄마아빠는 일찍 돌아가셔서 난 소화네 집에서 자랐어.",
  ui_story_5089_50890302_66_dialog_content = "소하네 부모님이 며칠 전에 나가실 때 나한테 소하를 잘 돌봐달라고 했어.\n나도 당연히 그럴 거고.",
  ui_story_5089_50890302_67_dialog_content = "그치만 소화는 부모님이 보고 싶어서 며칠 동안 계속 울었어, 난 그래서...",
  ui_story_5089_50890302_68_dialog_content = "장난감을 가지고 가서 달래주고 싶었던 거야?",
  ui_story_5089_50890302_69_dialog_content = "근데 너희한테 잡혔으니까, 때리고 욕해도 어쩔 수 없겠지.",
  ui_story_5089_50890302_70_dialog_content = "훔친 건 잘못한 게 맞지만, 그런 사정을 알고도 어떻게 너한테 뭐라 하겠어.",
  ui_story_5089_50890302_71_dialog_content = "근데 저 아이들은 어떡하죠? 구 씨가 둘러싸여서 굳어버렸어요.",
  ui_story_5089_50890302_72_dialog_content = "그러니 PlayerName 공자도 게으름 피우지 말고 어서 도와주거라.",
  ui_story_5089_50890302_73_dialog_content = "전 뭘 해야 할까요?",
  ui_story_5089_50890302_74_dialog_content = "구가 이 많은 사람들 앞에서 노래를 불러야 하면 과히 난처하지 않겠느냐.\n우리가 조금은 분담하는 게 좋겠구나.",
  ui_story_5089_50890302_75_dialog_content = "가자, 객잔으로 돌아가서 내 비파를 가져와야겠다.",
  ui_story_5089_50890302_76_dialog_content = "그러고 보니 PlayerName 공자는 피아노라는 악기를 잘 친다고 들었는데,\n지금까지 들을 기회가 없었구나. 오늘 나와 함께 합주하는 것은 어떠한가.",
  ui_story_5089_50890302_77_dialog_content = "저야 물론 좋지만, 여긴 피아노가 없는걸요.",
  ui_story_5089_50890302_78_dialog_content = "그거야 있지요, 만들면 됩니다.",
  ui_story_5089_50890302_79_dialog_content = "옛 시절에는 현자가 북을 치며 노래를 불렀다면,\n지금은 아이테르가 잔을 치며 연주할 수 있지 않겠습니까?",
  ui_story_5089_50890302_80_dialog_content = "자, 이렇게 잔 몇 개에 물의 양을 다르게 해서 담으면,\n두드렸을 때 저마다 다른 음을 내지요.",
  ui_story_5089_50890302_81_dialog_content = "그럼 한번 해 볼게요.",
  ui_story_5089_50890302_82_dialog_content = "구야, 우리가 처음 쌍사성에 갔을 때 내가 너에게 하였던 말을 기억하느냐.",
  ui_story_5089_50890302_83_dialog_content = "언젠가 피아노 악사와 합주하게 되거든, 네가 곁에서 검무를 췄으면 좋겠다고 했었지.",
  ui_story_5089_50890302_84_dialog_content = "이, 이렇게 많은 이들 앞에서 말입니까...?",
  ui_story_5089_50890302_85_dialog_content = "너뿐만 아니라 우리 모두가 있지 않느냐.",
  ui_story_5089_50890302_86_dialog_content = "아, 만약 네가 정말 원하지 않는다면 나도 강요하지 않으마.\n다만 오늘 이 음악에 소리가 다소 모자라게 되겠지.",
  ui_story_5089_50890302_87_dialog_content = "아, 알겠습니다...",
  ui_story_5089_50890302_88_dialog_content = "그럼 하찮은 재주나마 선보여 보겠습니다.",
  ui_story_5089_50890302_89_dialog_content = "후훗, 구야, 보아라. 저 아이들의 눈이 하나같이 반짝이고 있구나.",
  ui_story_5089_50890302_90_dialog_content = "네 검무는 틀림없이 천하제일일 게야.",
  ui_story_5089_50890302_91_dialog_content = "과찬이십니다. 제 조잡한 무예로는 보는 이들의 눈을 더럽힐 뿐입니다.",
  ui_story_5089_50890302_92_dialog_content = "연주도 있고, 검무도 있는데, 허면 소생은 무엇을 하는 게 좋겠습니까?",
  ui_story_5089_50890302_93_dialog_content = "아니면 소생도 노래를 불러 이 자리의 흥을 돋워보도록 하지요.",
  ui_story_5089_50890302_94_dialog_content = "호오? 어떤 곡조를 부를 수 있느냐.",
  ui_story_5089_50890302_95_dialog_content = "크흠, 자, 그럼 다들 잘 보십시오.",
  ui_story_5089_50890302_96_dialog_content = "각지에서 온 여러분께 오늘 여기서 기예를 보여드리도록 하겠습니다.",
  ui_story_5089_50890302_97_dialog_content = "돈이 없으면 자리만 채워 주십시오. 돈이 좀 있으신 분은 인심도 좀 써 주시고 말입니다.",
  ui_story_5089_50890302_98_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5089_50890302_99_dialog_content = "<color=#e8d9bb>말이 끝나자, 모여든 백성들 중 일부가 동전 몇 개를 던져주었다.</color>",
  ui_story_5089_50890302_100_dialog_content = "이천간!",
  ui_story_5089_50890302_101_dialog_content = "아이고, 전하! 자, 진정하고 연주를 하시지요.",
  ui_story_5089_50890302_102_dialog_content = "<color=#e8d9bb>은은하게 다가오는 비바람, 임시로 준비된 합주, 각자 복잡한 마음을 가진 동료들.</color>",
  ui_story_5089_50890302_103_dialog_content = "<color=#e8d9bb>결코 완벽하다고는 할 수 없을 즉흥적인 연주였다.</color>",
  ui_story_5089_50890302_104_dialog_content = "<color=#e8d9bb>그러나 적어도, 지금 이 순간만큼은──</color>",
  ui_story_5089_50890302_105_dialog_content = "<color=#e8d9bb>그 광경은 노래가 되었다.</color>",
  ui_story_5089_50890401_1_dialog_content = "PlayerName 공자, 계속 손에 쥐고 만지작거리는 그것은 무에냐.",
  ui_story_5089_50890401_2_dialog_content = "이 인형 말이죠? 방금 헤어지기 전에 이구가 준 거예요.",
  ui_story_5089_50890401_3_dialog_content = "구 씨가 소화한테 가면을 하나 주니까 장난감은 필요 없다고 하더라고요.\n그래서 이구가 물건을 다 돌려줬어요.",
  ui_story_5089_50890401_4_dialog_content = "그리고 사과의 뜻으로 저한테 이걸 줬고요.",
  ui_story_5089_50890401_5_dialog_content = "「마합라」라는 장난감인데, 걔 말로는 얼마 전에 마을을 지나던 어떤 누나가\n준 거라고 하더라고요.",
  ui_story_5089_50890401_6_dialog_content = "그 누나 옆에는 검은 옷 입은 사람들이 많이 따라다녔는데, 말도 별로 안 하고 무서웠어.",
  ui_story_5089_50890401_7_dialog_content = "근데 그 누나는 좋은 사람이었어. 우릴 큰 식당에 초대해서 고기도 많이 먹게 해 줬어!",
  ui_story_5089_50890401_8_dialog_content = "그리고 그 누나는 뭐든지 다 만들 수 있어.\n골목의 그 함정도 누나가 그린 도면대로 만든 거야.",
  ui_story_5089_50890401_9_dialog_content = "그게 다 기관술의 기본이고, 잘 배우면 똑똑해진댔어.",
  ui_story_5089_50890401_10_dialog_content = "혹시 그 사람 이름 들었어?",
  ui_story_5089_50890401_11_dialog_content = "아니, 마을엔 하루만 있다가 가버렸거든. 근데... 아, 맞다.",
  ui_story_5089_50890401_12_dialog_content = "그 누나 사실 좀 이상했어.\n비가 오는 날씨가 아닌데도 하루 종일 아주 큰 우산을 들고 다녔거든.",
  ui_story_5089_50890401_13_dialog_content = "어째 우리가 아는 누구 얘기 같지 않아요?",
  ui_story_5089_50890401_14_dialog_content = "이 길은 제나라에서 업나라로 돌아가는 가장 빠른 길이니,\n선기경도 이곳을 지났을 가능성이 있겠지.",
  ui_story_5089_50890401_15_dialog_content = "고기도 먹고, 술도 마시고, 아이들과 장난도 치고, 심지어 무기까지 들고 다니다니...",
  ui_story_5089_50890401_16_dialog_content = "조정의 중죄인이라는 사람이 꽤 괜찮은 나날을 보내고 있는 것처럼 들리는구나.",
  ui_story_5089_50890401_17_dialog_content = "근데 검은 옷 입은 사람들이 따라다니면 자유롭게 움직일 수 없겠죠.",
  ui_story_5089_50890401_18_dialog_content = "PlayerName 공자, 그 인형을 잠시 빌려줄 수 있느냐.",
  ui_story_5089_50890401_19_dialog_content = "여기요, 근데 저도 한참 살펴보고, 감응도 해 봤는데, 아무것도 못 찾았어요.",
  ui_story_5089_50890401_20_dialog_content = "어쩌면 정보가 있다 하여도 인형에 숨겨져 있을지도 모르겠구나...",
  ui_story_5089_50890401_21_dialog_content = "<color=#e8d9bb>깊은 밤</color>",
  ui_story_5089_50890401_22_dialog_content = "하아암~",
  ui_story_5089_50890401_23_dialog_content = "(목이 건조하네... 물 좀 마셔야지...)",
  ui_story_5089_50890401_24_dialog_content = "(찻주전자가 비었잖아? 거실로 가 봐야겠네.)",
  ui_story_5089_50890401_25_dialog_content = "(어라? 저긴 단당 씨 방일 텐데, 불이 아직도 켜져 있잖아?)",
  ui_story_5089_50890401_26_dialog_content = "PlayerName 공자인가.",
  ui_story_5089_50890401_27_dialog_content = "어? 단당 씨, 저 보였어요?",
  ui_story_5089_50890401_28_dialog_content = "발소리만 들어도 알 수 있다. 들어오거라.",
  ui_story_5089_50890401_29_dialog_content = "탁자 위에 그건... 아직도 그 인형을 조사하고 있었던 거예요?",
  ui_story_5089_50890401_30_dialog_content = "그러한 상황에서 선기경이 남긴 물건이라면, 의도가 아니라도 필시\n모종의 정보를 담고 있을 게야.",
  ui_story_5089_50890401_31_dialog_content = "그나저나 「마합라」가 대체 뭐죠?",
  ui_story_5089_50890401_32_dialog_content = "예전에 유행했던 장난감이다. 보통 흙이나 나무로 인형을 조각하고, 금속은 사용하지 않지.",
  ui_story_5089_50890401_33_dialog_content = "근데 이건 구리로 만들었잖아요?",
  ui_story_5089_50890401_34_dialog_content = "선기경은 구리를 잘 다룬다. 선기경이 처음으로 두각을 나타낸 것도 바로\n연주하는 구리 인형을 만들었을 때였지.",
  ui_story_5089_50890401_35_dialog_content = "선기경이 구리 인형들과 함께 악곡을 연주했지만, 아무도 이상함을 발견하지 못했고,\n공연이 끝난 뒤에야 관객들은 연주자들이 전부 인형이었음을 알았다.",
  ui_story_5089_50890401_36_dialog_content = "선극 씨가 그렇게 대단한 인형을 만들 수 있단 말이에요?\n...근데 왜 이 인형은 이렇게 못생겼죠?",
  ui_story_5089_50890401_37_dialog_content = "그것이 바로 내가 말하고 싶은 또 다른 의문점이다.",
  ui_story_5089_50890401_38_dialog_content = "「마합라」는 본디 아름답고 귀여운 아이의 모습이어야 하거늘,\n선기경은 오히려 이를 요마처럼 추하게 만들고 주름살까지 더했다.",
  ui_story_5089_50890401_39_dialog_content = "또한 「마합라」의 손에는 연잎이나 연꽃을 들고 있어야 한다.",
  ui_story_5089_50890401_40_dialog_content = "그러나 이 인형은 손에 꽃을 들고 있으나, 자세히 보면 이곳은 목란화다.",
  ui_story_5089_50890401_41_dialog_content = "하나는 물에서 태어났고, 다른 하나는 물에 잠기는 것을 두려워하니,\n이는 서로 어우러질 수 없는 물과 불의 사이라.",
  ui_story_5089_50890401_42_dialog_content = "이 인형은 「마합라」와 닮은 듯하면서도 많은 곳이 다르니,\n이는 가짜 대역이라고 할 수밖에 없다.",
  ui_story_5089_50890401_43_dialog_content = "가짜... 대역...?",
  ui_story_5089_50890401_44_dialog_content = "또한 예전에 「마합라」라는 연극이 있었다.",
  ui_story_5089_50890401_45_dialog_content = "대부분의 이들은 이 연극에 대해 잘 알지 못하나, 그중의 가사 한 구절이 널리 퍼져\n누구나 알 만큼 유명해졌지.",
  ui_story_5089_50890401_46_dialog_content = "어떤 구절인데요?",
  ui_story_5089_50890401_47_dialog_content = "「범의 가죽은 그려도 뼈는 그리지 못하고, 사람의 얼굴은 알아도 마음은 알지 못한다.」",
  ui_story_5089_50890401_48_dialog_content = "<color=#e8d9bb>휘익!</color>",
  ui_story_5089_50890401_49_dialog_content = "!",
  ui_story_5089_50890401_50_dialog_content = "누가 밖에 있다!",
  ui_story_5089_50890402_1_dialog_content = "대적할 수 없으면 도망치는 것인가, 오늘 보니 저들의 실력을 익히 알겠구나.",
  ui_story_5089_50890402_2_dialog_content = "저 사람들이 「천명」인가요? 아니면...",
  ui_story_5089_50890402_3_dialog_content = "모르겠구나.",
  ui_story_5089_50890402_4_dialog_content = "허나 현 상황에서는 「천명」이든 업나라의 밀정이든 별반 차이가 없겠지.",
  ui_story_5089_50890402_5_dialog_content = "다행히 방금 그자들은 수도 적고 무예도 그리 뛰어나지 못했다.",
  ui_story_5089_50890402_6_dialog_content = "오직 도주 기술만은 일류인 것을 보아, 소식을 알아보러 온 척후병일 게야.",
  ui_story_5089_50890402_7_dialog_content = "그럼 우리 위치가 노출됐다는 거잖아요? 얼른 자리를 피하는 게 좋지 않을까요?",
  ui_story_5089_50890402_8_dialog_content = "PlayerName 공자, 무언가 이상한 점을 찾지 못했느냐.",
  ui_story_5089_50890402_9_dialog_content = "무슨... 앗!",
  ui_story_5089_50890402_10_dialog_content = "저희가 이렇게 난장판으로 만든 건가요... 그리고 구 씨는요?",
  ui_story_5089_50890402_11_dialog_content = "보낸 놈들이 왜 아직도 안 오는 거지? 설마 죽은 건 아니겠지?",
  ui_story_5089_50890402_12_dialog_content = "이런 작은 일조차 제대로 못 한다면 죽어도 싸지.",
  ui_story_5089_50890402_13_dialog_content = "휴, 우리 목숨값이 싼 것을 탓해야겠지. 알 게 뭐야. 뒷간 좀 다녀와야겠다.",
  ui_story_5089_50890402_14_dialog_content = "움직이지 마라.",
  ui_story_5089_50890402_15_dialog_content = "!",
  ui_story_5089_50890402_16_dialog_content = "아, 알겠습니다. 대협, 조급해하지 마십시오.",
  ui_story_5089_50890402_17_dialog_content = "이렇게 소리 없이 몰래 침입해서 제 목에 검을 겨눌 수 있는 정도라면,\n전 분명히 당신 상대가 안 되겠지요.",
  ui_story_5089_50890402_18_dialog_content = "그러니 일단 이 검부터 좀 치워 주십시오.\n이러다 실수로 제 목이 베이면 아무것도 못 물어보실 겁니다.",
  ui_story_5089_50890402_19_dialog_content = "너흰 무슨 명령을 받았고, 여기서 뭘 하고 있었지?",
  ui_story_5089_50890402_20_dialog_content = "그 말씀은...",
  ui_story_5089_50890402_21_dialog_content = "군말 말고 질문에 대답해라.",
  ui_story_5089_50890402_22_dialog_content = "아, 알겠습니다. 저희는 가문을 나와 말썽을 피우는 아가씨를 데려오라는\n저희 주인님의 명령을 받았습니다.",
  ui_story_5089_50890402_23_dialog_content = "그저 한 집안의 일일 뿐입니다. 불법도 아니고 말이지요.",
  ui_story_5089_50890402_24_dialog_content = "이런 싸움을 하는 「집안일」도 있나?",
  ui_story_5089_50890402_25_dialog_content = "휴, 저희 주인님 가세가 좀 커야 말이지요.\n게다가 아가씨 곁에 고강한 호위무사가 있지 뭡니까.",
  ui_story_5089_50890402_26_dialog_content = "그 호위도 사실 저희 주인님이 보내신 사람인데,\n뭘 잘못 먹었는지 아가씨랑 같이 말썽을 피우기 시작했습니다.",
  ui_story_5089_50890402_27_dialog_content = "그래서 주인님께서 무척 실망하셨지요.",
  ui_story_5089_50890402_28_dialog_content = "......",
  ui_story_5089_50890402_29_dialog_content = "물론 저도 말씀드렸습니다. 어디까지나 「집안일」이고, 혈육의 정을 생각하시라고 말입니다.",
  ui_story_5089_50890402_30_dialog_content = "주인님께서 화가 나신 건 이해하지만, 아가씨를 정말로 해칠 순 없는 노릇 아니겠습니까.",
  ui_story_5089_50890402_31_dialog_content = "아가씨가 아무리 철이 없다 한들, 데려가서 외출을 금하고 반성문 정도나 쓰면 족할 일입니다.",
  ui_story_5089_50890402_32_dialog_content = "그런데 하필 그 호위무사가 본분을 잊고 주인님의 대사를 망치려 드는 게 아니겠습니까.",
  ui_story_5089_50890402_33_dialog_content = "주인님께서 애써 오랫동안 길러 왔는데, 이제 보니 배은망덕한 늑대였다니,\n대협께선 이를 어찌 생각...",
  ui_story_5089_50890402_34_dialog_content = "어? 대협? 어디 가셨습니까?",
  ui_story_5089_50890402_35_dialog_content = "훗.",
  ui_story_5089_50890402_36_dialog_content = "뭐야, 왜 이리 오래 걸렸어?",
  ui_story_5089_50890402_37_dialog_content = "아는 사람을 만났거든. 얘기 좀 하느라 늦었다.",
  ui_story_5089_50890402_38_dialog_content = "심부름꾼이 돌아오거든 전해.",
  ui_story_5089_50890402_39_dialog_content = "내일 군주 전하를 모시고 돌아갈 거라고 말이야.",
  ui_story_5089_50890402_40_dialog_content = "만약 저 귀면의 염라가 막아선다면, 반역으로 처리할 것이다.",
  ui_story_5089_50890402_41_dialog_content = "죽여라.",
  ui_story_5089_50890402_42_dialog_content = "...군주 전하, PlayerName 님, 어찌 모두 밖에 계십니까?",
  ui_story_5089_50890402_43_dialog_content = "구 씨, 어디 갔었어요? 저희 방금...",
  ui_story_5089_50890402_44_dialog_content = "...PlayerName 공자.",
  ui_story_5089_50890402_45_dialog_content = "이미 늦었으니 돌아가서 쉬도록 해라.",
  ui_story_5089_50890402_46_dialog_content = "나는 조금 더 생각할 일이 있다.",
  ui_story_5089_50890402_47_dialog_content = "...네.",
  ui_story_5089_50890402_48_dialog_content = "잘 자요, 단당 씨, 구 씨.",
  ui_story_5089_50890402_49_dialog_content = "편히 쉬거라.",
  ui_story_5089_50890402_50_dialog_content = "......",
  ui_story_5089_50890402_51_dialog_content = "<color=#e8d9bb>다음날</color>",
  ui_story_5089_50890402_52_dialog_content = "잠시 시간을 내어줄 수 있겠나, 이 대사.",
  ui_story_5089_50890402_53_dialog_content = "어이쿠... 소생이 아직 잠이 덜 깬 모양입니다. 아니면 오늘은 해가 서쪽에서 떴답니까?",
  ui_story_5089_50890402_54_dialog_content = "군주 전하께서 어인 일로 이토록 정중하게 말씀을 하십니까?",
  ui_story_5089_50890402_55_dialog_content = "그대에게 점을 쳐 달라고 부탁하고 싶다.",
  ui_story_5089_50890402_56_dialog_content = "그건 정말 드문 일이군요.",
  ui_story_5089_50890402_57_dialog_content = "천지와 길흉을 점치시겠습니까? 아니면 인연을 찾으시겠습니까?",
  ui_story_5089_50890402_58_dialog_content = "나는... 앞길을 묻고 싶다.",
  ui_story_5089_50890402_59_dialog_content = "어떤 일이 하나 있는데, 그것을 하는 게 좋을지, 그리고 할 수 있을지 모르겠구나.",
  ui_story_5089_50890402_60_dialog_content = "예, 알겠습니다. 허면 소생이 점괘를 뽑을 수 있도록 손을 좀 내밀어 주십시오.",
  ui_story_5089_50890402_61_dialog_content = "알겠다.",
  ui_story_5089_50890402_62_dialog_content = "<color=#e8d9bb>촤악──</color>",
  ui_story_5089_50890402_63_dialog_content = "<color=#e8d9bb>두 개의 산가지가 단당의 손에 떨어졌다. 그러나 그녀가 자세히 보기도 전에...</color>",
  ui_story_5089_50890402_64_dialog_content = "<color=#e8d9bb>이천간은 산통 안의 산가지를 전부 쏟아내 버렸다.</color>",
  ui_story_5089_50890402_65_dialog_content = "이 대사, 이것은 무슨 의미인가.",
  ui_story_5089_50890402_66_dialog_content = "휴, 계속 그렇게 부르시니까 불편해서 못 참겠습니다.\n이천간이라고 부르십시오. 아니면 이 사기꾼도 괜찮습니다.",
  ui_story_5089_50890402_67_dialog_content = "자, 이 산가지는 비록 보잘것없지만, 소생은 강호를 누비며 이것들로 먹고살고 있습니다.",
  ui_story_5089_50890402_68_dialog_content = "믿는 자는 화근을 풀어주고 재난을 피하도록 돕습니다.",
  ui_story_5089_50890402_69_dialog_content = "못 믿는 자라면 말이나 좀 해 보고, 믿거나 말거나 알아서 하라고 하면 되지요.",
  ui_story_5089_50890402_70_dialog_content = "허나 전하께서는 제게 점괘를 묻지만, 의심도 하십니다.\n앞길을 위해 하늘의 뜻을 구하면서도, 순순히 명에 따라 행할 마음은 없지요.",
  ui_story_5089_50890402_71_dialog_content = "이러한 행동은 소생의 점판을 엎는 일이나 다름이 없습니다.",
  ui_story_5089_50890402_72_dialog_content = "...그렇게까지 말할 필요가 있는가.",
  ui_story_5089_50890402_73_dialog_content = "소생은 그리 생각하지 않습니다.",
  ui_story_5089_50890402_74_dialog_content = "처음에 산가지 두 개가 떨어졌을 때, 전하께선 이미 원하던 결과를 얻지 않으셨습니까?",
  ui_story_5089_50890402_75_dialog_content = "......",
  ui_story_5089_50890402_76_dialog_content = "보십시오, 제가 뭐랬습니다.\n위풍당당한 작화군주께서는 천명을 믿지 않는다고 누구나 알고 있습니다.",
  ui_story_5089_50890402_77_dialog_content = "마음속으로 이미 결단을 내리셨다면, 심심풀이로 소생을 찾으실 필요는 없습니다.",
  ui_story_5089_50890402_78_dialog_content = "뭐, 그건 그렇고 제 산가지 좀 주워 주십시오.",
  ui_story_5089_50890402_79_dialog_content = "이 대사.",
  ui_story_5089_50890402_80_dialog_content = "아니, 전하, 이미 합의가 된 거 아니었습니까? 왜 아직도 그렇게 부르십니까?",
  ui_story_5089_50890402_81_dialog_content = "부탁할 일이 하나 더 있기 때문있다.",
  ui_story_5089_50890402_82_dialog_content = "...소생이 잘못했습니다. 아까 한 말은 취소하겠습니다.",
  ui_story_5089_50890402_83_dialog_content = "자, 손을 내밀어 주십시오. 소생이 점을 다시 봐 드리겠습니다.\n다만 이 일은 본디 해서는 안 되는 일입니다.",
  ui_story_5089_50890402_84_dialog_content = "유감이지만 나는 작화군주다.",
  ui_story_5089_50890402_85_dialog_content = "내가 천명을 믿지 않음은 누구나 알고 있다.",
  ui_story_5089_50890402_86_dialog_content = "자업자득이네.",
  ui_story_5089_50890402_87_dialog_content = "자기 발등을 찍었네!",
  ui_story_5089_50890402_88_dialog_content = "휴... 알겠습니다. 이게 다 소생이 목숨을 빚진 탓이지요.",
  ui_story_5089_50890402_89_dialog_content = "허면 어떻게 하실 것인지 말씀해 주십시오.",
  ui_story_5089_50890402_90_dialog_content = "단당 씨, 말씀하신 대로 표국에 다녀왔어요.",
  ui_story_5089_50890402_91_dialog_content = "세자가 준 금은 전부 표국에 맡겨서 왕성으로 먼저 보냈어요.",
  ui_story_5089_50890402_92_dialog_content = "이제 어떡하죠? 우리도 갈까요?",
  ui_story_5089_50890402_93_dialog_content = "서두를 것 없다.",
  ui_story_5089_50890402_94_dialog_content = "아까 객잔 주인이 새로 차 두 봉지를 가져왔는데, 맛이 괜찮더구나.\n앉아서 한잔하고 가도 될 것이야.",
  ui_story_5089_50890402_95_dialog_content = "진짜 그렇게 여유 부려도 돼요?",
  ui_story_5089_50890402_96_dialog_content = "괜찮다. 오래 걸리지 않을 게다.",
  ui_story_5089_50890402_97_dialog_content = "구야, 있느냐.",
  ui_story_5089_50890402_98_dialog_content = "...예.",
  ui_story_5089_50890402_99_dialog_content = "너도 와서 차 한 잔 마시거라. 다 마시면 네게 할 말이 있다.",
  ui_story_5089_50890402_100_dialog_content = "예.",
  ui_story_5089_50890402_101_dialog_content = "차가 진짜 맛있네요. 은은하면서도 상쾌해요.\n그리고 왜 다른 차엔 없는 과일 향이 나는 걸까요?",
  ui_story_5089_50890402_102_dialog_content = "미독수과로 만든 「한맥산」을 넣었기 때문이다.",
  ui_story_5089_50890402_103_dialog_content = "...네?",
  ui_story_5089_50890402_104_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_5089_50890402_105_dialog_content = "<color=#e8d9bb>구가 갑자기 한쪽 무릎을 꿇고 쓰러졌다.</color>",
  ui_story_5089_50890402_106_dialog_content = "구...구 씨!",
  ui_story_5089_50890402_107_dialog_content = "괜찮다, 이 약은 인체를 마비시켜 움직일 수 없게 할 뿐이고, 해를 끼치지는 않는다.\n시간이 지나면 자연히 회복될 것이야.",
  ui_story_5089_50890402_108_dialog_content = "다만 내공이 깊고 무예가 고강한 자일수록 중독이 빠르고, 오래 지속된다.",
  ui_story_5089_50890402_109_dialog_content = "그래서 전 아무 느낌도... 아니, 지금 이게 중요한 게 아니죠...",
  ui_story_5089_50890402_110_dialog_content = "왜 이러시는 건데요?",
  ui_story_5089_50890402_111_dialog_content = "시간이 없기 때문이다.",
  ui_story_5089_50890402_112_dialog_content = "전하, 많은 이들이 지금 객잔을 향해 오고 있다고 다언, 다어가 확인했습니다.",
  ui_story_5089_50890402_113_dialog_content = "좋은 의도로 오는 것 같진 않군요.",
  ui_story_5089_50890402_114_dialog_content = "천간 씨도... 다, 당신 누구야?!",
  ui_story_5089_50890402_115_dialog_content = "누가 봐도 틀림없는 구 소저이옵니다.",
  ui_story_5089_50890402_116_dialog_content = "전혀 틀리잖아요!",
  ui_story_5089_50890402_117_dialog_content = "이런 상황에서 사소한 트집은 잡지 마시지요.",
  ui_story_5089_50890402_118_dialog_content = "이게 제 문제인가요?!",
  ui_story_5089_50890402_119_dialog_content = "미안하지만 소생이 구 소저를 저기 벽장에 숨길 수 있게 좀 도와주십시오. 서둘러야 합니다.",
  ui_story_5089_50890402_120_dialog_content = "아, 알겠어요... 아니, 뭐라고요?",
  ui_story_5089_50890402_121_dialog_content = "어째서...",
  ui_story_5089_50890402_122_dialog_content = "<color=#e8d9bb>구의 몸은 미약하게 떨렸고, 약효에 맞서려고 안간힘을 쓰는 듯 뼈에서 소리가 들릴 정도였다.</color>",
  ui_story_5089_50890402_123_dialog_content = "<color=#e8d9bb>손의 상처가 갈라지고, 피가 옷에 스며들었다.</color>",
  ui_story_5089_50890402_124_dialog_content = "<color=#e8d9bb>그녀는 굳어진 몸을 움직여 마침내 단당의 한쪽 치맛자락을 붙잡았다.</color>",
  ui_story_5089_50890402_125_dialog_content = "......",
  ui_story_5089_50890402_126_dialog_content = "<color=#e8d9bb>그러나 단당은 한발 물러서며 구의 손을 떨쳐냈다.</color>",
  ui_story_5089_50890402_127_dialog_content = "함께 지낸 지난 오 년간, 너는 나를 위해 많은 일을 해 주었다. 참으로 고맙다.",
  ui_story_5089_50890402_128_dialog_content = "너는 훌륭한 소저였고, 가장 유능한 부하였다.",
  ui_story_5089_50890402_129_dialog_content = "허나 이제 더는 가장된 태평을 이어갈 수 없게 되었구나.",
  ui_story_5089_50890402_130_dialog_content = "물론 너는 나를 해치고 싶지 않겠지만, 숙부의 명을 거역하지도 않을 것이야.",
  ui_story_5089_50890402_131_dialog_content = "너는 두 개의 상반된 길을 갈 수 없다. 동시에 두 사람의 손에 쥐인 검이 될 수도 없지.",
  ui_story_5089_50890402_132_dialog_content = "군주... 전하...",
  ui_story_5089_50890402_133_dialog_content = "사실 이는 내가 안배해야 할 일이 아니다. 이것은 네가 스스로 선택해야 할 일이다.",
  ui_story_5089_50890402_134_dialog_content = "허나 네가 선택하고 싶지 않다면, 나처럼 누군가는 그 권리를 취하려 할 것이야.",
  ui_story_5089_50890402_135_dialog_content = "행동의 자유를 포기하면, 자연히 남에게 휘둘리는 인형이 될 수밖에 없다.",
  ui_story_5089_50890402_136_dialog_content = "보거라. 이제 어떻게 할지는 이미 네 의사에 달리지 않게 되었다.",
  ui_story_5089_50890402_137_dialog_content = "구야.",
  ui_story_5089_50890402_138_dialog_content = "오늘부터 나는 네 작화군주 호위 신분을 해제하겠다.",
  ui_story_5089_50890402_139_dialog_content = "!",
  ui_story_5089_50890402_140_dialog_content = "나는 지금의 네가 필요하지도 않고, 감히 그럴 수도 없다.",
  ui_story_5089_50890402_141_dialog_content = "이제 더는 네 보호를 받으면서, 감시도 받는 군주가 될 생각은 없다.",
  ui_story_5089_50890402_142_dialog_content = "내가 원하는 것은──",
  ui_story_5089_50890402_143_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5089_50890402_144_dialog_content = "<color=#e8d9bb>단당의 마지막 말은 바깥의 큰 소리에 파묻혀 버렸다.</color>",
  ui_story_5089_50890402_145_dialog_content = "자, 들어가시지요~",
  ui_story_5089_50890402_146_dialog_content = "?",
  ui_story_5089_50890402_147_dialog_content = "<color=#e8d9bb>당신도 벽장에 밀려들어 가고 말았다.</color>",
  ui_story_5089_50890402_148_dialog_content = "미안하구나. PlayerName 공자, 이번 일은 내가 독단으로 정한 것이야.",
  ui_story_5089_50890402_149_dialog_content = "허나 구와 향후의 일은 모두 그대에게 부탁할 수밖에 없겠구나.",
  ui_story_5089_50890402_150_dialog_content = "잠깐만요, 단당 씨!",
  ui_story_5089_50890402_151_dialog_content = "<color=#e8d9bb>옷장 문이 닫혔다.</color>",
  ui_story_5089_50890402_152_dialog_content = "<color=#e8d9bb>그리고 그다음 순간, 방의 문이 세차게 열렸다.</color>",
  ui_story_5089_50890402_153_dialog_content = "휴, 군주 마마, 참으로 모시기가 힘들군요.",
  ui_story_5089_50890402_154_dialog_content = "(이 목소리!)",
  ui_story_5089_50890402_155_dialog_content = "호련...",
  ui_story_5089_50890402_156_dialog_content = "선기경의 말이 맞았군. 정말 살아있었나.",
  ui_story_5089_50890402_157_dialog_content = "아직 최강의 기관수를 만들지 못했는데, 제가 어떻게 죽을 수가 있겠어요?",
  ui_story_5089_50890402_158_dialog_content = "일전에는 미처 묻지 못했으나, 상황은 이미 자명해졌구나. 역시 너도 「천명」의 일원이렷다.",
  ui_story_5089_50890402_159_dialog_content = "제 기관술을 지지하는 사람이 제 주인이 되는 건 당연한 일 아닌가요?",
  ui_story_5089_50890402_160_dialog_content = "허나 모처럼 촉음화를 손에 넣었고, 전 새로운 비채의 동력 체계를 조정하느라 바쁩니다.",
  ui_story_5089_50890402_161_dialog_content = "그런데도 이 녀석들은 굳이 절 데려와서 당신을 맞이하라 하더군요.",
  ui_story_5089_50890402_162_dialog_content = "뭐, 그 대가로 좋은 약속을 받긴 했지만요.",
  ui_story_5089_50890402_163_dialog_content = "만약 당신이 옆에 있는 호위와 반항한다면, 전 이곳에서 신무기의 실전 실험을 진행할 겁니다.",
  ui_story_5089_50890402_164_dialog_content = "그러니 좀 반항해 주실 수 있을까요?",
  ui_story_5089_50890402_165_dialog_content = "내 어찌 반항하겠느냐.",
  ui_story_5089_50890402_166_dialog_content = "나는 업나라의 작화군주다. 너는 제쳐두더라도, 나머지는 모두 내 숙부의 사람들이다.",
  ui_story_5089_50890402_167_dialog_content = "저들은 그저 날 맞이하여 집에 갈 뿐, 나를 해치지 않느니라. 그렇지 않느냐, 구야.",
  ui_story_5089_50890402_168_dialog_content = "[끄덕인다]",
  ui_story_5089_50890402_169_dialog_content = "휴, 됐어요. 그럼 얼른 가죠. 공방 쪽은 아직 바쁘니까요.",
  ui_story_5089_50890402_170_dialog_content = "잠시만 기다리십시오. 군주 전하 곁엔 두 사람이 더 있을 텐데요.",
  ui_story_5089_50890402_171_dialog_content = "그 점쟁이 사기꾼은 인기척을 듣고 일찌감치 도망쳤다.",
  ui_story_5089_50890402_172_dialog_content = "그리고 그 아이테르라면 홀로는 아무것도 할 수 없는 자이거늘, 무에 그리 걱정되느냐.",
  ui_story_5089_50890402_173_dialog_content = "또한 내 짐작이 옳다면, 숙부의 명령은 단지 「나」를 데려가는 것이지 않느냐.",
  ui_story_5089_50890402_174_dialog_content = "예... 군주 전하, 그럼 가시지요.",
  ui_story_5089_50890402_175_dialog_content = "<color=#e8d9bb>방은 다시 고요해졌다.</color>",
  ui_story_5089_50890402_176_dialog_content = "<color=#e8d9bb>다만 이번에는 당신과 구, 두 사람만이 남았다.</color>",
  ui_story_5089_50890501_1_dialog_content = "...저 두 사람 대체 뭘 어쩌려는 거죠?!",
  ui_story_5089_50890501_2_dialog_content = "자유롭게 움직일 시간을 벌겠다더니, 정작 꼼짝도 못 하고 알아서 잡혀버렸잖아요!",
  ui_story_5089_50890501_3_dialog_content = "호련 같은 위험한 녀석까지 섞여 있는데, 어떻게 안전을 보장할 수 있겠어요?!",
  ui_story_5089_50890501_4_dialog_content = "구 씨도 이상하다고 생각 안 해요?!",
  ui_story_5089_50890501_5_dialog_content = "저는... 모르겠습니다.",
  ui_story_5089_50890501_6_dialog_content = "전하께서는 이제 더는 절 믿지 않으시는 것 같습니다.",
  ui_story_5089_50890501_7_dialog_content = "어쩌면 전하의 말씀처럼, 전 사실 제 직무를 철저히 저버린 것일지도 모릅니다.",
  ui_story_5089_50890501_8_dialog_content = "그리고 저는 이제 더는 군주 전하의 호위가 아닙니다. 무엇을 해야 할지도...",
  ui_story_5089_50890501_9_dialog_content = "그게 무슨 바보 같은 말이에요? 적어도 반드시 해야 할 일이 하나 있잖아요.",
  ui_story_5089_50890501_10_dialog_content = "네?",
  ui_story_5089_50890501_11_dialog_content = "단당 씨는 시간이 없다고 했어요.",
  ui_story_5089_50890501_12_dialog_content = "하지만 분명히 전에 배에서는 그렇게 급하지 않았어요.\n그리고 구 씨가 망설이는 것도 이해할 수 있다고 했었고요.",
  ui_story_5089_50890501_13_dialog_content = "그런데 어젯밤 뒤로 태도가 갑자기 달라졌어요.",
  ui_story_5089_50890501_14_dialog_content = "아마 단서는 선극 씨가 준 그 인형에 있을 거예요.",
  ui_story_5089_50890501_15_dialog_content = "게다가 단당 씨는 저한테 아무것도 안 알려줬으면서, 나머지는 저한테 부탁한다니...",
  ui_story_5089_50890501_16_dialog_content = "아무튼 지금 있는 단서로 어떻게든 선극 씨를 만나면 진상을 알아낼 수 있을 거예요.",
  ui_story_5089_50890501_17_dialog_content = "그리고 구 씨는 단당 씨랑 좀 싸워야 돼요.",
  ui_story_5089_50890501_18_dialog_content = "군주 전하와 싸우다니요... 어찌 그런 참람한 짓을 할 수 있겠습니까!",
  ui_story_5089_50890501_19_dialog_content = "근데 단당 씨는 이제 구 씨 주인도 아니잖아요.",
  ui_story_5089_50890501_20_dialog_content = "그렇다고 해도...",
  ui_story_5089_50890501_21_dialog_content = "아무리 무슨 이유나 어려움이 있었다곤 해도, 일방적으로 그렇게 결정을 해버렸잖아요.",
  ui_story_5089_50890501_22_dialog_content = "솔직히 저도 좀 화가 났어요.",
  ui_story_5089_50890501_23_dialog_content = "이렇게 낯선 곳에 버려진 것도 모자라서...",
  ui_story_5089_50890501_24_dialog_content = "아무것도 모른 채 소중한 친구가 자기 안위를 걸고 모험하는 걸 지켜만 봐야 하잖아요.",
  ui_story_5089_50890501_25_dialog_content = "그러니까 이 잡다한 일들이 해결되고 나면 저랑 같이 가요.",
  ui_story_5089_50890501_26_dialog_content = "가서 저 제멋대로인 군주 전하한테 확실하게 따지는 거예요.",
  ui_story_5089_50890501_27_dialog_content = "PlayerName 님...",
  ui_story_5089_50890501_28_dialog_content = "대신 그 전에 절 좀 도와주시겠어요?",
  ui_story_5089_50890501_29_dialog_content = "어쨌든 저 혼자서 할 수 있는 일은 확실히 한계가 있으니까요.",
  ui_story_5089_50890501_30_dialog_content = "저는 어려서부터 대왕 전하의 휘하에서 자랐고, 검을 휘두르며 명령을 따르는 일밖에 모릅니다.",
  ui_story_5089_50890501_31_dialog_content = "만약 이 능력이 유용하게 쓰일 수 있다면, PlayerName 님, 부디 제게 명령해 주십시오.",
  ui_story_5089_50890501_32_dialog_content = "먼저 그런 생각부터 버려요. 그 대신...",
  ui_story_5089_50890501_33_dialog_content = "「우리는 서로 돕는 친구」라는 말을 마음속에 새겨 두세요.",
  ui_story_5089_50890501_34_dialog_content = "...저는 친구를 사귀어 본 적이 없습니다.",
  ui_story_5089_50890501_35_dialog_content = "그 말을 단당 씨가 들으면 아마 우리보다 먼저 화낼걸요.",
  ui_story_5089_50890501_36_dialog_content = "전하는 천금의 몸인데, 어찌 저 같은 사람과 친구라고 할 수... 으윽...",
  ui_story_5089_50890501_37_dialog_content = "휴, 됐어요. 손 이리 주세요. 부축해 줄 테니까 무리하지 말고 저랑 천천히 가요.",
  ui_story_5089_50890501_38_dialog_content = "같이 왕성으로 가는 거예요.",
  ui_story_5089_50890502_1_dialog_content = "크오오──",
  ui_story_5089_50890502_2_dialog_content = "PlayerName 님, 요마를 모두 제거했습니다.",
  ui_story_5089_50890502_3_dialog_content = "여긴 도시에서 그렇게 멀진 않겠네요.",
  ui_story_5089_50890502_4_dialog_content = "왕성까지는 반 시진 정도만 더 가면 됩니다. 그리고 주변에 마을이 몇 개 더 있습니다.",
  ui_story_5089_50890502_5_dialog_content = "용주는 그 사악한 힘을 누르는 대법 덕분에 민가가 있는 곳엔 암귀가 없다고 하지 않았어요?",
  ui_story_5089_50890502_6_dialog_content = "그건...",
  ui_story_5089_50890502_7_dialog_content = "전에 천간 씨도 암귀를 만났다고 했고요.",
  ui_story_5089_50890502_8_dialog_content = "그냥 우연이었으면 좋겠네요... 우린 지금 다른 일에 휘말릴 시간이 없어요. 서두르죠.",
  ui_story_5089_50890502_9_dialog_content = "네.",
  ui_story_5089_50890502_10_dialog_content = "그쪽에 뭐가 있나요?",
  ui_story_5089_50890502_11_dialog_content = "?",
  ui_story_5089_50890502_12_dialog_content = "구 씨 시선이 계속 저쪽으로 가는 것 같아서요.",
  ui_story_5089_50890502_13_dialog_content = "저쪽은 제가 어렸을 때 살던 마을입니다.",
  ui_story_5089_50890502_14_dialog_content = "그럼 구 씨의 고향이란 얘기잖아요? 한번 가 보실래요?",
  ui_story_5089_50890502_15_dialog_content = "그럴 필요 없습니다. 저는 이미 가족이 없고, 마을 사람들도 잘 모릅니다.",
  ui_story_5089_50890502_16_dialog_content = "남은 두 채의 초가집은 이미 집이라고도 할 수 없겠지요.",
  ui_story_5089_50890502_17_dialog_content = "지금은 우리 일이 더 중요합니다.",
  ui_story_5089_50890502_18_dialog_content = "보세요. PlayerName 님, 저곳이 바로 업의 왕성인 경양성입니다.",
  ui_story_5089_50890502_19_dialog_content = "......",
  ui_story_5089_50890502_20_dialog_content = "(나는 금과 옥으로 장식된 제나라 왕궁을 본 뒤로,\n더는 용주의 풍경을 보고 놀라는 일은 없을 줄 알았다.)",
  ui_story_5089_50890502_21_dialog_content = "(그러나 경양성에서는 지붕에 용 모양의 기관이 구름을 뿜어내고,\n거리에는 봉황 모양의 황동 새가 소식을 전하고 있었다.)",
  ui_story_5089_50890502_22_dialog_content = "<color=#e8d9bb>거리는 사방으로 뻗어 있고, 수많은 공방이 눈에 들어왔다.\n그것은 마치 만물이 모여 있는 듯한 번잡한 모습이었다.</color>",
  ui_story_5089_50890502_23_dialog_content = "<color=#e8d9bb>호화롭고 화려한 호진성과는 달리, 이 성의 금속 안에는 정교한 기술의 정수가 담겨 있었다.</color>",
  ui_story_5089_50890502_24_dialog_content = "<color=#e8d9bb>쿠르릉──!</color>",
  ui_story_5089_50890502_25_dialog_content = "무슨 소리죠?!",
  ui_story_5089_50890502_26_dialog_content = "화룡연입니다.",
  ui_story_5089_50890502_27_dialog_content = "PlayerName 님께서는 주변 거리의 지면에서 뭔가 특이한 점을 발견하셨는지요.",
  ui_story_5089_50890502_28_dialog_content = "바닥에 박힌 두 금속 궤도 말인가요? 오는 동안에도 왠지 본 것 같았어요.",
  ui_story_5089_50890502_29_dialog_content = "왠지 낯이 익은 게 제가 아는 물건 같은데...",
  ui_story_5089_50890502_30_dialog_content = "화룡연은 몇 년 전 「후풍」이라는 한 조정의 대인이 개량하신 기관차입니다.",
  ui_story_5089_50890502_31_dialog_content = "수능술과 화능술이 서로 주는 영향을 동력으로 사용해 많은 화물을 싣고도\n차체를 움직일 수 있지요.",
  ui_story_5089_50890502_32_dialog_content = "단점은 동력 소모가 너무 심해 아직은 전용 궤도만 달릴 수 있다는 점입니다.",
  ui_story_5089_50890502_33_dialog_content = "하여 지금은 대부분 왕궁이 일률적으로 계획하여,\n대형 공방의 주인에게 출자해 건설하고 있습니다.",
  ui_story_5089_50890502_34_dialog_content = "철도 건설을 담당하는 공방의 주인은 화룡연을 우선적으로 임차하여\n화물 운송을 진행할 수 있지요.",
  ui_story_5089_50890502_35_dialog_content = "그럼 결국... 증기 기관차라는 거죠?!",
  ui_story_5089_50890502_36_dialog_content = "그것은 무엇인지요.",
  ui_story_5089_50890502_37_dialog_content = "아스트라에 있는 교통수단이에요. 근데 그걸 혼자 만들다니...\n그 후풍경이라는 사람도 정말 대단하네요.",
  ui_story_5089_50890502_38_dialog_content = "군주께서도 같은 말씀을 하셨습니다.",
  ui_story_5089_50890502_39_dialog_content = "후풍경은 그가 만든 물건에서 볼 수 있듯이 재주가 매우 뛰어나며,\n그 소질은 선극 님과 견주어도 손색이 없을 것이라 하셨지요.",
  ui_story_5089_50890502_40_dialog_content = "게다가 공중에서 여러 사람을 안정적으로 태우고 비행할 수 있는 거대한 연도\n시험 제작한 적이 있었다고 합니다.",
  ui_story_5089_50890502_41_dialog_content = "아쉽게도 훗날 당쟁이 벌어지자 죄를 입어 그 종적을 알 수 없게 되었고,\n관련 개발도 중단되고 말았습니다.",
  ui_story_5089_50890502_42_dialog_content = "그거 아쉽네요. 보완만 했어도 엄청난 물건이 됐을 텐데 말이에요.",
  ui_story_5089_50890502_43_dialog_content = "하지만 구 씨는 정말 잘 알고 있네요. 전 구 씨가 이런 쪽에는 관심이 없을 줄 알았거든요.",
  ui_story_5089_50890502_44_dialog_content = "모두 전하께서 제게 말씀해 주신 것입니다.",
  ui_story_5089_50890502_45_dialog_content = "그리고 전하께선 당시 어려서 조정의 일을 알지 못했기에 어쩔 수 없었으나,\n아니었다면 반드시 방법을 찾아 이러한 인재를 남겼을 것이라 하셨지요.",
  ui_story_5089_50890502_46_dialog_content = "하하, 확실히 단당 씨 스타일이네요.",
  ui_story_5089_50890502_47_dialog_content = "자, 그럼 우리도 힘내야죠.",
  ui_story_5089_50890502_48_dialog_content = "업나라가 다시는 선극 씨 같은 인재를, 단당 씨 같은 책임감 있는 공주님을 잃지 않게요.",
  ui_story_5089_50890502_49_dialog_content = "일단 두 사람을 만날 방법부터 생각해야겠네요...",
  ui_story_5089_50890502_50_dialog_content = "대왕 전하께서 직접 명을 내려 체포한 범인은 주로 왕궁 외곽의 감옥에 수감됩니다.",
  ui_story_5089_50890502_51_dialog_content = "비록 지키는 이가 많으나, PlayerName 님께서 도와주신다면 제가 쓰러지는 한이 있더라도\n반드시 선극 님을 구해낼 수 있을 것입니다.",
  ui_story_5089_50890502_52_dialog_content = "시작부터 그런 과감한 방법을 쓰는 건가요?!",
  ui_story_5089_50890502_53_dialog_content = "PlayerName 님께서 도와달라고 하신 것은 제가 당신의 검이 되라는 뜻이 아니었습니까?",
  ui_story_5089_50890502_54_dialog_content = "그렇다고 조정의 범죄자가 될 생각은 없다구요! 구 씨를 죽게 만들 생각은 더더욱 없고요!",
  ui_story_5089_50890502_55_dialog_content = "분명히 다른 방법이 있을 거예요. 일단 그 감옥으로 한번 가 보자구요.",
  ui_story_5089_50890502_56_dialog_content = "만약 저들이 선극 씨를 해치려고 한다면... 그때 최후의 수단을 쓰기로 해요.",
  ui_story_5089_50890502_57_dialog_content = "그나저나 경양성엔 구 씨를 아는 사람이 많겠죠?",
  ui_story_5089_50890502_58_dialog_content = "대왕 전하 곁에 있을 때도 저는 비밀 호위로서 거의 모습을 드러내지 않았고,\n접촉이 있는 것은 기껏해야 동료들뿐이었습니다.",
  ui_story_5089_50890502_59_dialog_content = "하지만 대부분 제 가면만 기억할 것입니다. 아마 제가 남자인지, 여자인지도 잘 모르겠지요.",
  ui_story_5089_50890502_60_dialog_content = "저들이 뒤에서 제 얘기를 할 때는 늘 「귀면의 염라」라고만 불렀으니까요.",
  ui_story_5089_50890502_61_dialog_content = "그러니 PlayerName 님께서 염려하시는 점이 있다면...",
  ui_story_5089_50890502_62_dialog_content = "이렇게 하면 됩니다.",
  ui_story_5089_50890502_63_dialog_content = "음, 알겠어요... 왠지 어떤 의미에선 그게 더 눈에 띌 것 같지만요.",
  ui_story_5089_50890502_64_dialog_content = "역시 제 얼굴은 차마 눈에 담을 수 없는 것이겠지요... 너울로 덮도록 하겠습니다.",
  ui_story_5089_50890502_65_dialog_content = "필요 없어요! 왜 그렇게 생각하는 건데요? 오히려 정반대라구요.\n구 씨는 정말... 저, 정말...",
  ui_story_5089_50890502_66_dialog_content = "<size=28>...아름답단 말이에요.</size>",
  ui_story_5089_50890502_67_dialog_content = "?",
  ui_story_5089_50890502_68_dialog_content = "...됐어요, 이런 일은 신경 쓰지 말고 얼른 가요.",
  ui_story_5089_50890502_69_dialog_content = "이곳은 왕궁의 중요 구역이다. 함부로 출입할 수 없으니 용무가 없다면 물러나라.",
  ui_story_5089_50890502_70_dialog_content = "역시 바로 들어갈 순 없네요.",
  ui_story_5089_50890502_71_dialog_content = "그렇다면 제가 몰래 들어가서...",
  ui_story_5089_50890502_72_dialog_content = "...그 방법은 마지막에 쓰기로 해요!",
  ui_story_5089_50890502_73_dialog_content = "참, 저한테 선극 씨 기관조가 하나 있어요. 경비병만 따돌릴 수 있다면,\n이걸로 선극 씨랑 교신할 수 있을지도 몰라요.",
  ui_story_5089_50890502_74_dialog_content = "경비병을 끌어내는 일은 제가...",
  ui_story_5089_50890502_75_dialog_content = "잠깐만요... 으앗! 안 돼!",
  ui_story_5089_50890502_76_dialog_content = "<color=#e8d9bb>당신은 실수로 방금 꺼낸 기관조를 놓치고 말았다.</color>",
  ui_story_5089_50890502_77_dialog_content = "<color=#e8d9bb>기관조는 사전에 설정된 명령에 따라 선극을 찾기 위해 궐문 쪽으로 곧바로 돌진했다.</color>",
  ui_story_5089_50890502_78_dialog_content = "망했다! ...어라?",
  ui_story_5089_50890502_79_dialog_content = "<color=#e8d9bb>어디선가 한 줄기 금빛이 번쩍였다.</color>",
  ui_story_5089_50890502_80_dialog_content = "<color=#e8d9bb>두 경비병은 아무런 이상을 느끼지 못한 듯 기관조가 문을 지나도록 내버려두었다.</color>",
  ui_story_5089_50890502_81_dialog_content = "...경비병을 끌어내야 할까요?",
  ui_story_5089_50890502_82_dialog_content = "......",
  ui_story_5089_50890502_83_dialog_content = "<color=#e8d9bb>갑자기 궁문 안에서 작은 소리가 들렸다.</color>",
  ui_story_5089_50890502_84_dialog_content = "실례지만 여기 귀한 손님이 계십니까?",
  ui_story_5089_50890502_85_dialog_content = "누구시죠?",
  ui_story_5089_50890502_86_dialog_content = "절 따라오십시오.",
  ui_story_5089_50890502_87_dialog_content = "선극 님께서 당신을 기다리고 계십니다.",
  ui_story_5089_50890502_88_dialog_content = "PlayerName, 춘삭절 때 헤어진 뒤로 꽤 오랜만이네.",
  ui_story_5089_50890502_89_dialog_content = "구 소저도 오랜만이야. 요즘 좀 어때?",
  ui_story_5089_50890502_90_dialog_content = "지금 그건 우리가 할 말이잖아! 선극 씨, 그동안 별일 없었어? 놈들이 괴롭히진 않았지?",
  ui_story_5089_50890502_91_dialog_content = "그거야 당연하지! 휴, 이 난간 여기 두니까 너무 거추장스럽네, 치워야겠어.",
  ui_story_5089_50890502_92_dialog_content = "...엥?",
  ui_story_5089_50890502_93_dialog_content = "자, 자, 들어가서 얘기하자. 다들 아직 점심 안 먹었지? 마침 잘됐네.",
  ui_story_5089_50890502_94_dialog_content = "천기, 천교, 상식국에 가 봐.",
  ui_story_5089_50890502_95_dialog_content = "길고경이 전에 나랑 내기해서 생선 한 마리를 주기로 했거든. 오늘 가져오기로 했어.",
  ui_story_5089_50890502_96_dialog_content = "숙수를 불러서 생선찜 만들어 달라고 하면 되겠네.",
  ui_story_5089_50890502_97_dialog_content = "네.",
  ui_story_5089_50890502_98_dialog_content = "선극 씨... 이게 무슨...",
  ui_story_5089_50890502_99_dialog_content = "휴, 비웃지 마. 궁 안은 다른 건 다 좋은데, 신선한 걸 먹기가 힘들단 말이야.",
  ui_story_5089_50890502_100_dialog_content = "......",
  ui_story_5089_50890502_101_dialog_content = "난 지금 탈옥을 도울 각오로 내가 여기 온 게 완전 우스꽝스럽단 생각이 들어.",
  ui_story_5089_50890502_102_dialog_content = "선극 씨 진짜 잡혀서 온 거 맞아? 그리고 여기 진짜 감옥이야?",
  ui_story_5089_50890502_103_dialog_content = "아하하, 당연하지. 나 조롱박에 술 빈 거 안 보여?",
  ui_story_5089_50890502_104_dialog_content = "아무리 그래도 난 궁에서 관직을 맡았던 몸이야.\n여기서 친구도 많이 사귀었고, 서로 도울 동문도 많아.",
  ui_story_5089_50890502_105_dialog_content = "대왕께서 아무리 나한테 화가 나셨어도, 정식 판결도 없이 날 어떻게 하긴 곤란하실 거야.",
  ui_story_5089_50890502_106_dialog_content = "다만 죄를 뒤집어쓴 몸이라, 절대로 술은 안 주더라고.\n그래서 지금 두 사람한테 줄 게 녹차밖에 없어.",
  ui_story_5089_50890502_107_dialog_content = "PlayerName, 구 소저.",
  ui_story_5089_50890502_108_dialog_content = "여기까지 오면서 많이 힘들었겠지? 두 사람한테 술 대신 차 한잔 대접할게.",
  ui_story_5089_50890502_109_dialog_content = "걱정해 줘서 고마워.",
  ui_story_5089_50890502_110_dialog_content = "아스트라 대륙 여행에서 가장 큰 수확은 촉음화가 아니라 소중한 친구일 줄은 몰랐어.",
  ui_story_5089_50890502_111_dialog_content = "그...그렇게까지 정중할 필요는 없는데.",
  ui_story_5089_50890502_112_dialog_content = "근데 선극 씨, 지금 촉음화가 누구 손에 있는지 알아? 그리고 단당 씨는──",
  ui_story_5089_50890502_113_dialog_content = "쉿.",
  ui_story_5089_50890502_114_dialog_content = "난 지금 일개 죄수일 뿐이야. 바깥일은 나한테 물어봤자 소용없어.",
  ui_story_5089_50890502_115_dialog_content = "그리고 봐. 난 여기서 손에 물 한 방울 안 묻히고 지내고 있어.\n너무 편해서 다른 건 생각도 안 들 정도야.",
  ui_story_5089_50890502_116_dialog_content = "근데 다른 일이 나랑 무슨 상관이겠어?",
  ui_story_5089_50890502_117_dialog_content = "거짓말.",
  ui_story_5089_50890502_118_dialog_content = "응?",
  ui_story_5089_50890502_119_dialog_content = "여긴 정교한 부품이 하나도 없잖아.",
  ui_story_5089_50890502_120_dialog_content = "선극 씨가 이런 곳을 편하게 생각할 거라고 누가 믿겠어?",
  ui_story_5089_50890502_121_dialog_content = "아하하, PlayerName 당신은 여전히 참 솔직하네.",
  ui_story_5089_50890502_122_dialog_content = "그럼 잘 들어.",
  ui_story_5089_50890502_123_dialog_content = "날 잡는 건 대왕께서 직접 내린 명이고, 앞으로 내 생사도 대왕 한 사람 손에 달려 있어.",
  ui_story_5089_50890502_124_dialog_content = "설령 구 소저의 고강한 무예로 탈옥을 강행한다 해도, 대의명분이 서지 않는 건 마찬가지야.",
  ui_story_5089_50890502_125_dialog_content = "그치만 선극 씨는 분명히 뭔가 알고 있을 거잖아. 우린 이제 어떻게 해야 되는데?",
  ui_story_5089_50890502_126_dialog_content = "지금은 아직 「어떻게」를 고민할 때가 아냐.",
  ui_story_5089_50890502_127_dialog_content = "비록 난 외부의 일에 대해 의견을 내긴 어렵지만, 그래도 며칠간 모사 노릇도 해 봤으니까,\n당신한테 경험을 공유할 수 있을 거야.",
  ui_story_5089_50890502_128_dialog_content = "예를 들어, 일을 도모하고 싶지만 시야와 능력이 부족하다면, 술책을 수단으로 삼아야겠지.",
  ui_story_5089_50890502_129_dialog_content = "그리고 그보다 나은 선택은 형세를 수단으로 삼는 거야.",
  ui_story_5089_50890502_130_dialog_content = "형세에 순응하면 자연히 하늘이 돕는 법이고.",
  ui_story_5089_50890502_131_dialog_content = "하지만 시야를 넓혀 그 은은한 물결의 흐름을 잘 봐야 한다는 것이 전제가 되겠지.",
  ui_story_5089_50890502_132_dialog_content = "그래야만 필요한 「형세」가 왔을 때 잡을 수 있거든.",
  ui_story_5089_50890502_133_dialog_content = "마치 기관 장치들처럼 시동을 걸고 온몸을 움직이는 거지.",
  ui_story_5089_50890502_134_dialog_content = "아무리 간단한 동작이라도, 여러 개의 구조가 동시에 협력해야만 해.",
  ui_story_5089_50890502_135_dialog_content = "어느 작은 부품이 고장 나면 기관 전체의 붕괴를 유발하거든.",
  ui_story_5089_50890502_136_dialog_content = "하지만... 난 뭘 찾으러 가야 할지조차 모르겠어.",
  ui_story_5089_50890502_137_dialog_content = "그럼 주변부터 둘러보는 게 어때?",
  ui_story_5089_50890502_138_dialog_content = "예를 들면, 지금 다른 누구도 아닌 두 사람이 내 앞에 와 있어.\n이게 정말 누군가의 계획에 의한 게 아닐까?",
  ui_story_5089_50890502_139_dialog_content = "!",
  ui_story_5089_50890502_140_dialog_content = "다른 예를 들자면... 구 소저는 우리와 알게 된 지 꽤 오래됐지만...",
  ui_story_5089_50890502_141_dialog_content = "당신, 구 씨가 어디서 왔는지는 알아?",
  ui_story_5089_50890502_142_dialog_content = "선극 님, 음식이 준비되었습니다.",
  ui_story_5089_50890502_143_dialog_content = "다만 대왕님을 모시는 호위병들이 방금 기세등등하게 와서는 선극 님을 불러달라고 하네요.",
  ui_story_5089_50890502_144_dialog_content = "천교가 앞에 가서 막고 있는데, 오래 못 버틸 것 같아요. 보세요...",
  ui_story_5089_50890502_145_dialog_content = "알겠어.",
  ui_story_5089_50890502_146_dialog_content = "심문을 해도 참, 아침이나 저녁에 안 오고 왜 하필 점심시간에 오고 그래?",
  ui_story_5089_50890502_147_dialog_content = "PlayerName, 구 소저, 대접은 다음 기회에 해야겠어.",
  ui_story_5089_50890502_148_dialog_content = "휴, 어쩔 수 없지.",
  ui_story_5089_50890502_149_dialog_content = "...선극 씨, 아니면 우리랑 같이 가요.",
  ui_story_5089_50890502_150_dialog_content = "얼마 전에 업나라 국왕의 부하들이 호련이랑 같이 있는 걸 봤어요. 그 사람들...",
  ui_story_5089_50890502_151_dialog_content = "천기, 손님 배웅해.",
  ui_story_5089_50890502_152_dialog_content = "선극 씨!",
  ui_story_5089_50890502_153_dialog_content = "자, 자. 얼른 가. 난 내가 처리해야 할 문제가 있어.\n그리고 너도 네가 해야 할 일이 있을 거야.",
  ui_story_5089_50890502_154_dialog_content = "난 PlayerName 널 믿어.",
  ui_story_5089_50890502_155_dialog_content = "너라면 분명히 「형세」의 흐름을 확실하게 볼 수 있을 거야.",
  ui_story_5089_50890601_1_dialog_content = "<color=#e8d9bb>천기는 마차를 몰아 우리를 성 밖까지 데려다준 후 떠났다.</color>",
  ui_story_5089_50890601_2_dialog_content = "결국 또 우리 둘만 남았네요.",
  ui_story_5089_50890601_3_dialog_content = "선극 씨가 말을 잔뜩 하긴 했는데, 대체 무슨 뜻인지...",
  ui_story_5089_50890601_4_dialog_content = "<color=#e8d9bb>꼬르륵~</color>",
  ui_story_5089_50890601_5_dialog_content = "......",
  ui_story_5089_50890601_6_dialog_content = "...그러고 보니까 우리 오늘 아무것도 못 먹었네요.",
  ui_story_5089_50890601_7_dialog_content = "마을에 가서 사례를 하고 간단히 식사를 좀 할 수 있을지 물어보고 오겠습니다.",
  ui_story_5089_50890601_8_dialog_content = "PlayerName 님, 잠시만 기다려 주십시오.",
  ui_story_5089_50890601_9_dialog_content = "네... 어라?",
  ui_story_5089_50890601_10_dialog_content = "여기 마을이 있어요?",
  ui_story_5089_50890601_11_dialog_content = "요즘 쌀값이 비싸서, 집집마다 좋은 쌀은 전부 지나가는 제나라 행상한테 팔고 있습니다.",
  ui_story_5089_50890601_12_dialog_content = "저희도 고작 묵은 현미만 조금 남아서 죽밥을 만들어 보았는데,\n귀인 여러분의 입맛에 맞을지...",
  ui_story_5089_50890601_13_dialog_content = "신경 쓰지 마세요. 저흰 하루 종일 굶었거든요. 밥을 먹을 수 있는 것만으로도 충분해요.",
  ui_story_5089_50890601_14_dialog_content = "그쪽 대인께서는 왜 안 드십니까? 뭔가 부족한 게 있다면 말씀해 주시지요.",
  ui_story_5089_50890601_15_dialog_content = "전 됐습니다.",
  ui_story_5089_50890601_16_dialog_content = "뭐라도 좀 드세요. 안 그러면 몸이 못 버텨요.",
  ui_story_5089_50890601_17_dialog_content = "괜찮습니다. 전에 임무를 수행하면서 삼 일간 식사를 안 했을 때도\n검을 휘두르는 데는 지장이 없었습니다.",
  ui_story_5089_50890601_18_dialog_content = "그리고 제 용모는 야차 같아서 다른 사람을 놀라게 만들까 걱정이 됩니다.",
  ui_story_5089_50890601_19_dialog_content = "그건 제가 전에도 아니라고...",
  ui_story_5089_50890601_20_dialog_content = "...그 목소리, 그리고 그 가면... 너 설마... 구순이냐?",
  ui_story_5089_50890601_21_dialog_content = "네?",
  ui_story_5089_50890601_22_dialog_content = "...저예요.",
  ui_story_5089_50890601_23_dialog_content = "오랜만이네요, 어르신.",
  ui_story_5089_50890601_24_dialog_content = "아이고! 구매야! 살아 있었구나!",
  ui_story_5089_50890601_25_dialog_content = "네 부모가 비참하게 목숨을 잃고, 두 관원 나리까지 죽은 걸 보고\n다들 너도 분명히 죽었을 거라 생각했다...",
  ui_story_5089_50890601_26_dialog_content = "그때 그 어린 것이 벌써 이렇게 컸구나...",
  ui_story_5089_50890601_27_dialog_content = "그동안 어떻게 지낸 게냐...",
  ui_story_5089_50890601_28_dialog_content = "제 주공께서 은혜를 베푸신 덕분에 잘 지냈어요.",
  ui_story_5089_50890601_29_dialog_content = "그렇구나... 참으로 다행이구나.",
  ui_story_5089_50890601_30_dialog_content = "기다려라, 내가 가서 장아찌 좀 더 갖다 주마. 앉아서 좀 먹거라.",
  ui_story_5089_50890601_31_dialog_content = "여기가 구 씨의 고향이었군요.",
  ui_story_5089_50890601_32_dialog_content = "그렇다고 할 수 있겠죠.",
  ui_story_5089_50890601_33_dialog_content = "제 집은 원래 더 외진 마을에 살았는데, 화를 피하려고 이곳으로 옮겨 왔었지요.",
  ui_story_5089_50890601_34_dialog_content = "화를 피하다뇨?",
  ui_story_5089_50890601_35_dialog_content = "그때 전 열 살도 안 되었고, 기억도 많이 나지 않습니다.",
  ui_story_5089_50890601_36_dialog_content = "아마 어떤 독특한 취향을 가진 대인이 제 얼굴이 마음에 들었는지,\n장난감으로 사 가려고 했을 겁니다.",
  ui_story_5089_50890601_37_dialog_content = "하지만 부모님은 원치 않으셨고, 저들은 여러 번 저희를 귀찮게 했습니다.\n그래서 저희는 여기로 도망쳤지요.",
  ui_story_5089_50890601_38_dialog_content = "그 후 부모님은 제게 가면을 씌워주셨고, 제 얼굴이 야차 같아서 드러낼 수 없다고\n사람들에게 늘 말하라 하셨습니다.",
  ui_story_5089_50890601_39_dialog_content = "어떻게 그런...",
  ui_story_5089_50890601_40_dialog_content = "가면을 쓰는 건 괜찮았습니다. 어쨌든 제가 집에 폐를 끼친 건 사실이고,\n전 원래 남과 이야기하는 게 서툴렀으니까요.",
  ui_story_5089_50890601_41_dialog_content = "다만 부모님은 늘 마음에 두고 계셨던 것 같았습니다.",
  ui_story_5089_50890601_42_dialog_content = "마을의 아이들이 절 못생겼다고 놀릴 때마다. 어머니는 절 안고 노래를 불러주셨습니다.",
  ui_story_5089_50890601_43_dialog_content = "아버지는 먹기 아까워하던 참외도 주셨고 말이지요.",
  ui_story_5089_50890601_44_dialog_content = "아, 구 씨가 전에 불렀던 그 노래... 어머니가 특별히 지어 주신 노래였겠네요.\n두 분이 구 씨를 정말 많이 사랑하셨을 것 같아요.",
  ui_story_5089_50890601_45_dialog_content = "그래서 그 뒤엔 어떻게 됐는데요?",
  ui_story_5089_50890601_46_dialog_content = "아마 PlayerName 님도 보셨겠지요. 마을 서쪽에는 산이 하나 있습니다.",
  ui_story_5089_50890601_47_dialog_content = "어...어디요?",
  ui_story_5089_50890601_48_dialog_content = "가서 이야기합시다.",
  ui_story_5089_50890601_49_dialog_content = "구순아... 이제 가는 게냐?",
  ui_story_5089_50890601_50_dialog_content = "광산 쪽에 가 볼 일이 있어서요.",
  ui_story_5089_50890601_51_dialog_content = "알겠다. 헌데 광산은 몇 년 전에 고갈됐고, 노역장도 해산했다.",
  ui_story_5089_50890601_52_dialog_content = "그 후 그 땅에 큰 공방이 세워졌는데, 거기서 뭘 만들긴 하는지는 지금까지 보질 못했지.",
  ui_story_5089_50890601_53_dialog_content = "마을 젊은이들이 일자리가 있는지 알아보러 갔었는데, 사람은 코빼기도 안 보였다더구나.\n아마 버려진 모양이니, 볼만한 게 없을 게야.",
  ui_story_5089_50890601_54_dialog_content = "그것보다, 구순아...",
  ui_story_5089_50890601_55_dialog_content = "또 무슨 일 있으신가요?",
  ui_story_5089_50890601_56_dialog_content = "아, 아니다... 휴, 모두가 힘든 난세잖냐.",
  ui_story_5089_50890601_57_dialog_content = "너라도 그런 운수가 있으니, 꿋꿋하게 잘 살거라.",
  ui_story_5089_50890601_58_dialog_content = "네 부모가 구천에서 보면 분명히 기뻐할 게야.",
  ui_story_5089_50890601_59_dialog_content = "...네.",
  ui_story_5089_50890601_60_dialog_content = "구 씨가 말한 게 바로 저 휑한 산인가요?",
  ui_story_5089_50890601_61_dialog_content = "네, 대왕 전하께서 즉위하시기 전까지, 저 광산과 이 주변 일대는 모두 전하의 봉토였습니다.",
  ui_story_5089_50890601_62_dialog_content = "전하께서는 산 아래에 노역장을 하나 세우셨는데,\n늘 유민과 죄수를 받아들여 일을 하도록 하셨습니다.",
  ui_story_5089_50890601_63_dialog_content = "그날, 관병 두 명이 한 사형수를 노역장으로 압송하다가,\n도중에 지쳐 저희 집에서 묵고 가겠다고 했습니다.",
  ui_story_5089_50890601_64_dialog_content = "부모님은 그들을 반나절 동안 모셨고, 집에서 비축한 양식을 가지고 술도 구해다 주었습니다.\n게다가 그들은 사형수에게도 밥을 주라고 지시했지요.",
  ui_story_5089_50890601_65_dialog_content = "결국 술기운이 오른 그들은 제 맨얼굴을 보려고 했고,\n억제로 제 가면을 벗기고는 절 능욕하려 했습니다.",
  ui_story_5089_50890601_66_dialog_content = "다행히 지나가던 누군가가 울타리를 무너트려 그 두 사람을 죽였습니다.",
  ui_story_5089_50890601_67_dialog_content = "허나 그 사람은 소란에 휘말리기 싫었는지, 줄곧 어둠 속에 숨어 있었고,\n당시 저도 자세히 생각할 여유가 없었습니다.",
  ui_story_5089_50890601_68_dialog_content = "저는 제가 또 큰 화를 불러왔다는 것을 깨닫고 부모님에게 가 보았지만...",
  ui_story_5089_50890601_69_dialog_content = "발견한 것은 피범벅이 되어 쓰러진 두 분의 시신이었습니다.",
  ui_story_5089_50890601_70_dialog_content = "그 옆엔 아직도 김이 모락모락 나는 흰죽이 쏟아져 있었고,\n사형수는 이미 쇠사슬을 풀고 달아난 뒤였지요.",
  ui_story_5089_50890601_71_dialog_content = "전 가끔 「운명이 인간을 농락한다」는 말이 사실일지도 모른다고 생각했습니다.",
  ui_story_5089_50890601_72_dialog_content = "다른 이들에게 못난이, 요마라고 불리며 맞고 욕을 들을 때도 저는 두렵지 않았습니다.",
  ui_story_5089_50890601_73_dialog_content = "그러나 오직 그날, 부모님의 시신을 보았을 때 저는 두려웠습니다.",
  ui_story_5089_50890601_74_dialog_content = "하지만 그 이후로 다시는 어머니가 절 달래는 노래를 들을 수 없게 되었지요.",
  ui_story_5089_50890601_75_dialog_content = "죄송합니다. 이야기가 다른 길로 빠졌군요... 그 후...",
  ui_story_5089_50890601_76_dialog_content = "구 씨!",
  ui_story_5089_50890601_77_dialog_content = "?",
  ui_story_5089_50890601_78_dialog_content = "만약 구 씨가 싫으면 저한테 얘기 안 해도 돼요.",
  ui_story_5089_50890601_79_dialog_content = "좋거나 싫은 것도 없습니다.",
  ui_story_5089_50890601_80_dialog_content = "비록 전 선극 님의 뜻을 이해하지 못했지만, 그분의 모든 말 한 마디에는\n반드시 의미가 있다는 것은 압니다.",
  ui_story_5089_50890601_81_dialog_content = "선극 님께서 제 과거를 언급하신 이상, 저는 이 일들을 당신에게 들려드려야만 합니다.",
  ui_story_5089_50890601_82_dialog_content = "그리고 이런 제 잡다한 이야기에도 개의치 않는 PlayerName 님께 감사드립니다.",
  ui_story_5089_50890601_83_dialog_content = "...그런 일을 말하는 게 정말 아무렇지도 않을 리가 없잖아요.",
  ui_story_5089_50890601_84_dialog_content = "정말 괜찮다고 생각했다면...",
  ui_story_5089_50890601_85_dialog_content = "누가 바닥에 쏟아진 죽 같은 걸 기억하겠냐구요!",
  ui_story_5089_50890601_86_dialog_content = "PlayerName 님, 제게 화가 나셨는지요.",
  ui_story_5089_50890601_87_dialog_content = "이제야 알아챘나 보네요.",
  ui_story_5089_50890601_88_dialog_content = "맞아요, 전 지금 너무 화가 나요.",
  ui_story_5089_50890601_89_dialog_content = "죄송합니다. 제 이야기가 무척 불쾌하셨겠지요.",
  ui_story_5089_50890601_90_dialog_content = "허나... 저는 곧 복수할 수 있었습니다.",
  ui_story_5089_50890601_91_dialog_content = "얼마 후, 저는 관병들이 가지고 있던 안령도를 쥐고 하루 종일 그 사형수를 쫓았습니다.",
  ui_story_5089_50890601_92_dialog_content = "그러나 뜻밖에도 그자는 노역장에 침입하여 당시의 대왕 전하를 암살하려 했던 것입니다.",
  ui_story_5089_50890601_93_dialog_content = "제가 도착했을 때, 그자는 이미 제압된 뒤였지요.",
  ui_story_5089_50890601_94_dialog_content = "전하께서는 제 사정을 물으시고, 제 가족의 죽음을 듣자 절 받아주셨습니다.\n그리고 제게 「구」라는 이름을 하사하셨습니다.",
  ui_story_5089_50890601_95_dialog_content = "그분께선 절 위해 복수해 주셨을 뿐만 아니라, 그분의 저택에 거처를 마련해 주셨고,\n제게 글을 읽고 쓰는 법을 가르쳐 주셨으며, 무술을 익혀 몸을 단련할 수 있게 하셨습니다.",
  ui_story_5089_50890601_96_dialog_content = "그래서 저는 어떻게든 이 큰 은혜를 갚고자 했습니다.",
  ui_story_5089_50890601_97_dialog_content = "좌우간 그 외에 제가 검을 휘두를... 또는 살아갈 이유는 없습니다.",
  ui_story_5089_50890601_98_dialog_content = "제 말은 그게 아니에요.",
  ui_story_5089_50890601_99_dialog_content = "구 씨는 말끝마다 복수니 은혜니 하고 있잖아요.",
  ui_story_5089_50890601_100_dialog_content = "그럼 그거 말고 구 씨의 감정은요? 하고 싶은 일은요?",
  ui_story_5089_50890601_101_dialog_content = "전에 저 대신 공격을 막았을 때도, 아무렇지도 않게 감옥을 습격하겠다고 했을 때도 그랬죠.\n자기 감정은 안 중요하다고 생각하는 것도 그렇구요.",
  ui_story_5089_50890601_102_dialog_content = "대체 구 씨는 무슨 근거로 늘 그렇게 당연하다는 얼굴로\n자기 희생을 대수롭지 않게 여기는 거죠?",
  ui_story_5089_50890601_103_dialog_content = "구 씨가 아무리 강해도 결국 같은 사람이잖아요.\n상처받고, 아프고, 슬퍼하고, 잘못하면 정말로 죽을 수도 있다구요.",
  ui_story_5089_50890601_104_dialog_content = "그런 생각은 아니었습니다. 그저 때로는 임무를 완수하기 위해...",
  ui_story_5089_50890601_105_dialog_content = "됐어요, 알겠어요. 이제 슬슬 구 씨랑 어떻게 소통해야 할지 알 것 같아요.",
  ui_story_5089_50890601_106_dialog_content = "괜히 단당 씨한테 탓해서 미안해지네요. 전 이제 구 씨가 얼마나 완고한지 알았어요.",
  ui_story_5089_50890601_107_dialog_content = "그럼 지금부터는 구 씨가 알아들을 수 있는 말로 할게요.",
  ui_story_5089_50890601_108_dialog_content = "?",
  ui_story_5089_50890601_109_dialog_content = "몸을 사리지 않는 구 씨의 희생정신이 절 정말 괴롭게 해요.",
  ui_story_5089_50890601_110_dialog_content = "아이테르는 평화를 사랑하는 종족이에요.\n전 피를 보고 싶지 않고, 구 씨가 다치는 걸 원하지 않아요.",
  ui_story_5089_50890601_111_dialog_content = "전 구 씨를 무사히 단당 씨한테 돌려주고 싶어요.",
  ui_story_5089_50890601_112_dialog_content = "그러니까 내 명령을 들어줄 마음이 있다면, 제 규칙을 잘 따라주세요.",
  ui_story_5089_50890601_113_dialog_content = "「어떤 상황이 닥치더라도, 자기 자신을 소중하게 여길 것」.",
  ui_story_5089_50890601_114_dialog_content = "전...",
  ui_story_5089_50890601_115_dialog_content = "변명은 듣고 싶지 않아요. 이럴 땐 그냥 「네」라고 대답하면 돼요.",
  ui_story_5089_50890601_116_dialog_content = "네, 기억하겠습니다.",
  ui_story_5089_50890601_117_dialog_content = "하지만 이 명령엔 기한이 있습니까?",
  ui_story_5089_50890601_118_dialog_content = "제 말이 무슨 뜻인지 전혀 이해 못 한 거 아니에요?",
  ui_story_5089_50890601_119_dialog_content = "휴, 됐어요. 굳이 기한을 정해야 한다면, 음...",
  ui_story_5089_50890601_120_dialog_content = "구 씨가 더는 은혜를 갚거나 복수를 하기 위해 검을 휘두를 필요가 없어질 때까지요.",
  ui_story_5089_50890601_121_dialog_content = "네?",
  ui_story_5089_50890601_122_dialog_content = "구 씨가 마음에 안 들어도 전 안 바꿀 거예요.",
  ui_story_5089_50890601_123_dialog_content = "아닙니다, 그저 그 말씀이 한때 사부님께서 해 주신 것과 같아서 그랬습니다.",
  ui_story_5089_50890601_124_dialog_content = "사부님이요?",
  ui_story_5089_50890601_125_dialog_content = "제 검술은 천하제일의 검객으로부터 배운 것입니다.",
  ui_story_5089_50890601_126_dialog_content = "비록 그분은 절 막돌이라면서 정식 제자로 받아들이지 않으려 하셨지만,\n그래도 많은 것을 가르쳐 주셨습니다.",
  ui_story_5089_50890601_127_dialog_content = "다만 사부님이 직접 창안하신, 산과 바다를 가를 수 있는 「경정검」은\n가르쳐주길 원치 않으셨습니다.",
  ui_story_5089_50890601_128_dialog_content = "그분께선 그것이 실재하는 검술이 아니므로, 제게 가르쳐 줄 수 없다고 하셨지요.",
  ui_story_5089_50890601_129_dialog_content = "그리고 오직 제가 더는 은혜를 갚거나 복수를 하기 위해 검을 휘두를 필요가 없어졌을 때,\n비로소 그 검술을 깨달을 자격이 생긴다고 하셨습니다.",
  ui_story_5089_50890601_130_dialog_content = "그거 신기하네요. 혹시 다른 단서는... 으읍!",
  ui_story_5089_50890601_131_dialog_content = "죄송합니다. PlayerName 님, 누군가 왔습니다.",
  ui_story_5089_50890601_132_dialog_content = "어... 호련?!",
  ui_story_5089_50890601_133_dialog_content = "저 사람이 왜 여기에... 구 씨, 우리도 얼른 따라가요!",
  ui_story_5089_50890601_134_dialog_content = "저 공방에 들어간 건가요? 그럼 우리도...",
  ui_story_5089_50890601_135_dialog_content = "끼기긱!",
  ui_story_5089_50890601_136_dialog_content = "기관수가 지키고 있어요! 구 씨, 조심해요!",
  ui_story_5089_50890602_1_dialog_content = "그냥 버려진 공방이었는데, 왜 경비가 이렇게 삼엄하죠?",
  ui_story_5089_50890602_2_dialog_content = "그리고 많은 사람들이 활동한 흔적이 남아 있어요. 거기다 호련이 여기 나타난 것까지 보면...",
  ui_story_5089_50890602_3_dialog_content = "아마 여기가 「천명」의 거점인 거겠죠.",
  ui_story_5089_50890602_4_dialog_content = "조심하십시오. 이 공방은 지하 공간까지 있어 내부 공간이 매우 넓고, 길이 복잡합니다.",
  ui_story_5089_50890602_5_dialog_content = "길을 잃는다면 곤란해질 겁니다.",
  ui_story_5089_50890602_6_dialog_content = "괜찮아요. 마침 전 이런 건물이 익숙하거든요. 그리고 감응 능력은 길 찾을 때 유용해요.",
  ui_story_5089_50890602_7_dialog_content = "[감응한다]",
  ui_story_5089_50890602_8_dialog_content = "...! 안에 무기가 엄청 많아요...",
  ui_story_5089_50890602_9_dialog_content = "「천명」 놈들... 대체 무슨 목적으로... 어라?",
  ui_story_5089_50890602_10_dialog_content = "앞쪽 구석에 있는 방에 사람이 갇혀 있는 것 같아요.",
  ui_story_5089_50890602_11_dialog_content = "!",
  ui_story_5089_50890602_12_dialog_content = "<color=#e8d9bb>문을 들어서는 순간, 지독한 악취가 느껴졌다.</color>",
  ui_story_5089_50890602_13_dialog_content = "<color=#e8d9bb>구석에 숨어 있던 사람의 그림자는 몸을 떨며 벽 쪽으로 더욱 움츠러들었다.</color>",
  ui_story_5089_50890602_14_dialog_content = "아무래도 여기 엄청 오랫동안 갇혀 있었나 봐요.",
  ui_story_5089_50890602_15_dialog_content = "당신은 누구죠? 왜 여기 있는 거예요?",
  ui_story_5089_50890602_16_dialog_content = "아── 으어──",
  ui_story_5089_50890602_17_dialog_content = "으... 하하... 으아아──",
  ui_story_5089_50890602_18_dialog_content = "안 되겠네요. 전혀 말이 안 통해요. 이미 이성을 잃은 것 같아요.",
  ui_story_5089_50890602_19_dialog_content = "일단 이 공방부터 조사해 보고 나서 이 사람을 구할 방법을 찾아보기로 해요...",
  ui_story_5089_50890602_20_dialog_content = "...구 씨? 거기 서서 뭐 하세요?",
  ui_story_5089_50890602_21_dialog_content = "...어떻게... 대체 왜... 여기 계신단 말입니까...",
  ui_story_5089_50890602_22_dialog_content = "대왕 전하!",
  ui_story_5089_50890602_23_dialog_content = "...네?! 그럼 이 사람이 업나라 국왕이에요?!",
  ui_story_5089_50890700_1_dialog_content = "<color=#e8d9bb>다음날</color>",
  ui_story_5089_50890700_2_dialog_content = "...전하, 군주 전하?",
  ui_story_5089_50890700_3_dialog_content = "으음? 무슨 일 있느냐?",
  ui_story_5089_50890700_4_dialog_content = "방택과 소흠 두 군주님의 소식을 알아봐 달라고 하셨잖습니까.",
  ui_story_5089_50890700_5_dialog_content = "아, 그렇지, 형님과 아우는 잘 지내고 있더냐.",
  ui_story_5089_50890700_6_dialog_content = "얼마 전 업나라 대왕께서 두 분께 제례에 참가하라고 보내셨습니다.\n이 기간에는 경양성으로 돌아오지 않고 행궁에 머무르실 거라고 하더군요.",
  ui_story_5089_50890700_7_dialog_content = "과연 그랬구나...",
  ui_story_5089_50890700_8_dialog_content = "왜 계속 여기 멍하니 계신 겁니까? 아침도 안 드셨군요.\n허어, 이 좋은 음식들이 다 식었잖습니까.",
  ui_story_5089_50890700_9_dialog_content = "나는 입맛이 없느니라.",
  ui_story_5089_50890700_10_dialog_content = "걱정이 아무리 많더라도, 자기 몸을 해쳐서는 안 되는 법입니다.",
  ui_story_5089_50890700_11_dialog_content = "게다가 지금은 이 궁에 갇혀있으니, 아무리 걱정해도 소용이 없지 않습니까.\n그저 PlayerName 공과 구 소저만 바라볼 수밖에요.",
  ui_story_5089_50890700_12_dialog_content = "어제 하녀가 보낸 서신에서는 다들 잘 지내고 있다고 하지 않았습니까?",
  ui_story_5089_50890700_13_dialog_content = "아니면 저들을 믿지 않시는 겁니까?",
  ui_story_5089_50890700_14_dialog_content = "당연히 믿는다. 오히려 그대야말로...",
  ui_story_5089_50890700_15_dialog_content = "나는 그대가 진즉 기회를 봐서 도망칠 줄 알았다.",
  ui_story_5089_50890700_16_dialog_content = "거 말씀을 왜 그리하십니까. 이 궁에서 먹고 자고 얼마나 좋습니까?",
  ui_story_5089_50890700_17_dialog_content = "심지어 이렇게 좋은 날이 얼마나 갈지 아쉬워서 제가 점까지 쳐봤습니다.\n점괘가 어떻게 나왔는지 맞혀 보시겠습니까?",
  ui_story_5089_50890700_18_dialog_content = "괘상에 따르면 소생은 아직 전하에게 쓸모가 있습니다.",
  ui_story_5089_50890700_19_dialog_content = "구의 대역을 부탁한 것만으로도 이미 어려운 일을 시킨 것인데,\n내 어찌 또 그대를 귀찮게 할 수 있겠느냐.",
  ui_story_5089_50890700_20_dialog_content = "이번 일이 끝나면 그대에게 응당한 보수를 주어야겠지.",
  ui_story_5089_50890700_21_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5089_50890700_22_dialog_content = "무슨 일이냐!",
  ui_story_5089_50890700_23_dialog_content = "전하, 누군가 내궁에 침입했습니다. 자리를 옮기셔야... 으억!",
  ui_story_5089_50890700_24_dialog_content = "이천간, 이자는 왜 기절시키는 게냐?",
  ui_story_5089_50890700_25_dialog_content = "보십시오, 소생이 아직 쓸모가 있다고 하지 않았습니까?",
  ui_story_5089_50890700_26_dialog_content = "아, 아...",
  ui_story_5089_50890700_27_dialog_content = "하암~ 아, 벌써 날이 밝았네요.",
  ui_story_5089_50890700_28_dialog_content = "밤새 잠도 못 잤는데...",
  ui_story_5089_50890700_29_dialog_content = "으어──",
  ui_story_5089_50890700_30_dialog_content = "휴, 저흰 위험을 무릅쓰고 밤새 당신을 데리고 마을의 의사들을 다 만나고 왔어요.",
  ui_story_5089_50890700_31_dialog_content = "하지만 당신 증세는 중독 때문이고, 독성이 이미 깊이 퍼져 치료할 약이 없대요.",
  ui_story_5089_50890700_32_dialog_content = "아으, 으어──",
  ui_story_5089_50890700_33_dialog_content = "당신이 진짜 업나라 국왕이 맞나요? 만약 그렇다면...",
  ui_story_5089_50890700_34_dialog_content = "아무래도 이 일은 그리 간단한 문제가 아닌 것 같네요.",
  ui_story_5089_50890700_35_dialog_content = "그리고 구 씨가 어제 한 말들도 왠지 불길한 예감이 들고 말이죠.",
  ui_story_5089_50890700_36_dialog_content = "이 의사도 안 된다고 하던가요?",
  ui_story_5089_50890700_37_dialog_content = "너무 실망하진 마세요, 구 씨. 다른 의사한테 방법이 있을지도 몰라요.\n리청한테 편지를 써 보는 것도 좋을 것 같아요.",
  ui_story_5089_50890700_38_dialog_content = "아니면 단당 씨가 말한 그 「복존자」란 사람을...",
  ui_story_5089_50890700_39_dialog_content = "PlayerName 님.",
  ui_story_5089_50890700_40_dialog_content = "만약 궁에 계신 분이 진짜 대왕 전하가 아니라면, 군주 전하는 어떻게 되실까요?",
  ui_story_5089_50890700_41_dialog_content = "아...",
  ui_story_5089_50890700_42_dialog_content = "저는 대왕 전하의 은혜를 입은 사람이고, 군주 전하께서도 절 많이 보살펴 주셨습니다.",
  ui_story_5089_50890700_43_dialog_content = "군주 전하께서 직접 절 호위에서 해임하셨으니, 전 이제 그분의 일에\n참견할 자격이 없을지도 모릅니다.",
  ui_story_5089_50890700_44_dialog_content = "하지만 제가 더는 그분을 지킬 수 없게 된다면, PlayerName 님...",
  ui_story_5089_50890700_45_dialog_content = "군주 전하의 안위를 부탁하겠습니다.",
  ui_story_5089_50890700_46_dialog_content = "미안해요.",
  ui_story_5089_50890700_47_dialog_content = "어라? 구 씨...? 어디 갔지?!",
  ui_story_5089_50890700_48_dialog_content = "으... 이럴 줄 알았다니까!",
  ui_story_5089_50890700_49_dialog_content = "미리 준비해서 망정이지...",
  ui_story_5089_50890700_50_dialog_content = "어르신! 죄송하지만 이 사람 좀 돌봐주실 수 있을까요?",
  ui_story_5089_50890700_51_dialog_content = "예? 그거야 물론 가능하지만... 그리 급히 어딜 가십니까?",
  ui_story_5089_50890700_52_dialog_content = "경양성이요!",
  ui_story_5089_50890700_53_dialog_content = "으어──",
  ui_story_5089_50890700_54_dialog_content = "대왕 전하, 자객이 궁에 들이닥쳤으나 호위병이 막아내지 못했습니다.\n이제 곧 정전으로 올 것입니다!",
  ui_story_5089_50890700_55_dialog_content = "전하, 구 대인이 오고 있습니다.",
  ui_story_5089_50890700_56_dialog_content = "저희가 나서면 되겠습니까?",
  ui_story_5089_50890700_57_dialog_content = "되었다. 과인은 여기서 기다릴 것이다.",
  ui_story_5089_50890700_58_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5089_50890700_59_dialog_content = "멈추어라! 대왕 전하의 어전이다! 감히...",
  ui_story_5089_50890700_60_dialog_content = "비켜라.",
  ui_story_5089_50890700_61_dialog_content = "으악──",
  ui_story_5089_50890700_62_dialog_content = "<color=#e8d9bb>구는 정전에 들어섰고, 고개를 들어 옥좌에 앉아 있는 사람과 눈을 마주쳤다.</color>",
  ui_story_5089_50890700_63_dialog_content = "보아하니 과인이 확실히 좋은 칼을 길러낸 모양이로다.",
  ui_story_5089_50890700_64_dialog_content = "온 궁에 네 적수가 없다니.",
  ui_story_5089_50890700_65_dialog_content = "연기는 집어치워.",
  ui_story_5089_50890700_66_dialog_content = "난 이미 진짜 전하를 만났어, 이 가짜!",
  ui_story_5089_50890700_67_dialog_content = "대왕 전하의 자리에서 꺼져!",
  ui_story_5089_50890700_68_dialog_content = "호오, 그 백치를 만난 모양이로군.",
  ui_story_5089_50890700_69_dialog_content = "<color=#e8d9bb>챙──!</color>",
  ui_story_5089_50890700_70_dialog_content = "<color=#e8d9bb>검이 서로 부딪히며 맑은 소리를 냈다.</color>",
  ui_story_5089_50890700_71_dialog_content = "감히 전하께 그런 불손한 언사를 내뱉다니!",
  ui_story_5089_50890700_72_dialog_content = "훗, 기세가 좋군.",
  ui_story_5089_50890700_73_dialog_content = "역시 내 휘하의 제일검이로다.",
  ui_story_5089_50890700_74_dialog_content = "이놈──!",
  ui_story_5089_50890700_75_dialog_content = "자, 모두 나와서 너희들의 수장과 대련해 보도록 해라.",
  ui_story_5089_50890700_76_dialog_content = "예!",
  ui_story_5089_50890700_77_dialog_content = "<color=#e8d9bb>비밀 호위병들은 구를 양쪽에서 포위하며 접근했고, 날카로운 금속 실이 허공에서 날아왔다.</color>",
  ui_story_5089_50890700_78_dialog_content = "<color=#e8d9bb>구는 몸을 피하려 했지만, 그녀의 시선은 다음 순간 가짜 업왕의 움직임에서 허점을 발견했다.</color>",
  ui_story_5089_50890700_79_dialog_content = "──!",
  ui_story_5089_50890700_80_dialog_content = "<color=#e8d9bb>금속 실이 그녀의 종아리를 관통했지만, 그녀의 동작은 조금도 멈추지 않았고,\n검끝은 가짜 업왕의 심장을 찔렀다.</color>",
  ui_story_5089_50890700_81_dialog_content = "너는 어려서부터 이런 나쁜 습관을 가지고 있었지.",
  ui_story_5089_50890700_82_dialog_content = "<color=#e8d9bb>띵──</color>",
  ui_story_5089_50890700_83_dialog_content = "<color=#e8d9bb>검끝은 업왕이 입고 있는 옷 속 갑옷에 막혔고, 둔탁한 저항감이 전해졌다.</color>",
  ui_story_5089_50890700_84_dialog_content = "제길...!",
  ui_story_5089_50890700_85_dialog_content = "<color=#e8d9bb>구는 힘을 뺀 후, 다시 검을 휘두르려 시도했다.</color>",
  ui_story_5089_50890700_86_dialog_content = "네 검은 날카로우나, 그 지극한 날카로움을 위한 대가는 검신의 취약함이다.",
  ui_story_5089_50890700_87_dialog_content = "내 너에게 구라는 이름을 준 것은 옥석구분의 결말을 원해서가 아니었다.",
  ui_story_5089_50890700_88_dialog_content = "!",
  ui_story_5089_50890700_89_dialog_content = "<color=#e8d9bb>10년 전</color>",
  ui_story_5089_50890700_90_dialog_content = "범인을 쫓기 위해 홀로 맨발로, 먹지도 마시지도 않고 이곳까지 쫓아온 것이냐.",
  ui_story_5089_50890700_91_dialog_content = "하하하, 어린 나이에 강한 의지를 품었도다.",
  ui_story_5089_50890700_92_dialog_content = "허나 너는 지금 굶주린 배와 피투성이인 수족으로 비틀거리고 있다.",
  ui_story_5089_50890700_93_dialog_content = "설령 원수를 따라잡는다 하여도, 기껏해야 옥석구분의 결말을 맞이할 터인데, 이래서야 되겠느냐.",
  ui_story_5089_50890700_94_dialog_content = "...그 또한 무방하겠지. 네 그 목숨은 복수 외에 더는 아무런 의미도 없다 하니 말이다.",
  ui_story_5089_50890700_95_dialog_content = "되었다. 내 이미 네 원수를 대신 처리한 이상, 끝까지 책임을 져야 마땅할 터,\n네 목숨도 내가 맡도록 하겠다.",
  ui_story_5089_50890700_96_dialog_content = "이름이 구순이라 하였느냐. 아홉 구 자를 써서야 제대로 된 이름이라 할 수 없다.",
  ui_story_5089_50890700_97_dialog_content = "앞으로는 네 이름을 「구(玖)」라고 함이 어떠하냐.",
  ui_story_5089_50890700_98_dialog_content = "이는 옥돌을 뜻하니, 옥처럼 아름다운 돌이면서, 옥보다도 더 단단한 것이다.",
  ui_story_5089_50890700_99_dialog_content = "나는 네가 내 수하 중의 날카로운 칼이 되길 바란다.\n자신을 단련하는 것은 무방하나, 쉽게 부서지지 않도록 해라.",
  ui_story_5089_50890700_100_dialog_content = "<color=#e8d9bb>구는 정신을 차렸지만, 금세 수많은 금속 실들이 그물을 엮어 그녀를 바닥에 짓눌렀다.</color>",
  ui_story_5089_50890700_101_dialog_content = "<color=#e8d9bb>그러나 가면이 땅에 떨어졌음에도 그녀는 가짜 업왕만을 바라보았다.</color>",
  ui_story_5089_50890700_102_dialog_content = "당신... 대체 누구야.",
  ui_story_5089_50890700_103_dialog_content = "누가 궁에 침입한 거 아니었습니까?\n왜 아직도 이렇게 많은 호위병들이 여길 지키고 있는 겁니까?",
  ui_story_5089_50890700_104_dialog_content = "네가 갑자기 뛰자고 하여 무슨 큰 계획이라도 있는 줄 알았다.",
  ui_story_5089_50890700_105_dialog_content = "상황을 봐 가며 대처하는 것이 곧 계획 아니겠습니까?",
  ui_story_5089_50890700_106_dialog_content = "군주 전하, 비록 전하께선 소생의 괘를 믿지 않으시지만, 소생은 믿습니다.",
  ui_story_5089_50890700_107_dialog_content = "PlayerName 공이 일전에 뽑은 음의 용과 음의 쥐는 확연히 지금 상황과 부합합니다.",
  ui_story_5089_50890700_108_dialog_content = "허나 소생의 예상이 옳다면, PlayerName 공과 구 소저만으로는 이 난국을 풀 수 없습니다.",
  ui_story_5089_50890700_109_dialog_content = "그 말은?",
  ui_story_5089_50890700_110_dialog_content = "소생이 호위병들을 유인하겠습니다. 그 틈을 타서 궁을 빠져나가십시오.",
  ui_story_5089_50890700_111_dialog_content = "그다음은... 상황을 봐 가며 대처하십시오.",
  ui_story_5089_50890700_112_dialog_content = "잠깐! 이천간!",
  ui_story_5089_50890700_113_dialog_content = "누가 저기 있다!",
  ui_story_5089_50890700_114_dialog_content = "쫓아라!",
  ui_story_5089_50890700_115_dialog_content = "(...정말 말이 통하질 않는 자로구나!)",
  ui_story_5089_50890700_116_dialog_content = "(허나 지금은 그저...)",
  ui_story_5089_50890700_117_dialog_content = "군주 전하, 어딜 가십니까?",
  ui_story_5089_50890700_118_dialog_content = "......",
  ui_story_5089_50890700_119_dialog_content = "선극 님, 밖에...",
  ui_story_5089_50890700_120_dialog_content = "떠들지 마, 나 일하고 있잖아.",
  ui_story_5089_50890700_121_dialog_content = "지금이 어느 때인데 아직도 기와를 만지작거리고 계세요?",
  ui_story_5089_50890700_122_dialog_content = "이건 그냥 기와가 아니라, 내가 며칠 동안 열심히 설계한 유리 기와 기관이야.",
  ui_story_5089_50890700_123_dialog_content = "비록 PlayerName도 많이 성장했지만, 간계를 부리는 재주는 아직 부족해.",
  ui_story_5089_50890700_124_dialog_content = "네?",
  ui_story_5089_50890700_125_dialog_content = "내 말은 그러니까, 이 감방은 겉으로 보기엔 기관 부품이 보이지 않는다는 거야.",
  ui_story_5089_50890700_126_dialog_content = "하지만 진정한 기교사의 손에는 책걸상이나 대들보, 기왓장도 전부 기관의 일부가 될 수 있어.",
  ui_story_5089_50890700_127_dialog_content = "봐, 이건 내가 아이테르한테서 영감을 받아 실내의 재료들만 가지고\n즉석에서 만든 기관, 「이광영와」야!",
  ui_story_5089_50890700_128_dialog_content = "지금 농담하시는 거죠? 그럼 그 기관은 무슨 효과가 있는데요?",
  ui_story_5089_50890700_129_dialog_content = "발사한 빛이나 광력을 내가 원하는 위치로 유도할 수 있어.",
  ui_story_5089_50890700_130_dialog_content = "그걸 어디 쓰실 건데요?",
  ui_story_5089_50890700_131_dialog_content = "그러게, 어디에 써야 할까~?",
  ui_story_5089_50890700_132_dialog_content = "십 년 전, 조정의 투쟁에 연루되어 죄수가 된 고관이 있었다.\n그는 벌로 광산에 들어가 죽을 때까지 고된 노동을 해야 했지.",
  ui_story_5089_50890700_133_dialog_content = "그러나 하늘은 그를 저버리지 않았다.\n호송하는 관원들은 게으름을 피웠고, 기어코 도중에 민가에서 묵어가려고 했다.",
  ui_story_5089_50890700_134_dialog_content = "그 집의 부부는 모두 지극히 평범한 백성들이었기에, 손쉽게 그에게 습격당했고,\n그는 기회를 노려 도망쳤다.",
  ui_story_5089_50890700_135_dialog_content = "허나 마당을 빠져나오던 그는 개돼지만도 못한 두 관병이\n부부의 여식을 능욕하려 하는 것을 발견했지.",
  ui_story_5089_50890700_136_dialog_content = "그는 내친김에 그 두 마리 축생을 도살했고, 당초에 가려던 길을 따라 노역장으로 향했다.",
  ui_story_5089_50890700_137_dialog_content = "당시 노역장을 주관하던 친왕은 좋은 사람이라 할 수 있었으나, 기실은 무능한 자였고,\n약을 한 번 쓰자 백치가 되었다.",
  ui_story_5089_50890700_138_dialog_content = "죄수는 역용술로 그와 서로 얼굴을 바꾸었고, 그리하여 그의 신분을 차지했다.",
  ui_story_5089_50890700_139_dialog_content = "휘하의 수족들 또한 그에게 추호의 충심도 없었기에, 제 주공이 바뀐 것조차 알지 못했지.",
  ui_story_5089_50890700_140_dialog_content = "이윽고 때마침 그 부부의 딸이 부모를 대신하여 복수를 하겠다고 쫓아왔다.",
  ui_story_5089_50890700_141_dialog_content = "그제서야 그는 자신이 손을 과하게 쓴 탓에 그 부부가 모두 죽었다는 것을 알게 되었지.",
  ui_story_5089_50890700_142_dialog_content = "하여 그는 그 소녀를 거두었고, 겸사로 자신에게 충직한 명검을 길러냈다.",
  ui_story_5089_50890700_143_dialog_content = "당신... 당신이──!",
  ui_story_5089_50890700_144_dialog_content = "<color=#e8d9bb>구는 눈을 붉히며 안간힘을 다해 몸을 일으켜 세웠고,\n그녀를 억누르고 있던 철망은 날카로운 소리를 내며 끊어지려 했다.</color>",
  ui_story_5089_50890700_145_dialog_content = "이 이야기는 진즉 네게 말했어야 했다.",
  ui_story_5089_50890700_146_dialog_content = "하여 너는 이제 나를 죽여 부모의 원수를 갚을 셈이냐.",
  ui_story_5089_50890700_147_dialog_content = "아니면 내가 너를 구하고 지금까지 기른 은혜를 갚을 셈이냐.",
  ui_story_5089_50890700_148_dialog_content = "......",
  ui_story_5089_50890700_149_dialog_content = "<color=#e8d9bb>검을 쥔 구의 손이 처음으로 떨렸다.</color>",
  ui_story_5089_50890700_150_dialog_content = "네가 줄곧 마음속으로 생각하던 일은 대관절 무엇이란 말이냐.",
  ui_story_5089_50890700_151_dialog_content = "하앗──!",
  ui_story_5089_50890700_152_dialog_content = "<color=#e8d9bb>한줄기의 밝은 빛이 번쩍였다.</color>",
  ui_story_5089_50890700_153_dialog_content = "<color=#e8d9bb>주변의 금속 실이 수없이 무너져 내렸고, 하늘을 뒤덮은 파편 속에서\n그녀는 아랑곳하지 않고 마지막 검초를 펼쳤다.</color>",
  ui_story_5089_50890700_154_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5089_50890700_155_dialog_content = "<color=#e8d9bb>빛의 힘으로 감싸인 검기는 궁전의 반을 가르고도 흩어지지 않았고,\n거대한 참격은 벽돌 바닥에 깊은 계곡을 남겼다.</color>",
  ui_story_5089_50890700_156_dialog_content = "<color=#e8d9bb>그러나 업왕은 조금도 피하지 않았고, 검의 빛과 엇갈려 조금의 상처도 입지 않았다.</color>",
  ui_story_5089_50890700_157_dialog_content = "망설이고 있군. 이제 검조차 제대로 잡을 수 없는 것이냐.",
  ui_story_5089_50890700_158_dialog_content = "<color=#e8d9bb>챙──!</color>",
  ui_story_5089_50890700_159_dialog_content = "<color=#e8d9bb>업왕은 구의 검을 쳐냈고, 검은 구석으로 날아갔다.</color>",
  ui_story_5089_50890700_160_dialog_content = "<color=#e8d9bb>얼마 전</color>",
  ui_story_5089_50890700_161_dialog_content = "전하, 기어이 가셔야겠다면 소인도 실례를 범할 수밖에 없습니다.",
  ui_story_5089_50890700_162_dialog_content = "내 업의 왕궁에서 제 호위와 싸우게 될 날이 올 줄은 생각지도 못했거늘.",
  ui_story_5089_50890700_163_dialog_content = "허나 내 이제 더는 물러나지 않을 것이야.",
  ui_story_5089_50890700_164_dialog_content = "게다가 바깥에는 나를 기다리는 이가 있다.",
  ui_story_5089_50890700_165_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5089_50890700_166_dialog_content = "<color=#e8d9bb>근처의 정전이 갑자기 강력한 루미나에 의해 갈라졌다.</color>",
  ui_story_5089_50890700_167_dialog_content = "<color=#e8d9bb>곧이어 한 줄기 빛이 스쳐 지나가더니, 그 강력한 루미나를 끌어당겨 궤도를 바꾸었다.</color>",
  ui_story_5089_50890700_168_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5089_50890700_169_dialog_content = "<color=#e8d9bb>성루는 한가운데부터 갈라져 궁정 호위병과 단당 사이를 떨어트렸다.</color>",
  ui_story_5089_50890700_170_dialog_content = "<color=#e8d9bb>이어서 밝은 빛은 다시 번쩍이며 궁궐 밖으로 나가는 길을 비추었다.</color>",
  ui_story_5089_50890700_171_dialog_content = "(저 방향은... 선기경?)",
  ui_story_5089_50890700_172_dialog_content = "(역시, 감옥에 순순히 갇혀만 있을 이가 아니지 않느냐.)",
  ui_story_5089_50890700_173_dialog_content = "(그대도 지금 내가 궁을 나서는 것이 더 옳다고 생각하는 것인가.)",
  ui_story_5089_50890700_174_dialog_content = "대왕 전하.",
  ui_story_5089_50890700_175_dialog_content = "무슨 일이냐.",
  ui_story_5089_50890700_176_dialog_content = "작화군주가 궁을 탈출했습니다.",
  ui_story_5089_50890700_177_dialog_content = "군주와 함께 입궁한 내력 불명의 사내도 행방을 알 수 없습니다.",
  ui_story_5089_50890700_178_dialog_content = "추적하던 금위병의 보고에 따르면, 그자가 덤불 속으로 들어가는 것을 보았는데,\n따라가 보니 설탕 인형밖에 없었다고 합니다.",
  ui_story_5089_50890700_179_dialog_content = "그리고...",
  ui_story_5089_50890700_180_dialog_content = "또 무엇이냐, 속히 고하라.",
  ui_story_5089_50890700_181_dialog_content = "「저쪽」에서 온 소식입니다. 조만간 거사를 시작하겠다고 합니다.",
  ui_story_5089_50890700_182_dialog_content = "저희에게 반드시 삼 일 내에 병기를 운송하라고 하더군요.",
  ui_story_5089_50890700_183_dialog_content = "허나 공방에서는 양이 너무 많아 어렵다고 합니다.\n게다가 제나라 쪽도 일전의 거래를 이행하라 재촉하고 있습니다...",
  ui_story_5089_50890700_184_dialog_content = "알겠다.",
  ui_story_5089_50890700_185_dialog_content = "이 일은 나중에 다시 논하도록 하지.",
  ui_story_5089_50890700_186_dialog_content = "우선은 너희 수장을 제압해서 진정시키도록 해라.",
  ui_story_5089_50890700_187_dialog_content = "예.",
  ui_story_5089_50890700_188_dialog_content = "<color=#e8d9bb>쿵.</color>",
  ui_story_5089_50890700_189_dialog_content = "<color=#e8d9bb>호위병은 구를 빈방에 두고 떠났다.</color>",
  ui_story_5089_50890700_190_dialog_content = "어라, 이게 누구야, 구 소저잖아?",
  ui_story_5089_50890700_191_dialog_content = "나랑 이웃이 됐네?",
  ui_story_5089_50890700_192_dialog_content = "......",
  ui_story_5089_50890802_1_dialog_content = "악한이 군주 전하를 납치했다! 계엄을 선포한다!",
  ui_story_5089_50890802_2_dialog_content = "거리 곳곳을 수색하고, 수상한 자를 발견하면 즉시 보고하라!",
  ui_story_5089_50890802_3_dialog_content = "예!",
  ui_story_5089_50890802_4_dialog_content = "(경비병들이 엄청 많네... 온 경양성의 분위기가 달라졌잖아.)",
  ui_story_5089_50890802_5_dialog_content = "(그리고 왠지 나도 저 사람들이 쫓고 있는 수상한 사람에 포함될 것 같네.)",
  ui_story_5089_50890802_6_dialog_content = "거기 누구냐! 나와라!",
  ui_story_5089_50890802_7_dialog_content = "(이런...! 어? 누가 날 잡아당기는 거야...)",
  ui_story_5089_50890802_8_dialog_content = "쉿, 나다.",
  ui_story_5089_50890802_9_dialog_content = "단당 씨!",
  ui_story_5089_50890802_10_dialog_content = "따라오거라.",
  ui_story_5089_50890802_11_dialog_content = "여긴 어디죠?",
  ui_story_5089_50890802_12_dialog_content = "우리가 일전에 금을 호송하라고 의뢰했던 표국이 마련한 방이다.",
  ui_story_5089_50890802_13_dialog_content = "저들도 반은 강호인이라 할 수 있고, 제 나름의 규칙이 있다.",
  ui_story_5089_50890802_14_dialog_content = "우리가 그런 큰 거래를 해주었으니, 어느 정도는 우리를 위해 편의를 봐주지 않겠느냐.",
  ui_story_5089_50890802_15_dialog_content = "그때부터 이렇게 많은 걸 생각했던 거예요?",
  ui_story_5089_50890802_16_dialog_content = "그럼 저흴 객잔에 두고 온 것도 이유가 있었겠네요.",
  ui_story_5089_50890802_17_dialog_content = "내 그때는 미처 진상을 명확히 알지 몰랐다. 그저 선기경의 모호한 암시만 있을 뿐이었지.",
  ui_story_5089_50890802_18_dialog_content = "허나 일말의 가능성만 있더라도, 이미 온 업나라를 위태롭게 만들 대사였다.",
  ui_story_5089_50890802_19_dialog_content = "게다가... 곡물의 값이 너무나도 비쌌다.",
  ui_story_5089_50890802_20_dialog_content = "저희도 마을 어르신한테 들었어요.\n제나라 행상이 최근 계속 식량을 비싼 값에 사들이고 있다고 말이에요.",
  ui_story_5089_50890802_21_dialog_content = "...춘삭절 때의 소란은 업나라가 해안포의 인도를 늦춘 탓도 있다.",
  ui_story_5089_50890802_22_dialog_content = "그러니 제나라도 헛되이 손해를 볼 순 없겠지.",
  ui_story_5089_50890802_23_dialog_content = "그 말은 그럼... 제나라가 일부러 곡물값을 올리고 있다는 건가요?",
  ui_story_5089_50890802_24_dialog_content = "값이 비싸면 백성을 해치고, 백성이 해를 입으면 흩어지는 법.",
  ui_story_5089_50890802_25_dialog_content = "업나라는 근 몇 년간 크고 작은 공방을 늘렸고,\n많은 청장년들이 공방의 일자리를 노리고 밭을 떠났지.",
  ui_story_5089_50890802_26_dialog_content = "애당초 우리의 식량 비축량은 이러한 충격에 대처할 수 있을 만큼 충분하지 못했다.",
  ui_story_5089_50890802_27_dialog_content = "곡물값의 상승은 다른 산업의 비용 증가를 의미하고, 일련의 부작용을 가져오기 마련이다.",
  ui_story_5089_50890802_28_dialog_content = "더욱이 제나라는 돈이 부족하지 않은 나라다.\n만약 우리와 소모전을 펼칠 결심을 한다면, 사태가 길어졌을 때 반드시 혼란이 벌어질 게다.",
  ui_story_5089_50890802_29_dialog_content = "나는 제나라가 이 일로 결판을 낼 심산이라 보진 않아.\n그저 이를 기회로 업나라를 애먹이려는 것일 게야.",
  ui_story_5089_50890802_30_dialog_content = "...다만, 시기가 너무나도 좋지 않구나.",
  ui_story_5089_50890802_31_dialog_content = "시기요?",
  ui_story_5089_50890802_32_dialog_content = "PlayerName 공자, 그대는 「국가」란 무엇이라 생각하느냐.",
  ui_story_5089_50890802_33_dialog_content = "네? 저는... 모두가 더 좋은 삶을 살기 위해 모인 결과라고 생각해요.",
  ui_story_5089_50890802_34_dialog_content = "각자 노력도 하고, 서로 돕는 집단인 거죠.",
  ui_story_5089_50890802_35_dialog_content = "그것은 그대들 국가의 이념인가? 참으로 세외의 도원과도 같구나.",
  ui_story_5089_50890802_36_dialog_content = "뭐, 뭔가 틀렸나요?",
  ui_story_5089_50890802_37_dialog_content = "아니다, PlayerName 공자의 생각은 좋은 것이야.",
  ui_story_5089_50890802_38_dialog_content = "비록 모두가 같은 조나라 황실을 섬기고 있으나, 이 용주의 제후국들은 이에 대해\n저마다 다른 견해를 가지고 있다.",
  ui_story_5089_50890802_39_dialog_content = "예를 들어, 「치국은 상업」이라 여기는 것이 제나라의 생각이다.",
  ui_story_5089_50890802_40_dialog_content = "반면에 우리 업나라는 「국가」란 쉬지 않고 밤낮으로 움직이는\n거대한 무형의 기관 장치와 같다고 배워왔지.",
  ui_story_5089_50890802_41_dialog_content = "임금은 축이 되고, 신하는 톱니바퀴가 되며, 장인은 기름이 되고,\n백성은 그 기관의 동력이 되는 것이야.",
  ui_story_5089_50890802_42_dialog_content = "만약 각자 맡은 직분을 수행하여 정상적으로 실행될 수 있다면,\n자연히 국력이 융성해지기 마련이다.",
  ui_story_5089_50890802_43_dialog_content = "그러나 지금은 어떠하냐.",
  ui_story_5089_50890802_44_dialog_content = "임금은 가짜고, 신하 중에는 역심을 품은 자가 있으며, 장인들은 자유롭지 못하고,\n백성들은 그저 투쟁의 피해를 지켜볼 수밖에 없는 신세다.",
  ui_story_5089_50890802_45_dialog_content = "이러한 국면을 타개하려면 오직 쾌도난마뿐.",
  ui_story_5089_50890802_46_dialog_content = "하여 내 직접 환궁하여 가장 핵심이 되는 곳에서부터 허점을 찾고자 했다.",
  ui_story_5089_50890802_47_dialog_content = "더불어 그대들이 추격에서 벗어나 자유롭게 증거를 찾을 수 있게 하기 위함이었지.",
  ui_story_5089_50890802_48_dialog_content = "솔직히 말한다면 구가 내 뜻에 따르지 않았을 게야. 하여 이러한 하책을 쓸 수밖에 없었지.\n부디 PlayerName 공자도 이를 탓하지 않았으면 좋겠구나.",
  ui_story_5089_50890802_49_dialog_content = "그럴 리가요. 저도 이미 구 씨가 얼마나 완고한지 잘 알았는걸요.",
  ui_story_5089_50890802_50_dialog_content = "그래서 저도 사실은 준비한 게 있는데요...",
  ui_story_5089_50890802_51_dialog_content = "나리, 소저, 물건은 모두 안전하게 도착했습니다. 와서 확인해 주십시오.",
  ui_story_5089_50890802_52_dialog_content = "아, 네, 고마워요.",
  ui_story_5089_50890802_53_dialog_content = "그리고 소저가 방금 저희한테 알아봐 달라고 부탁한 그 일도 단서가 잡혔습니다.",
  ui_story_5089_50890802_54_dialog_content = "성 밖의 형제들이 보낸 소식인데, 확실히 화룡연이 그쪽 궤도에 집중되어 있었습니다.\n보아하니 운반할 물건이 적지 않은 모양입니다.",
  ui_story_5089_50890802_55_dialog_content = "알겠네, 고맙구나.",
  ui_story_5089_50890802_56_dialog_content = "돈 받고 하는 일일 뿐입니다. 이만 물러가겠습니다.",
  ui_story_5089_50890802_57_dialog_content = "설마 비밀 공방 얘기인가요?",
  ui_story_5089_50890802_58_dialog_content = "그래, 내 궁에서 소식을 조금 알아냈다.",
  ui_story_5089_50890802_59_dialog_content = "가짜 숙부는 줄곧 업나라를 이용하여 「천명」을 위해 무기를 만들고 있었다.",
  ui_story_5089_50890802_60_dialog_content = "제나라의 해안포 인도가 늦어진 것은 첫째, 「천명」의 계획에 협조하기 위해서고,\n둘째는 「천명」 또한 해안포를 제 소유로 하려 했기 때문이다.",
  ui_story_5089_50890802_61_dialog_content = "그리고 얼마 전, 저들은 거듭 병기의 수요량을 늘렸다.",
  ui_story_5089_50890802_62_dialog_content = "게다가 몇 번을 거듭 재촉하고, 심지어는 가짜 숙부에게 즉시 보내라고 위협하기도 했지.",
  ui_story_5089_50890802_63_dialog_content = "오는 길에 PlayerName 공자가 비밀 공방에 대해 말한 것을 듣고 사람을 보냈다.",
  ui_story_5089_50890802_64_dialog_content = "다만 이렇게 빨리 움직일 줄은 몰랐구나...",
  ui_story_5089_50890802_65_dialog_content = "「천명」 같은 조직이 그렇게 많은 무기를 손에 넣는 걸 어떻게 보고만 있겠어요!",
  ui_story_5089_50890802_66_dialog_content = "나도 같은 마음이다.",
  ui_story_5089_50890802_67_dialog_content = "다만 지금 우리의 처지로는 어떤 행동도 하기 어렵다.",
  ui_story_5089_50890802_68_dialog_content = "PlayerName 공자 덕에 겨우 진상을 알게 되었건만,\n만일 내 조금 더 일찍 준비할 수 있었더라면...",
  ui_story_5089_50890802_69_dialog_content = "그 표정은 제가 아는 단당 씨가 아닌 것 같은데요.",
  ui_story_5089_50890802_70_dialog_content = "PlayerName 공자?",
  ui_story_5089_50890802_71_dialog_content = "제가 아는 단당 씨는 운명조차도 맞서 싸우는 사람이잖아요.",
  ui_story_5089_50890802_72_dialog_content = "무서울 정도로 용감한 사람이죠.",
  ui_story_5089_50890802_73_dialog_content = "...과찬이다. 눈앞의 난국은 결코 혼자만의 힘으로 해결할 수 있는 것이 아니니라.",
  ui_story_5089_50890802_74_dialog_content = "적어도 협상에 사용할 패만 있다면...",
  ui_story_5089_50890802_75_dialog_content = "있죠.",
  ui_story_5089_50890802_76_dialog_content = "무에냐?",
  ui_story_5089_50890802_77_dialog_content = "패는 아니지만 판돈은 많죠.",
  ui_story_5089_50890802_78_dialog_content = "성 하나를 살 만큼의 금이 있잖아요.",
  ui_story_5089_50890802_79_dialog_content = "!",
  ui_story_5089_50890802_80_dialog_content = "허나 그것은 세자가 그대에게 준 선물이고, 그대는 다시 돌려줄 심산이 아니었더냐.",
  ui_story_5089_50890802_81_dialog_content = "겨우 여기까지 왔는데, 쓸 수 있는 건 써야 안 아깝지 않을까요?",
  ui_story_5089_50890802_82_dialog_content = "허나 이 많은 황금이 있다 해도, 제한된 시간 내에 일손을 모으려면...",
  ui_story_5089_50890802_83_dialog_content = "그거라면 말이죠...",
  ui_story_5089_50890802_84_dialog_content = "전 조정의 그런 복잡한 일들은 잘 몰라서, 그런 쪽 의견은 제시할 수가 없어요.",
  ui_story_5089_50890802_85_dialog_content = "근데 그냥 좀 쉽게 생각해 보면 어떨까요?",
  ui_story_5089_50890802_86_dialog_content = "결국 돈이란 건 물건을 사는 데 쓰는 거잖아요.",
  ui_story_5089_50890802_87_dialog_content = "하면... PlayerName 공자는 무엇을 사고 싶으냐.",
  ui_story_5089_50890802_88_dialog_content = "제 짐작이 맞다면 저들은 그동안은 화룡연을 쓴 적이 없을 거예요.",
  ui_story_5089_50890802_89_dialog_content = "소리가 크게 났다면 주변의 주민들이 못 들었을 리도 없고,\n그 공방이 오래전에 폐기됐다고 믿을 리도 없잖아요.",
  ui_story_5089_50890802_90_dialog_content = "확실히 그렇지, 이전까지는 아무도 그러한 광경을 본 적이 없었다.",
  ui_story_5089_50890802_91_dialog_content = "저들의 일은 기밀을 지켜야 하니, 비밀 공방이 「비밀」임을 보장하려면\n여러 차례에 걸쳐 소량으로 운송하는 수밖에 없었겠지.",
  ui_story_5089_50890802_92_dialog_content = "하지만 이번엔 화룡연을 사용한 걸 보면, 한 대가 끝이 아닌 것 같아요.",
  ui_story_5089_50890802_93_dialog_content = "화룡연의 임대는 백공원에서 관리감독을 맡고 있다.",
  ui_story_5089_50890802_94_dialog_content = "양대 기관술 문파 출신의 관원들이 조정에서 직접 파견한 관리관과 함께 감독하지.",
  ui_story_5089_50890802_95_dialog_content = "대왕조차도 절차를 거치지 않고서는 독단으로 사용할 수 없다.",
  ui_story_5089_50890802_96_dialog_content = "다만 이미 공방주 등에게 임차한 것들은 관리가 그리 엄격하지 않아.",
  ui_story_5089_50890802_97_dialog_content = "그럼 아마 저 화룡연들은 「천명」이 그 사람들한테서 다시 빌린 거겠네요.",
  ui_story_5089_50890802_98_dialog_content = "그 사람들부터 착수해야 하는 게냐?",
  ui_story_5089_50890802_99_dialog_content = "아니요.",
  ui_story_5089_50890802_100_dialog_content = "이런 일로 그들과 정면으로 충돌할 필요는 없어요.\n어쨌든 지금 조급할 사람은 「천명」 쪽이니까요.",
  ui_story_5089_50890802_101_dialog_content = "지금 물러서서 지켜보니까 오히려 선극 씨가 말한 「형세」를\n더 뚜렷하게 볼 수 있게 된 것 같아요.",
  ui_story_5089_50890802_102_dialog_content = "단당 씨, 백공원에서 임대해 주는 건 「화룡연」뿐인 거죠?",
  ui_story_5089_50890802_103_dialog_content = "그렇다.",
  ui_story_5089_50890802_104_dialog_content = "그럼... 제가 사고 싶은 건...",
  ui_story_5089_50890802_105_dialog_content = "「길」이에요.",
  ui_story_5089_50890802_106_dialog_content = "...역시 PlayerName 공자는 참으로 귀재로구나!",
  ui_story_5089_50890802_107_dialog_content = "<color=#e8d9bb>비밀 공방</color>",
  ui_story_5089_50890802_108_dialog_content = "주변의 화룡연은 어떻게 된 거냐? 누가 당신 마음대로 움직이라고 했냔 말이다!",
  ui_story_5089_50890802_109_dialog_content = "뭘 소리를 질러? 나야말로 물어볼 게 많은데 말이야.",
  ui_story_5089_50890802_110_dialog_content = "그동안 몇 번이나 병기를 보내라고 재촉했는데, 당신들은 뭘 했어?",
  ui_story_5089_50890802_111_dialog_content = "제작 수량이 적으면 제나라 쪽에 갈 걸 이쪽 먼저 주면 되잖아. 어려운 거 아니잖아?",
  ui_story_5089_50890802_112_dialog_content = "...제나라의 주문 건을 인도하지 않으면 양국 관계에 영향을 미칠 수 있다.",
  ui_story_5089_50890802_113_dialog_content = "하, 세 살짜리 어린애도 그렇게 순진하진 않겠네.",
  ui_story_5089_50890802_114_dialog_content = "피차 「천명」의 배에 같이 탄 사이인데, 어느 쪽 명령을 들을지까지 내가 가르쳐 줘야 해?\n양국 관계 같은 걸 누가 신경 쓴다고 그래?",
  ui_story_5089_50890802_115_dialog_content = "설마... 너희 그 대왕은 진짜로 자기가 업나라 왕이라 생각하는 건 아니겠지?",
  ui_story_5089_50890802_116_dialog_content = "그럴 리가.",
  ui_story_5089_50890802_117_dialog_content = "하긴, 그 사람 원래 사형수였다며?\n「천명」에 투항한 덕분에 업왕 신분으로 오늘까지 살 수 있었다고 들었어.",
  ui_story_5089_50890802_118_dialog_content = "만약 그 사람이 감히 딴마음을 품는다면, 지금의 모든 걸 어떻게 얻었든,\n그대로 토해내야 할 거야.",
  ui_story_5089_50890802_119_dialog_content = "지금은 거사를 눈앞에 두고 있어. 말 잘 듣는 제후국은 그러려니 하면 되고,\n안 듣는 쪽은 소란을 크게 피울수록 좋아.",
  ui_story_5089_50890802_120_dialog_content = "이 정도는 당신도 알고 있겠지?",
  ui_story_5089_50890802_121_dialog_content = "...물론이다.",
  ui_story_5089_50890802_122_dialog_content = "그럼 됐어, 얼른 가서 물건이나 실어줘.",
  ui_story_5089_50890802_123_dialog_content = "호련 님, 문제가 생겼습니다.",
  ui_story_5089_50890802_124_dialog_content = "또 뭔데?",
  ui_story_5089_50890802_125_dialog_content = "아무래도 당분간은 화룡연으로 화물을 운송할 수 없을 것 같습니다.",
  ui_story_5089_50890802_126_dialog_content = "공방 쪽엔 이미 우리가 임차료를 잔뜩 준 거 아니었어?",
  ui_story_5089_50890802_127_dialog_content = "그런 문제가 아니라...",
  ui_story_5089_50890802_128_dialog_content = "길이 막혔습니다.",
  ui_story_5089_50890802_129_dialog_content = "하아?!",
  ui_story_5089_50890901_1_dialog_content = "PlayerName 공자가 거금을 쾌척하니 일이 잘 풀리는지고.",
  ui_story_5089_50890901_2_dialog_content = "내 이미 공방 근처 길의 토지를 빌리고 백성들에게 방책을 쌓으라 당부해 두었다.",
  ui_story_5089_50890901_3_dialog_content = "반드시 「천명」을 한 발짝도 움직일 수 없게 막아야 한다.",
  ui_story_5089_50890901_4_dialog_content = "다만 우리가 길을 막은 탓에 행상 한 무리가 이곳에 발이 묶이고 말았구나.",
  ui_story_5089_50890901_5_dialog_content = "소인은 곡식을 사러 왔을 뿐이지, 죄를 지은 적은 없습니다.",
  ui_story_5089_50890901_6_dialog_content = "두 귀인께서는 소인의 상단을 좀 보내줄 수 있겠는지요.",
  ui_story_5089_50890901_7_dialog_content = "제나라에서 식량을 사러 온 건가요?",
  ui_story_5089_50890901_8_dialog_content = "예, 그렇습니다요. 헌데 무슨 문제라도 있는 것입니까?\n소인의 사업은 필요한 허가를 다 받았습니다만...",
  ui_story_5089_50890901_9_dialog_content = "(단당 씨.)",
  ui_story_5089_50890901_10_dialog_content = "(알고 있다.)",
  ui_story_5089_50890901_11_dialog_content = "흥, 그대는 지금 눈앞의 사람이 어떤 귀인인지 알기나 하는 것이냐.",
  ui_story_5089_50890901_12_dialog_content = "자, 잘 모르겠습니다요...",
  ui_story_5089_50890901_13_dialog_content = "여기 PlayerName 공자는 아스트라 대륙의 특사이자 헤븐즈 밸리의 주인,\n제나라 국군이 친히 봉한 명예 국민이다.",
  ui_story_5089_50890901_14_dialog_content = "또한 선녀용왕의 가호를 받은 자이자 린 가문 상회의 맹우이며,\n제나라 세자가 애타게 구애하고 있는...",
  ui_story_5089_50890901_15_dialog_content = "(됐어요! 충분해요! 저 사람 눈빛 좀 보세요! 벌써 이글거려서 더 말할 것도 없다구요!)",
  ui_story_5089_50890901_16_dialog_content = "귀인의 존함은 오래전부터 들었습니다! 이렇게 만나게 되다니 소인 평생의 복이옵니다!",
  ui_story_5089_50890901_17_dialog_content = "소인에게 분부할 일이라도 있으십니까? 제가 할 수 있는 일이라면...\n참, 이 길은 귀인께서 막으셨지요.",
  ui_story_5089_50890901_18_dialog_content = "제가 늙어 죽을 때까지 막으셔도 소인은 절대 원망하지 않을 것입니다!",
  ui_story_5089_50890901_19_dialog_content = "그 정도는 아닌데요... 전 그냥 거래를 하나 하고 싶을 뿐이에요.",
  ui_story_5089_50890901_20_dialog_content = "말씀만 하십시오. 무엇을 사시든지 가격을 깎아 드리겠습니다!",
  ui_story_5089_50890901_21_dialog_content = "단당 씨, 금이 얼마나 남았죠?",
  ui_story_5089_50890901_22_dialog_content = "장인의 품삯, 궤도와 토지 임차에 쓴 값을 합해도 극히 일부일 뿐이다.",
  ui_story_5089_50890901_23_dialog_content = "그럼 남은 거 다 저 사람 줄래요.",
  ui_story_5089_50890901_24_dialog_content = "그게 무슨...",
  ui_story_5089_50890901_25_dialog_content = "전 제 금으로 여러분이 업나라에서 사들인 모든 식량을 사고 싶어요.",
  ui_story_5089_50890901_26_dialog_content = "아... 그러시면 소인이 좀 난처해집니다요...",
  ui_story_5089_50890901_27_dialog_content = "여러분이 제나라 국왕님의 일을 하는 거 알고 있어요.",
  ui_story_5089_50890901_28_dialog_content = "!",
  ui_story_5089_50890901_29_dialog_content = "그냥 가서 제가 억지로 샀다고 하세요.\n제나라 국왕님이 뭐라 탓하시면 저한테 책임을 떠넘기면 돼요.",
  ui_story_5089_50890901_30_dialog_content = "허면... 소인은 귀인의 말씀대로 따르겠습니다.",
  ui_story_5089_50890901_31_dialog_content = "네, 전 제가 한 말은 지킬 거예요.",
  ui_story_5089_50890901_32_dialog_content = "휴, 드디어 갔네요.",
  ui_story_5089_50890901_33_dialog_content = "후훗.",
  ui_story_5089_50890901_34_dialog_content = "역시 저 허세 부리는 게 웃겼던 거죠...?",
  ui_story_5089_50890901_35_dialog_content = "그럴 리가 있겠느냐, 방금 PlayerName 공자의 모습은 기개가 넘쳐 경탄했느니라.",
  ui_story_5089_50890901_36_dialog_content = "으음?",
  ui_story_5089_50890901_37_dialog_content = "저기 저 사람들은...",
  ui_story_5089_50890901_38_dialog_content = "<color=#e8d9bb>얼마 전</color>",
  ui_story_5089_50890901_39_dialog_content = "똑똑똑──",
  ui_story_5089_50890901_40_dialog_content = "이럴 때 누가 소식을 전한 거지?",
  ui_story_5089_50890901_41_dialog_content = "......",
  ui_story_5089_50890901_42_dialog_content = "선극 사저! 백공원의 사형한테 연락이 왔는데요! 그 아이테르가...",
  ui_story_5089_50890901_43_dialog_content = "휴, 내가 몇 번을 말했어? 궁에서는 사형, 사저라고 부르지 말라고.",
  ui_story_5089_50890901_44_dialog_content = "우리가 당파를 만들 뜻은 없긴 해도, 괜히 오해받을 행동은 하지 않는 게 좋아.",
  ui_story_5089_50890901_45_dialog_content = "왕년의 후풍경도 그렇게 휘말렸잖아.",
  ui_story_5089_50890901_46_dialog_content = "후풍경이면... 벌써 십여 년도 더 된 일이잖아요.",
  ui_story_5089_50890901_47_dialog_content = "어떤 문파에도 들어가지 않고 외인 신분의 장인들만 따라다면서 배운 비정통 기교사였죠?",
  ui_story_5089_50890901_48_dialog_content = "재능이 뛰어나긴 했지만, 그 재능을 믿고 거만하기도 해서,\n양대 문파의 초빙도 전부 거절했었구요.",
  ui_story_5089_50890901_49_dialog_content = "조정에 들어와 관직을 맡은 뒤엔 급진적인 개혁 의견도 많이 제시했었죠.",
  ui_story_5089_50890901_50_dialog_content = "기관의 매매 제한도 풀려고 했었고, 모든 문파의 자원을 조정이 총괄해야 한다느니\n그런 주장도 했었고요.",
  ui_story_5089_50890901_51_dialog_content = "나라에 대한 충정이 있는 건 맞는데, 실제 상황은 고려하지도 않고 일을 너무 과격하게 했어요.",
  ui_story_5089_50890901_52_dialog_content = "그러니까 그런 신세가 된 거죠. 남 탓할 것도 없어요.\n선극 님은 절대 그런 사람 따라 하지 마세요.",
  ui_story_5089_50890901_53_dialog_content = "그럴 리가 없잖아. 난 말 잘 듣는 신하야.\n봐, 대왕께서 날 가두겠다고 하시니까 순순히 갇혔잖아?",
  ui_story_5089_50890901_54_dialog_content = "선극 님은 왠지 자기가 왜 갇혀 있는지도 잊으신 것 같네요.",
  ui_story_5089_50890901_55_dialog_content = "그 이유가 뭐든, 내가 설계에 참여한 기관포 몇 대 좀 썼다고 그런 건 아닐걸.",
  ui_story_5089_50890901_56_dialog_content = "자, 어디 서신에 뭐라고 쓰여 있는지나 좀 볼까?",
  ui_story_5089_50890901_57_dialog_content = "...아하하, 재미있네, 역시 PlayerName답다니까.",
  ui_story_5089_50890901_58_dialog_content = "기상천외한 발상이긴 해도, 이런 상황에서라면 이게 최선의 해결책일 거야.",
  ui_story_5089_50890901_59_dialog_content = "보아하니 이미 국면을 철저히 파악한 모양이네.",
  ui_story_5089_50890901_60_dialog_content = "뭘 파악해요?",
  ui_story_5089_50890901_61_dialog_content = "별거 아니야. 그것보다 이따가 나 대신 서신 좀 전해줘.",
  ui_story_5089_50890901_62_dialog_content = "난 지금 관직도 없는 그저 평범한 기교사일 뿐이니까, 정무에 관여하는 건 곤란해.",
  ui_story_5089_50890901_63_dialog_content = "하지만 소식을 주고받으면서 종문의 배신자를 처리하는 건 마땅한 일이야.",
  ui_story_5089_50890901_64_dialog_content = "그러니까 사형이 좀 봐줬으면 좋겠다고 전해줘.",
  ui_story_5089_50890901_65_dialog_content = "네, 사저.",
  ui_story_5089_50890901_66_dialog_content = "그리고... 거기 이웃 소저, 괜찮아?",
  ui_story_5089_50890901_67_dialog_content = "......",
  ui_story_5089_50890901_68_dialog_content = "난 후풍경에 대한 얘기를 꺼내면 당신이 입을 열 줄 알았어.",
  ui_story_5089_50890901_69_dialog_content = "십 년 전 조정의 관원이었다가 당쟁에 휘말려 사형을 선고받고 행방불명된 사람.",
  ui_story_5089_50890901_70_dialog_content = "모든 조건에 부합하는 사람은 그 사람뿐이잖아.",
  ui_story_5089_50890901_71_dialog_content = "...이젠 저와는 상관없는 일입니다.",
  ui_story_5089_50890901_72_dialog_content = "이제는 한때 제가 은원에 집착했던 것이 모두 우스운 일이 되고 말았습니다.",
  ui_story_5089_50890901_73_dialog_content = "저는 이미 어떻게 다시 검을 휘둘러야 할지도 모르겠습니다. 아무 쓸모가 없습니다.",
  ui_story_5089_50890901_74_dialog_content = "선극 대인께서도 더는 저 때문에 마음 쓰지 마십시오.",
  ui_story_5089_50890901_75_dialog_content = "오직 한 가지 일만을 위해 살고, 쓸모가 없어지면 버려진다?",
  ui_story_5089_50890901_76_dialog_content = "일전에 그런 말을 들었던 건 요마에 대한 이야기였는데 말이야.",
  ui_story_5089_50890901_77_dialog_content = "구 소저, 질문 하나 할게.",
  ui_story_5089_50890901_78_dialog_content = "사람과 요마의 가장 큰 차이점이 뭐라고 생각해?",
  ui_story_5089_50890901_79_dialog_content = "......",
  ui_story_5089_50890901_80_dialog_content = "차이가 있습니까?",
  ui_story_5089_50890901_81_dialog_content = "휴, 아무래도 난 안 될 것 같아요.",
  ui_story_5089_50890901_82_dialog_content = "당신한테 맡길게.",
  ui_story_5089_50890901_83_dialog_content = "......",
  ui_story_5089_50890901_84_dialog_content = "PlayerName 공자, 무슨 생각을 하느냐.",
  ui_story_5089_50890901_85_dialog_content = "사람과 암귀의 차이가 뭘까요?",
  ui_story_5089_50890901_86_dialog_content = "으음?",
  ui_story_5089_50890901_87_dialog_content = "아니에요, 아무것도... 방금 뭐라고 했어요?",
  ui_story_5089_50890901_88_dialog_content = "지금 설치한 방책을 「천명」이 강제로 돌파하려 한다면, 저들을 막아낼 수 없을 게다.",
  ui_story_5089_50890901_89_dialog_content = "그러니 이제 원군을 부를 때가 되었다.",
  ui_story_5089_50890901_90_dialog_content = "경양성에는 수용할 수 있는 병력이 제한되어 있다.\n하여 대부분의 경위군은 평소 성 밖에 주둔하고 있지.",
  ui_story_5089_50890901_91_dialog_content = "비록 성안의 정예 병력에는 견줄 수 없으나, 지금 우리에게 부족한 것은 세의 규모다.",
  ui_story_5089_50890901_92_dialog_content = "그럼 빨리 가요. 단당 씨 신분으로 병력을 동원할 수 있다고 했죠?",
  ui_story_5089_50890901_93_dialog_content = "PlayerName 공자.",
  ui_story_5089_50890901_94_dialog_content = "...그 칼은 왜 갑자기 주는 건데요?",
  ui_story_5089_50890901_95_dialog_content = "비록 성 밖에 주둔하고 있다고는 하나, 경위군은 내외가 하나의 조직이다.\n성안의 소식은 이미 이곳으로 전해졌을 게야.",
  ui_story_5089_50890901_96_dialog_content = "나나 그대나 이미 잘 알고 있을 것이야.\n일이 이렇게 된 이상, 가짜 숙부는 더는 내 사정을 봐줄 이유가 없다.",
  ui_story_5089_50890901_97_dialog_content = "아마 저들은 더는 내 신분을 가지고 동원할 수 없을 게다.",
  ui_story_5089_50890901_98_dialog_content = "그럼 우린 여기 왜 온 건데요?",
  ui_story_5089_50890901_99_dialog_content = "자.",
  ui_story_5089_50890901_100_dialog_content = "...그러니까 그 칼은 왜 주는 거냐구요.",
  ui_story_5089_50890901_101_dialog_content = "지금 이곳의 경위군이 어떤 명령을 받았는지는 알 수 없다.",
  ui_story_5089_50890901_102_dialog_content = "허나 가짜 숙부가 여전히 제 신분을 감추고자 한다면,\n적어도 겉으로는 나를 해치지 못할 것이야.",
  ui_story_5089_50890901_103_dialog_content = "따라서 저들에게 작화군주는 여전히 지켜야 할 대상이겠지. 하여...",
  ui_story_5089_50890901_104_dialog_content = "제가 단당 씨를 납치한 것처럼 연기해서 저 병사들을 공방으로 유인하겠다는 거예요?",
  ui_story_5089_50890901_105_dialog_content = "그건 너무 위험해요. 무슨 일이 일어날지 전혀 예측할 수가 없잖아요.",
  ui_story_5089_50890901_106_dialog_content = "만약 우리가 바로 잡히면요? 만약 가짜 국왕이 미쳐서 진짜로 단당 씨를 죽이려고 한다면요?",
  ui_story_5089_50890901_107_dialog_content = "그냥 일단 돌아가요. 같이 다른 방법을 생각해 볼...",
  ui_story_5089_50890901_108_dialog_content = "<color=#e8d9bb>단당은 갑자기 칼을 든 당신의 손을 쥐고, 재빨리 자신의 목을 그었다.</color>",
  ui_story_5089_50890901_109_dialog_content = "단당 씨!",
  ui_story_5089_50890901_110_dialog_content = "<color=#e8d9bb>당신은 필사적으로 칼을 치웠지만, 날카로운 칼날은 그녀의 목에 붉은 자국을 남겼다.</color>",
  ui_story_5089_50890901_111_dialog_content = "PlayerName 공자, 나를 보거라.",
  ui_story_5089_50890901_112_dialog_content = "<color=#e8d9bb>핏방울이 칼날을 타고 당신의 손바닥으로 미끄러져 들어왔지만,\n단당은 나무 그늘로 가려진 하늘 아래에서 가볍게 미소 지었다.</color>",
  ui_story_5089_50890901_113_dialog_content = "나는 그대를 믿는다.",
  ui_story_5089_50890901_114_dialog_content = "...알겠어요.",
  ui_story_5089_50890901_115_dialog_content = "거기 누구냐!",
  ui_story_5089_50890901_116_dialog_content = "가까이 오지 마!",
  ui_story_5089_50890901_117_dialog_content = "너희 작화군주의 목숨은 내 손에 달렸어.",
  ui_story_5089_50890901_118_dialog_content = "!",
  ui_story_5089_50890901_119_dialog_content = "악한이 군주 전하를 납치했다! 전군 집결하라!",
  ui_story_5089_50890901_120_dialog_content = "당장 군주 전하를 놓아라! 그럼 네 목숨만은 살려줄 수 있다!",
  ui_story_5089_50890901_121_dialog_content = "어떻게 놓으라고 바로 놓냐? 그리고 너흰 나한테 위협이 안 돼.",
  ui_story_5089_50890901_122_dialog_content = "난 「천명」의 일원이다! 우리의 거점은 근처에 있고, 안에 대량의 병기가 있다!",
  ui_story_5089_50890901_123_dialog_content = "경솔하게 움직이지 않는 게 좋을걸. 우린 언제든지 너희랑 같이 죽을 수 있으니까.",
  ui_story_5089_50890901_124_dialog_content = "궁수!",
  ui_story_5089_50890901_125_dialog_content = "(강제 감응!)",
  ui_story_5089_50890901_126_dialog_content = "으악──",
  ui_story_5089_50890901_127_dialog_content = "놓치지 마라!",
  ui_story_5089_50890901_128_dialog_content = "대장님! 군주 전하와 악한 모두 사라졌습니다!",
  ui_story_5089_50890901_129_dialog_content = "빨리 안 쫓고 뭐 하는 것이냐! 군주 전하께 무슨 변고라도 생기면\n우리가 감당할 수 있겠느냐!",
  ui_story_5089_50890901_130_dialog_content = "하지만 어디로 가야... 아! 여기 해당화 한 송이가 있습니다!",
  ui_story_5089_50890901_131_dialog_content = "틀림없이 군주 전하께서 남긴 단서일 것이다. 그쪽으로 추격하라!",
  ui_story_5089_50890901_132_dialog_content = "반드시 놈들의 거점을 찾아야 한다!",
  ui_story_5089_50890901_133_dialog_content = "대왕 전하, 성 밖의 경위군 부대 하나가 공방 쪽으로 향했습니다.",
  ui_story_5089_50890901_134_dialog_content = "어찌 된 일이냐.",
  ui_story_5089_50890901_135_dialog_content = "군주를 납치한 악한을 발견했다고 하더군요.",
  ui_story_5089_50890901_136_dialog_content = "경위군의 장수는 감히 홀대할 수 없어 즉시 군사를 이끌고 향했습니다.",
  ui_story_5089_50890901_137_dialog_content = "또한 지금 공방은 경위군에게 포위되어 있을 뿐만 아니라, 주변의 도로도 봉쇄되어 있습니다.",
  ui_story_5089_50890901_138_dialog_content = "아무래도 곧 협공을 당할 듯합니다.",
  ui_story_5089_50890901_139_dialog_content = "저희 쪽에서 당분간 공방 내 상황을 통제하고, 저들이 움직이지 않도록 할 수 있습니다.",
  ui_story_5089_50890901_140_dialog_content = "허나 그들은 여전히 대왕 전하께서 어찌 생각하시는지 알고 싶어 합니다.",
  ui_story_5089_50890901_141_dialog_content = "훗.",
  ui_story_5089_50890901_142_dialog_content = "건곤일척을 위해 준비한 것이 고작 그 정도인가.",
  ui_story_5089_50890901_143_dialog_content = "가자.",
  ui_story_5089_50890901_144_dialog_content = "과인을 나서게 만들 심산이라면, 과인이 직접 상대해 주겠다.",
  ui_story_5089_50890901_145_dialog_content = "<color=#e8d9bb>잠시 후</color>",
  ui_story_5089_50890901_146_dialog_content = "(휴, 드디어 갔군요.)",
  ui_story_5089_50890901_147_dialog_content = "(역시 등잔 밑이 어둡다는 말처럼, 적의 코앞에 숨는 게 가장 안전하지요.)",
  ui_story_5089_50890901_148_dialog_content = "(허나 저분이 반나절 동안 꿈쩍도 않을 줄 누가 알았겠습니까.\n앉아서 무슨 생각을 하고 있는지, 궁궐이 망가졌는데 수리도 안 시키고 말입니다.)",
  ui_story_5089_50890901_149_dialog_content = "(대들보가 넓어서 망정이지, 아니었으면 팔다리가 저려서 못 견딜 뻔했네요.)",
  ui_story_5089_50890901_150_dialog_content = "(이제 다들 갔으니 저도 궁 밖으로 나갈 수 있겠지요.)",
  ui_story_5089_50890901_151_dialog_content = "(흐음? 이건... 구 소저의 검 아닙니까?)",
  ui_story_5089_50890901_152_dialog_content = "(뭐, 그럼 이번엔 이걸 가져다드려야겠군요.)",
  ui_story_5089_50890901_153_dialog_content = "후우... 하아... 이렇게 죽어라 뛰고 있는데...",
  ui_story_5089_50890901_154_dialog_content = "저 경위군들... 어떻게 저렇게 빨리 쫓아온 거죠?",
  ui_story_5089_50890901_155_dialog_content = "해당화를 놓아서 최대한 잘못된 길로 안내했건만, 내 예상보다 반응이 빠르구나.",
  ui_story_5089_50890901_156_dialog_content = "또한 기강이 잡혀 있는 것을 보면, 필시 평소에도 훈련을 게을리하지 않았을 게야.",
  ui_story_5089_50890901_157_dialog_content = "저 가짜 숙부는 줄곧 병사를 훈련시키고, 많은 병기를 필요로 하고 있다...",
  ui_story_5089_50890901_158_dialog_content = "「천명」의 의도는 대체 무엇이란 말이냐...",
  ui_story_5089_50890901_159_dialog_content = "지금 생각해 봤자 소용없어요. 어차피 우리가 할 수 있는 건 다 했으니까요.",
  ui_story_5089_50890901_160_dialog_content = "일단 여기서 좀 쉬어요.",
  ui_story_5089_50890901_161_dialog_content = "공방 쪽은 아직 움직임이 없지만, 상황이 달라지면 뭔가 반응을 보이겠죠.",
  ui_story_5089_50890901_162_dialog_content = "<color=#e8d9bb>뒤에는 잘 훈련된 경위군이 산개하여 두 사람을 포위했고,\n그들의 손에 든 횃불은 밤하늘을 붉게 물들였다.</color>",
  ui_story_5089_50890901_163_dialog_content = "<color=#e8d9bb>앞에는 「천명」의 공방이 있고, 인적은 있으나 사람의 모습은 보이지 않았다.\n그것은 마치 칩거하는 거대한 짐승처럼 기이하고 어두웠다.</color>",
  ui_story_5089_50890901_164_dialog_content = "PlayerName 공자, 내 전에 미처 말하지 못한 것이 있다.",
  ui_story_5089_50890901_165_dialog_content = "비록 내 뻔뻔하게도 그대에게 도움을 청했으나,\n그대를 오늘과 같은 위험에 빠트릴 마음은 없었다.",
  ui_story_5089_50890901_166_dialog_content = "실로 참괴한 마음뿐이다.",
  ui_story_5089_50890901_167_dialog_content = "괜찮아요. 다 잘될 거예요.",
  ui_story_5089_50890901_168_dialog_content = "저도 단당 씨를 믿어요.",
  ui_story_5089_50890901_169_dialog_content = "어라? 경위군 쪽에 뭔가 움직임이 있는데요...",
  ui_story_5089_50890901_170_dialog_content = "대왕 전하 납시오!",
  ui_story_5089_50890901_171_dialog_content = "저 사람이 바로...",
  ui_story_5089_50890901_172_dialog_content = "나의 가짜 숙부다.",
  ui_story_5089_50890901_173_dialog_content = "단당, 나는 네가 조금은 더 총명할 줄 알았다.",
  ui_story_5089_50890901_174_dialog_content = "과인이 명만 내리면 저 공방이 해를 입지 않으리라는 것은 생각지 못하였느냐.",
  ui_story_5089_50890901_175_dialog_content = "오직 너희만이 이곳에서 죽을 것이다.",
  ui_story_5089_50890901_176_dialog_content = "그야말로 스스로 그물에 걸려든 꼴이 아니더냐.",
  ui_story_5089_50890901_177_dialog_content = "그대가 정녕 나의 숙부라면 응당 그러할 권리가 있었겠지.",
  ui_story_5089_50890901_178_dialog_content = "허나 그대는 사시이비한 일개 꼭두각시에 불과하거늘, 어찌 감히 이토록 방자하단 말이냐!",
  ui_story_5089_50890901_179_dialog_content = "이제 모든 이의 앞에서 그대의 가면을 벗겨주마── 후풍경!",
  ui_story_5089_50890902_1_dialog_content = "PlayerName 공자, 지금이다!",
  ui_story_5089_50890902_2_dialog_content = "(강제 감응!)",
  ui_story_5089_50890902_3_dialog_content = "으윽...",
  ui_story_5089_50890902_4_dialog_content = "(경위군에 시간을 낭비하면 안 돼. 우리 목적은 이 사람들과 싸우는 게 아니니까.)",
  ui_story_5089_50890902_5_dialog_content = "(「천명」의 역용술은 모두 얼굴 가죽을 이용한 위장술이야.)",
  ui_story_5089_50890902_6_dialog_content = "(기회를 찾아야 해. 단 한 순간만이라도... 녀석의 가면을 긁을 수만 있다면──!)",
  ui_story_5089_50890902_7_dialog_content = "?!",
  ui_story_5089_50890902_8_dialog_content = "<color=#e8d9bb>칼날은 가짜 업왕의 옆얼굴을 베었다.</color>",
  ui_story_5089_50890902_9_dialog_content = "<color=#e8d9bb>그러나 갈라진 것은 예상과 같은 무기질의 가면이 아니었다.</color>",
  ui_story_5089_50890902_10_dialog_content = "<color=#e8d9bb>칼날 아래에서는 선혈이 새어 나왔고, 그것이 실제 살아있는 피부임을 드러냈다.</color>",
  ui_story_5089_50890902_11_dialog_content = "어째서...",
  ui_story_5089_50890902_12_dialog_content = "이제 확인이 되었느냐.",
  ui_story_5089_50890902_13_dialog_content = "너희들이 원하는 결과는 얻었나?",
  ui_story_5089_50891001_1_dialog_content = "대...대왕 전하! 어서 전하를 지켜라! 다들 뭘 멍하니 있는 것이냐!",
  ui_story_5089_50891001_2_dialog_content = "모두 물러가라, 아이가 소란을 피우고 있을 뿐이다.",
  ui_story_5089_50891001_3_dialog_content = "아니... 당신이 진짜 국왕일 리가 없는데, 어떻게...",
  ui_story_5089_50891001_4_dialog_content = "너희가 애써 도모한 것이 고작 이것이라니, 참으로 어리석구나.",
  ui_story_5089_50891001_5_dialog_content = "내가 오랜 시간 이 신분을 사용하는 동안, 아무도 이상한 점을 찾지 못했다.",
  ui_story_5089_50891001_6_dialog_content = "설마 내가 매일 가면 속에 숨어서 연명하는 망령이라 생각했던 것이냐?",
  ui_story_5089_50891001_7_dialog_content = "!",
  ui_story_5089_50891001_8_dialog_content = "나는 십 년 전부터 줄곧 내 얼굴을 다듬었다.",
  ui_story_5089_50891001_9_dialog_content = "피와 살을 베고, 뼈를 깎았지.",
  ui_story_5089_50891001_10_dialog_content = "팔 모양이 안 맞는다면 잘라서 다시 이으면 그만이다.",
  ui_story_5089_50891001_11_dialog_content = "말소리가 다르다면 독을 마시고 목이 쉬면 된다.",
  ui_story_5089_50891001_12_dialog_content = "즉위 전 숙부는 자주 암살 시도를 당했다고 일찍이 들은 적 있었는데... 그랬던 것인가.",
  ui_story_5089_50891001_13_dialog_content = "「천명」을 위해 그대는 실로 전력을 다하는지고.",
  ui_story_5089_50891001_14_dialog_content = "「천명」? 흥, 고작해야 그림자 속에 숨기만 하는 쥐 떼들일 뿐이다.",
  ui_story_5089_50891001_15_dialog_content = "자신들이 뭐라도 된다고 생각하는 것인지, 감히 과인의 업나라를 건드리다니!",
  ui_story_5089_50891001_16_dialog_content = "......",
  ui_story_5089_50891001_17_dialog_content = "작금의 대법은 불안정하고, 어린 황제는 천하를 주관할 능력이 없다.\n풍운이 동요하니 난세가 곧 닥칠 것이다.",
  ui_story_5089_50891001_18_dialog_content = "내 본디 제나라와의 관계를 염려하여 일을 천천히 도모하고자 했다.",
  ui_story_5089_50891001_19_dialog_content = "허나 일이 이렇게 되었으니, 병기를 모두 「천명」에게 맡긴들 또 어떠하겠느냐.",
  ui_story_5089_50891001_20_dialog_content = "저들은 병기를 손에 넣자마자 거사를 일으킬 것이다.",
  ui_story_5089_50891001_21_dialog_content = "「천명」은 이미 오랫동안 각국에 침투했고, 호진성의 재해는 필시 도처에서 되풀이될 것이다.\n제후국들은 자기들 일만으로 벅찰 것이고, 「천명」은 곧바로 조나라 앙경을 노리겠지.",
  ui_story_5089_50891001_22_dialog_content = "사마귀가 매미를 잡을 때, 나는 그 뒤에 있는 참새가 될 것이다.",
  ui_story_5089_50891001_23_dialog_content = "후풍, 후풍... 후풍경은 결코 오지 않는 그 동풍을 평생 기다렸다.",
  ui_story_5089_50891001_24_dialog_content = "허나 이번에는 과인이 직접 그 바람을 일으킬 것이다!",
  ui_story_5089_50891001_25_dialog_content = "십 년간, 과인은 병마를 기르고 싸움을 준비했다.",
  ui_story_5089_50891001_26_dialog_content = "군웅의 각축이 벌어질 때, 시작되는 것이 꼭 「천명」만의 「형세」는 아닐 터.",
  ui_story_5089_50891001_27_dialog_content = "단당, 너는 이미 과인의 비밀을 알고 있다.",
  ui_story_5089_50891001_28_dialog_content = "비록 네 오늘 소행은 어리석었으나, 그럼에도 너는 여전히 현명한 인재다.\n과인을 따를 뜻이 있느냐?",
  ui_story_5089_50891001_29_dialog_content = "네가 고개만 끄덕이면, 과인은 네가 계속 작화군주 노릇을 할 수 있게 해주마.",
  ui_story_5089_50891001_30_dialog_content = "또한 그쪽의 이방인, 네 능력은 전장에서 큰 역할을 할 수 있다.\n과인의 휘하로 들어올 뜻이 있느냐?",
  ui_story_5089_50891001_31_dialog_content = "훗날 칠국을 평정하고...",
  ui_story_5089_50891001_32_dialog_content = "그대는 「천명」이 요마와 결탁하고, 백성들의 목숨조차 괄시하는 무리임을 아는가.",
  ui_story_5089_50891001_33_dialog_content = "「천명」의 병기 비축량은 대부분 업나라에 의존하고 있다. 그러니 과인도 물론 알고 있지.",
  ui_story_5089_50891001_34_dialog_content = "허나 과인을 위해 쓰이지 않는다면, 타국 백성의 목숨이 과인과 무슨 상관이냐.\n적을 위해 걱정하는 것은 아녀자의 인애일 뿐이다.",
  ui_story_5089_50891001_35_dialog_content = "축생만도 못한 요마와 결탁함은 수치스러운 일이나, 「천명」은 본디 간사한 소인배들이니,\n저들의 행태도 무리는 아니다.",
  ui_story_5089_50891001_36_dialog_content = "마음에 들지 않는다면 다 쓰고 죽이면 그만이다.",
  ui_story_5089_50891001_37_dialog_content = "그대의 생각은 잘 알겠다. 보아하니 우리는...",
  ui_story_5089_50891001_38_dialog_content = "도를 달리하니, 뜻을 같이할 수 없을 것이야.",
  ui_story_5089_50891001_39_dialog_content = "호의도 모르는구나.",
  ui_story_5089_50891001_40_dialog_content = "저기... 나도 궁금한 게 있어.",
  ui_story_5089_50891001_41_dialog_content = "당신 말이야. 그런 걸 죄다 말해버려도 괜찮은 거야?",
  ui_story_5089_50891001_42_dialog_content = "「천명」의 공방이 바로 옆에 있는데?",
  ui_story_5089_50891001_43_dialog_content = "과인이 너희 같은 줄 아느냐. 저 공방은 과인이 이미 봉쇄했다.",
  ui_story_5089_50891001_44_dialog_content = "거사를 하려면 「천명」은 과인의 병기를 필요로 한다.",
  ui_story_5089_50891001_45_dialog_content = "병기만 손에 넣는다면, 공방의 저자들이 죽든 살든 관심도 없을 것이다.",
  ui_story_5089_50891001_46_dialog_content = "하지만 삼 일 안에 당신 병기가 전달되지 않는다면?",
  ui_story_5089_50891001_47_dialog_content = "...어떻게 알았지?",
  ui_story_5089_50891001_48_dialog_content = "아이테르의 능력이 유용하다면서? 이건 몰랐나 봐?",
  ui_story_5089_50891001_49_dialog_content = "지금 중요한 건 당신이 그 삼 일의 기한을 지킬 수 없게 됐다는 거야.",
  ui_story_5089_50891001_50_dialog_content = "무슨 짓을 한 것이냐?",
  ui_story_5089_50891001_51_dialog_content = "대왕 전하! 큰일입니다!",
  ui_story_5089_50891001_52_dialog_content = "말해라!",
  ui_story_5089_50891001_53_dialog_content = "백공원 쪽 사람들이 화룡연의 궤도를 철거하고 있습니다!\n저희가 원래 정했던 운송 노선이 전부 폐기되었습니다!",
  ui_story_5089_50891001_54_dialog_content = "누가 이를 허락했단 말이냐!",
  ui_story_5089_50891001_55_dialog_content = "백공원에서...",
  ui_story_5089_50891001_56_dialog_content = "그냥 선의의 투자자가 금을 약간 기부했을 뿐이야.",
  ui_story_5089_50891001_57_dialog_content = "임차인의 부적절한 사용 때문에 과도하게 마모된 철도를 그 돈으로 보수하기로 했어.",
  ui_story_5089_50891001_58_dialog_content = "그리고 그 유일한 조건은 철거할 선로의 순서를 지정한다는 것뿐, 이 정도면 합리적이지 않아?",
  ui_story_5089_50891001_59_dialog_content = "그리고 겸사겸사 당신 시선도 끌었고 말이야.",
  ui_story_5089_50891001_60_dialog_content = "오늘 오후부터 작업을 시작한다면, 바로 복구를 시작해도 아마 삼 일 이상 걸릴 거야.",
  ui_story_5089_50891001_61_dialog_content = "처음부터 내가 사고 싶었던 건 바로 이 「길」이었어.",
  ui_story_5089_50891001_62_dialog_content = "고작 뒤에서 그런 얄팍한 수작 부린 정도로 으스대기는! 대왕 전하께서 명령만 내리시면──!",
  ui_story_5089_50891001_63_dialog_content = "멍청한 놈, 썩 꺼져라!",
  ui_story_5089_50891001_64_dialog_content = "뭐, 내 수단이 얄팍해 보일 순 있을 거야.",
  ui_story_5089_50891001_65_dialog_content = "근데 지금부터 중요한 건 우리가 무슨 수단을 썼는지가 아니란 걸 당신도 알겠지?",
  ui_story_5089_50891001_66_dialog_content = "백공원이 네 편에 서다니... 선기경인가.",
  ui_story_5089_50891001_67_dialog_content = "선극 씨가 감옥에 간 건 멋대로 병기를 동원해서가 아니라, 당신 비밀을 발견했기 때문이겠지.",
  ui_story_5089_50891001_68_dialog_content = "그러니까 선극 씨를 진짜로 가둬버리지 못한 시점부터, 당신은 진 거야.",
  ui_story_5089_50891001_69_dialog_content = "아무리 당신이 국왕의 왕좌에 앉아 있다고 해도...",
  ui_story_5089_50891001_70_dialog_content = "조정의 관리들과 기교사들은 모두 당신의 일거수일투족을 주시하고 있을 거야.",
  ui_story_5089_50891001_71_dialog_content = "화룡연의 궤도도 철거할 수 있고, 목우유마의 축도 부서질 수 있어.",
  ui_story_5089_50891001_72_dialog_content = "마차로 바꾼다 해도 말의 힘으론 한계가 있을 거야.",
  ui_story_5089_50891001_73_dialog_content = "게다가 화룡연 외의 도구들은 그 많은 양의 화물을 신속하게 운송하기 어렵겠지.",
  ui_story_5089_50891001_74_dialog_content = "물론 가장 중요한 건...",
  ui_story_5089_50891001_75_dialog_content = "저 많은 사람들 앞에서, 왜 기록에도 없는 대량의 병기를 다른 곳으로 보내야 하는지\n어떻게 설명할 건데?",
  ui_story_5089_50891001_76_dialog_content = "......",
  ui_story_5089_50891001_77_dialog_content = "미안하게 됐네요, 국왕님.",
  ui_story_5089_50891001_78_dialog_content = "이제부터 어떻게 될지는 아직 알 수 없겠지.",
  ui_story_5089_50891001_79_dialog_content = "하지만 적어도 지금의 「형세」는 나한테 있어.",
  ui_story_5089_50891001_80_dialog_content = "그랬군.",
  ui_story_5089_50891001_81_dialog_content = "네가 막은 건 「천명」이 아니라 나의 길이었던 것인가.",
  ui_story_5089_50891001_82_dialog_content = "그대는 우리가 스스로 그물에 걸렸다고 하면서,\n왜 자신이 놓은 덫에 걸린다는 생각은 못 한 것이냐.",
  ui_story_5089_50891001_83_dialog_content = "후풍경, 그대는 이미 선택의 여지가 없다.",
  ui_story_5089_50891001_84_dialog_content = "병기가 제때 전해지지 않는다면, 「천명」은 반드시 조사하러 올 것이다.",
  ui_story_5089_50891001_85_dialog_content = "그리고 방금 그대가 말한 대로라면, 그대는 「천명」에 그다지 충심을 품고 있지 않으니,\n그대의 소행으로는 저들의 조사를 견디지 못할 것 같구나.",
  ui_story_5089_50891001_86_dialog_content = "하면 이제 서로 앉아서 차분히 이야기해 볼 수 있지 않겠는가.",
  ui_story_5089_50891001_87_dialog_content = "요마와 「천명」 조직은 그대가 생각하는 것처럼 그리 간단하지 않다.\n그대의 계획은 호랑이에게 가죽을 달라는 것이나 다를 바가 없다.",
  ui_story_5089_50891001_88_dialog_content = "하하하, 이야기? 과인은 이 나라의 임금이다!",
  ui_story_5089_50891001_89_dialog_content = "업나라의 길은 오직 과인 한 사람만이 주관할 수 있다!",
  ui_story_5089_50891001_90_dialog_content = "결코 네놈들의 방해를 받지 않는다!",
  ui_story_5089_50891001_91_dialog_content = "<color=#e8d9bb>푸욱──</color>",
  ui_story_5089_50891001_92_dialog_content = "<color=#e8d9bb>칼날이 살을 파고드는 소리가 전해졌다.</color>",
  ui_story_5089_50891001_93_dialog_content = "<color=#e8d9bb>그와 함께, 피가 사방으로 튀었다.</color>",
  ui_story_5089_50891001_94_dialog_content = "후풍경──!",
  ui_story_5089_50891001_95_dialog_content = "<color=#e8d9bb>날카로운 금속 갈고리 꼬리가 등 뒤에서 가짜 업왕의 몸을 관통했다.</color>",
  ui_story_5089_50891001_96_dialog_content = "저건... 비채?!",
  ui_story_5089_50891001_97_dialog_content = "휴, 순순히 말을 들었으면 좋았잖아.",
  ui_story_5089_50891001_98_dialog_content = "오직 내 기관술처럼 오랫동안 검증된 백가의 장점을 착실하게 흡수해야,\n이렇게 아름다운 성과를 낼 수 있는 거야.",
  ui_story_5089_50891001_99_dialog_content = "현실성 없는 웅대한 포부 따윈 목숨만 앗아갈 뿐이라고.",
  ui_story_5089_50891001_100_dialog_content = "감히 날... 무엄하다!",
  ui_story_5089_50891001_101_dialog_content = "유라 군주님 말씀 중에 하나는 맞더라고.",
  ui_story_5089_50891001_102_dialog_content = "당신은 「천명」을 너무 우습게 봤어.",
  ui_story_5089_50891001_103_dialog_content = "주상의 명이 내려왔어. 업나라는 이제 더는 쓸모없어.",
  ui_story_5089_50891001_104_dialog_content = "이 땅은 이제 내 마음대로 처분할 수 있고, 심지어 최대 전력을 사용해서\n비채의 화력을 시험할 수도 있어!",
  ui_story_5089_50891001_105_dialog_content = "아하하, 이렇게 좋은 일이 생기다니, 이게 다 우리 대왕 전하께서\n촉음화를 나한테 준 덕분 아니겠어?",
  ui_story_5089_50891001_106_dialog_content = "어디 보자, 명령은... 저 산을 폭파하라고?",
  ui_story_5089_50891001_107_dialog_content = "자, 이제 가자, 비채. 목표 조준, 동력 정비... 아직 해야 할 일이 많아.",
  ui_story_5089_50891001_108_dialog_content = "<color=#e8d9bb>비채가 갈고리 꼬리를 뽑자 가짜 업왕이 쓰러졌다.</color>",
  ui_story_5089_50891001_109_dialog_content = "그나저나, 여기 쓸모없는 배신자들이 더 있는데...",
  ui_story_5089_50891001_110_dialog_content = "「천명」은 명에 따라 배신자를 주살하라!",
  ui_story_5089_50891001_111_dialog_content = "대왕 전하──",
  ui_story_5089_50891001_112_dialog_content = "<color=#e8d9bb>먼 곳의 경위군이 움직이려던 순간, 가지런하던 병사들의 대열이 갑자기 흐트러졌다.</color>",
  ui_story_5089_50891001_113_dialog_content = "<color=#e8d9bb>대열 속 많은 이들이 무기를 들고 옆에 서 있는 동료들을 찔렀던 것이었다.</color>",
  ui_story_5089_50891001_114_dialog_content = "이런! 가짜 국왕 쪽이...",
  ui_story_5089_50891001_115_dialog_content = "「꽃이여, 흐드러지게 피어라!」",
  ui_story_5089_50891001_116_dialog_content = "너...",
  ui_story_5089_50891001_117_dialog_content = "오해하지 마라. 내 그대의 초대를 사양하려는 뜻은 변함이 없으니.",
  ui_story_5089_50891001_118_dialog_content = "허나 그대가 살아있는 한, 우리는 「천명」을 상대할 패를 쥘 수 있다.",
  ui_story_5089_50891001_119_dialog_content = "게다가 그대는 아직 다른 이와 풀어야 할 은원이 있다.",
  ui_story_5089_50891001_120_dialog_content = "하필... 크윽...",
  ui_story_5089_50891001_121_dialog_content = "지금 가지 않으면... 후회해도... 늦을 것이다.",
  ui_story_5089_50891001_122_dialog_content = "설령 후회하더라도, 내가 후회해야 할 것은 궁에서 승부를 걸었을 때\n그대의 자리를 대신하지 않은 것이다.",
  ui_story_5089_50891001_123_dialog_content = "저 산 아래에는 아직도 수많은 무고한 백성들이 살고 있고,\n식량을 공급하여 백성들을 살아가게 할 농토가 있다.",
  ui_story_5089_50891001_124_dialog_content = "만약 지금 도망친다면, 내가 무슨 낯으로 업나라의 작화군주라고 하겠느냐.",
  ui_story_5089_50891001_125_dialog_content = "게다가 나와 PlayerName 공자는 아직 여기 잘 서 있다. 줄행랑이나 칠 때가 아니다!",
  ui_story_5089_50891001_126_dialog_content = "하... 전혀 몰랐구나, 네가...",
  ui_story_5089_50891001_127_dialog_content = "나보다 더 방자할 줄은.",
  ui_story_5089_50891001_128_dialog_content = "그래도... 좋다... 살아서 다시 이야기하도록 하지.",
  ui_story_5089_50891001_129_dialog_content = "<color=#e8d9bb>그러나 경위군들 사이의 전투도 아직 끝나지 않았는데,\n공방에서 연이어 「천명」의 자객들이 나타났다.</color>",
  ui_story_5089_50891002_1_dialog_content = "전투가 이대로 계속된다면, 아마 결과는 좋지 않을 거야.",
  ui_story_5089_50891002_2_dialog_content = "구 소저.",
  ui_story_5089_50891002_3_dialog_content = "저런 모습을 보고도 당신은 여전히 한마디도 안 할 셈이야?",
  ui_story_5089_50891002_4_dialog_content = "......",
  ui_story_5089_50891002_5_dialog_content = "어라...?",
  ui_story_5089_50891002_6_dialog_content = "누구냐!",
  ui_story_5089_50891002_7_dialog_content = "주상의 명을 받들어 방해자를 없애라.",
  ui_story_5089_50891002_8_dialog_content = "쳇, 이젠 궁까지 침투한 건가?",
  ui_story_5089_50891002_9_dialog_content = "「뇌광의 기철!」",
  ui_story_5089_50891002_10_dialog_content = "......",
  ui_story_5089_50891002_11_dialog_content = "!",
  ui_story_5089_50891002_12_dialog_content = "꺼져!",
  ui_story_5089_50891002_13_dialog_content = "구 소저! 다른 일은 이제 마음에 두고 싶지 않다고 해도...",
  ui_story_5089_50891002_14_dialog_content = "이름조차 감히 말하지 못하는 이런 쥐새끼들 손에 목숨을 잃을 셈이야?!",
  ui_story_5089_50891002_15_dialog_content = "......",
  ui_story_5089_50891101_1_dialog_content = "으악──",
  ui_story_5089_50891101_2_dialog_content = "잘했어요, 단당 씨. 그렇게 계속.... 으윽...",
  ui_story_5089_50891101_3_dialog_content = "PlayerName 공자, 어찌... 이마가 이리도 뜨거운 게냐!",
  ui_story_5089_50891101_4_dialog_content = "괜찮아요... 그냥 능력을 좀 많이 써서... 금방...",
  ui_story_5089_50891101_5_dialog_content = "이것이 어딜 봐서 금방 좋아진다는 말이냐!",
  ui_story_5089_50891101_6_dialog_content = "...아니야.",
  ui_story_5089_50891101_7_dialog_content = "내 그대를 처음 본 것도 아니고, 그대의 능력에 대서는 익히 알고 있다.",
  ui_story_5089_50891101_8_dialog_content = "지금 비록 적은 많으나, 이 전투 강도로는 그대를 이 정도로 몰아붙일 리 없다.",
  ui_story_5089_50891101_9_dialog_content = "지금 대체 무엇을 하고 있는 게냐.",
  ui_story_5089_50891101_10_dialog_content = "...들켰네요.",
  ui_story_5089_50891101_11_dialog_content = "미안해요. 원래는 말하려고 했는데, 계속 기회가 없더라구요.",
  ui_story_5089_50891101_12_dialog_content = "지금이라면... 직접 보시는 게 더 빠르겠네요.",
  ui_story_5089_50891101_13_dialog_content = "?",
  ui_story_5089_50891101_14_dialog_content = "[감응한다]",
  ui_story_5089_50891101_15_dialog_content = "드디어 오셨군요.",
  ui_story_5089_50891101_16_dialog_content = "한참 기다렸습니다, 군주 전하.",
  ui_story_5089_50891101_17_dialog_content = "선기경! 그리고... 그대 쪽에도...",
  ui_story_5089_50891101_18_dialog_content = "네, 회포를 풀고 싶긴 한데, 이쪽도 불청객이 있어서요.",
  ui_story_5089_50891101_19_dialog_content = "선극 씨, 뒤에!",
  ui_story_5089_50891101_20_dialog_content = "「뇌광의 기철!」",
  ui_story_5089_50891101_21_dialog_content = "PlayerName, 고마워.",
  ui_story_5089_50891101_22_dialog_content = "설마... PlayerName 공자가 그쪽 전투까지 동시에 지휘해 왔단 말이냐!\n그러니 이토록 부담이 되었던 게로구나...",
  ui_story_5089_50891101_23_dialog_content = "맞습니다, 군주 전하. 그리고 이 감응 연결이 언제부터 시작됐는지도 물어보셔야죠.",
  ui_story_5089_50891101_24_dialog_content = "......",
  ui_story_5089_50891101_25_dialog_content = "PlayerName 공자?",
  ui_story_5089_50891101_26_dialog_content = "그, 그렇게 오래된 것도 아니에요... 어제 선극 씨랑 만나고 나서부터였으니까요.",
  ui_story_5089_50891101_27_dialog_content = "꼬박 하루지.",
  ui_story_5089_50891101_28_dialog_content = "그러니까 선극 씨가 말을 명확하게 안 해준 탓이라고...",
  ui_story_5089_50891101_29_dialog_content = "그리고 저도 주의했어요. 일이 없을 땐 너무 긴밀하게 연결되지 않게 말이에요...",
  ui_story_5089_50891101_30_dialog_content = "그래도 끊기지 않으려고 지금까지 잠도 제대로 못 잤잖아.",
  ui_story_5089_50891101_31_dialog_content = "......",
  ui_story_5089_50891101_32_dialog_content = "심지어 나뿐만이 아니잖아.",
  ui_story_5089_50891101_33_dialog_content = "그거라면 구 씨한테 사과해야겠네요.",
  ui_story_5089_50891101_34_dialog_content = "어젯밤에 그런 말씀을 하시니까, 왠지 충동적으로 나올 것 같아서\n몰래 구 씨랑도 감응 연결을 했어요.",
  ui_story_5089_50891101_35_dialog_content = "국왕이랑 싸우는 것도 봤구요.",
  ui_story_5089_50891101_36_dialog_content = "구 씨 마음은 저도 이해할 수 있어요. 하지만...",
  ui_story_5089_50891101_37_dialog_content = "조심해라!",
  ui_story_5089_50891101_38_dialog_content = "으윽...",
  ui_story_5089_50891101_39_dialog_content = "단당 씨! 다쳤어요?!",
  ui_story_5089_50891101_40_dialog_content = "!",
  ui_story_5089_50891101_41_dialog_content = "구 씨! 지금은 상황이 급하니까, 한 명이라도 더 있으면 좋아요. 와서 좀 도와주세요.",
  ui_story_5089_50891101_42_dialog_content = "전... 이제 더는...",
  ui_story_5089_50891101_43_dialog_content = "<color=#e8d9bb>구는 긴 한숨을 내쉬었다.</color>",
  ui_story_5089_50891101_44_dialog_content = "<color=#e8d9bb>그녀는 아무 말 없이 자객이 옆에 떨어트린 단검을 집어 들고,\n선극과의 싸움을 벌이고 있는 「천명」을 찔렀다.</color>",
  ui_story_5089_50891101_45_dialog_content = "!",
  ui_story_5089_50891101_46_dialog_content = "<color=#e8d9bb>상대는 당황하며 몸을 피했지만, 비수는 그저 뒤틀린 곡선만을 그리며 그의 옆을 스친 뒤,\n벽 쪽으로 튕겨져 나갈 뿐이었다.</color>",
  ui_story_5089_50891101_47_dialog_content = "구 소저, 당신...",
  ui_story_5089_50891101_48_dialog_content = "예전에는 도검이 제 몸과 같았습니다.",
  ui_story_5089_50891101_49_dialog_content = "다치는 것도, 피로 물드는 것도 아무 상관 없었습니다.",
  ui_story_5089_50891101_50_dialog_content = "검이 가야 할 궤적은 명확했고, 오직 은혜를 갚기 위해 움직였습니다.",
  ui_story_5089_50891101_51_dialog_content = "그러나 이제 더는 검의 궤적도 보이지 않고, 검도 절 버렸습니다.",
  ui_story_5089_50891101_52_dialog_content = "보시다시피 저는 이제 더는 검을 휘두를 수 없습니다.",
  ui_story_5089_50891101_53_dialog_content = "구 씨...",
  ui_story_5089_50891101_54_dialog_content = "PlayerName 공자, 전황이 급박하니, 무관한 이와 쓸데없는 말을 할 시간 따윈 없다.",
  ui_story_5089_50891101_55_dialog_content = "내 일전에는 그토록 망설였거늘, 이제 보니 저러한 호위를 버린 것이 실로 옳은 선택이었구나.",
  ui_story_5089_50891101_56_dialog_content = "단당 씨?",
  ui_story_5089_50891101_57_dialog_content = "십 년을 하루 같이 검술을 익혔으나, 공든 탑이 하루아침에 무너졌구나.",
  ui_story_5089_50891101_58_dialog_content = "가서 검술을 배워 온 그 천하제일의 검객이란 자도 결국 헛된 명성에 불과했던 것이겠지.",
  ui_story_5089_50891101_59_dialog_content = "...제 배움이 부족했을 뿐, 전하께서 제 은사를 그리 비방하시면 안 됩니다.",
  ui_story_5089_50891101_60_dialog_content = "은사, 그리 보이지는 않는다만.",
  ui_story_5089_50891101_61_dialog_content = "그가 가르침을 베푼 은덕이 네 검에 담긴 것을 내 본 적이 없느니라.",
  ui_story_5089_50891101_62_dialog_content = "......",
  ui_story_5089_50891101_63_dialog_content = "네가 은원을 풀고자 한다면, 내 너와 함께 그 은원을 풀 것이야.",
  ui_story_5089_50891101_64_dialog_content = "크게는 낳고 기른 부모, 돌봐준 이웃, 가르침을 준 스승이 네가 입은 은덕이다.",
  ui_story_5089_50891101_65_dialog_content = "작게는 신풍호에서 월백의 열성과 선기경의 노력이 없었더라면,\n우리는 이미 바다에 묻혔을지도 모르지.",
  ui_story_5089_50891101_66_dialog_content = "하물며 PlayerName 공자는 말할 것도 없지 않느냐.\n아직까지도 널 저버리지 않고 있으니 말이야.",
  ui_story_5089_50891101_67_dialog_content = "허나 이제 보니 이런 것들은 모두 네 안중에 없었구나. 이 모든 성의가 헛된 것이었다니.",
  ui_story_5089_50891101_68_dialog_content = "...전하께서는 이제 남의 마음을 잘 아시는군요.",
  ui_story_5089_50891101_69_dialog_content = "제가 많은 이들에게 많은 빚을 진 것은 물론 알고 있습니다.",
  ui_story_5089_50891101_70_dialog_content = "허나 전하께서는 어떠십니까?",
  ui_story_5089_50891101_71_dialog_content = "저는 전하 곁에서 충성을 다하며, 한시도 소홀하지 않았다고 자부합니다.",
  ui_story_5089_50891101_72_dialog_content = "허나 전하께선 아무 말도 없이 절 헌신짝처럼 버리지 않으셨습니까!",
  ui_story_5089_50891101_73_dialog_content = "역시 화를 낼 줄 알지 않느냐.",
  ui_story_5089_50891101_74_dialog_content = "나는 네가 진즉 피도 눈물도 없는 인형이 된 줄 알았다.",
  ui_story_5089_50891101_75_dialog_content = "실망하셨습니까?",
  ui_story_5089_50891101_76_dialog_content = "그렇다.",
  ui_story_5089_50891101_77_dialog_content = "아직 칠정육욕이 남아 있고, 아직 뭇사람의 관심을 받음을 알고 있으면서...",
  ui_story_5089_50891101_78_dialog_content = "어찌 네 검은 여전히 그 은원에 얽매여 있단 말이더냐!",
  ui_story_5089_50891101_79_dialog_content = "전하...?",
  ui_story_5089_50891101_80_dialog_content = "단당 씨, 뒤에──!",
  ui_story_5089_50891101_81_dialog_content = "「바람이여, 흩어져라.」",
  ui_story_5089_50891101_82_dialog_content = "<color=#e8d9bb>그녀는 고개를 돌리지 않았지만, 무수히 많은 해당화가 파도처럼 펼쳐져 사방을 휩쓸었다.</color>",
  ui_story_5089_50891101_83_dialog_content = "내 너에게 알려주고 싶은 것이 하나 있다.",
  ui_story_5089_50891101_84_dialog_content = "내 너를 버린 것은 네가 나보다 다른 이에게 더 충성했기 때문이 아니라,\n네가 모르는 바가 있었기 때문이니라.",
  ui_story_5089_50891101_85_dialog_content = "<color=#e8d9bb>순식간에 시야 속 해당화가 활짝 피어났다.</color>",
  ui_story_5089_50891101_86_dialog_content = "<color=#e8d9bb>이 아름다운 꽃바다에 발을 들여놓은 모든 적은 그 순간 자리에서 멍하니 망연자실할 뿐이었다.</color>",
  ui_story_5089_50891101_87_dialog_content = "<color=#e8d9bb>그 가운데 선 단당의 옷은 피로 물들었지만, 그 눈빛은 위엄이 있었다.\n이는 사람의 마음을 가장 사로잡는 한 줄기 빛깔이었다.</color>",
  ui_story_5089_50891101_88_dialog_content = "대도를 이룸에 있어 무수한 하늘의 안배가 있으나, 인간 스스로 열 길은 오직 하나뿐이라.",
  ui_story_5089_50891101_89_dialog_content = "도리를 논치 않는 천상조차 인간의 길을 막지 않거늘,\n너는 무엇을 구실로 스스로에게 족쇄를 채운단 말이더냐!",
  ui_story_5089_50891101_90_dialog_content = "일전에 객잔에서 못다 한 말을 내 다시 해야겠다.",
  ui_story_5089_50891101_91_dialog_content = "새의 화려한 깃털을 사랑한다 하여, 잡아다 새장에 가두는 것.",
  ui_story_5089_50891101_92_dialog_content = "범의 반란한 가죽을 사랑한다 하여, 죽여서 껍질을 벗기는 것.",
  ui_story_5089_50891101_93_dialog_content = "그것은 진정한 사랑이 아니다.",
  ui_story_5089_50891101_94_dialog_content = "만물은 천성이 자유로운 법, 만약 정녕 저들을 아낀다면,\n새가 하늘을 날게 두고, 호랑이가 산천에서 울부짖도록 두어야 한다.",
  ui_story_5089_50891101_95_dialog_content = "내 억지로 네게 진상을 찾도록 한 것은 그 멍에가 영원토록 네 몸에 묶이는 것을\n원하지 않았기 때문이다.",
  ui_story_5089_50891101_96_dialog_content = "나는 명령에 의하여서만 네게 지켜지는 군주가 되고 싶지 않고,\n네가 그림자 속의 보이지 않는 검이 되는 것도 원치 않는다.",
  ui_story_5089_50891101_97_dialog_content = "네가 머리를 들고, 가슴을 펴고, 태양 아래 자유롭게 살기를 바란다.",
  ui_story_5089_50891101_98_dialog_content = "네 이름이 나와 어깨를 나란히 하고, 네가 만인에게 칭송받는 장군이 되기를 바란다.",
  ui_story_5089_50891101_99_dialog_content = "그리고 네가 기꺼이 나를 따르기를 바란다.",
  ui_story_5089_50891101_100_dialog_content = "나는──",
  ui_story_5089_50891101_101_dialog_content = "네 진정한 주군이 되고자 한다!",
  ui_story_5089_50891101_102_dialog_content = "군주... 전하.",
  ui_story_5089_50891101_103_dialog_content = "너는 이미 더는 나의 호위가 아니다. 나는 너에게 도움을 청하지 않을 것이야.",
  ui_story_5089_50891101_104_dialog_content = "허나 더는 명령과 은원, 그리고 그 가면 아래 좁은 시야에 얽매이지 않는 네가\n나를 도와줄 뜻이 있거든...",
  ui_story_5089_50891101_105_dialog_content = "일어나라! 기어서라도 좋다──!",
  ui_story_5089_50891101_106_dialog_content = "구!",
  ui_story_5089_50891101_107_dialog_content = "내 곁으로 오도록 해라!",
  ui_story_5089_50891101_108_dialog_content = "...군주 전하께서는 때때로 너무나도 제멋대로라고 제가 말씀드린 적 있었습니까?",
  ui_story_5089_50891101_109_dialog_content = "없었지.",
  ui_story_5089_50891101_110_dialog_content = "그러니 직접 와서 내게 말해다오.",
  ui_story_5089_50891101_111_dialog_content = "......",
  ui_story_5089_50891101_112_dialog_content = "명을 받들겠습니다.",
  ui_story_5089_50891101_113_dialog_content = "<color=#e8d9bb>잠시 후</color>",
  ui_story_5089_50891101_114_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5089_50891101_115_dialog_content = "<color=#e8d9bb>갓 수리한 궁문이 두 번째 붕괴를 맞이했다.</color>",
  ui_story_5089_50891101_116_dialog_content = "중죄인이 탈옥! 어서 쫓아라!",
  ui_story_5089_50891101_117_dialog_content = "사저, 다녀왔... 이게 무슨 일이래요?!",
  ui_story_5089_50891101_118_dialog_content = "별거 아냐. 그냥 간만에 생긴 이웃이 가버렸지 뭐야, 휴.",
  ui_story_5089_50891101_119_dialog_content = "아까 제 옆을 몰아쳤던 그 바람... 그 소저인가요?",
  ui_story_5089_50891101_120_dialog_content = "일단 구 소저한테 먼저 길을 열어달라고 부탁해야지. 이만큼 싸웠으니까 나도 좀 쉬어야겠어.",
  ui_story_5089_50891101_121_dialog_content = "사저도 정말... 아니, 잠깐만요.",
  ui_story_5089_50891101_122_dialog_content = "방금 그 소저, 갈 때 무기도 없지 않았어요?",
  ui_story_5089_50891101_123_dialog_content = "당연하지, 저 사람 실력이면 이 궁궐을 가르는 것도 거뜬할 거야.",
  ui_story_5089_50891101_124_dialog_content = "나라도 저 사람 가둘 때 절대 검을 주진 못했을걸.",
  ui_story_5089_50891101_125_dialog_content = "그럼 저 소저 혼자 경위군 전체를 맨손으로 상대하겠다는 얘기잖아요! 걱정도 안 되세요?",
  ui_story_5089_50891101_126_dialog_content = "뭐가 걱정이야?",
  ui_story_5089_50891101_127_dialog_content = "얼굴이 죽상이었을 땐 일단 넘어가고, 지금 저 상태에선...",
  ui_story_5089_50891101_128_dialog_content = "본인이 멈추지만 않는다면 아무도 저 사람을 막을 수 없어.",
  ui_story_5089_50891101_129_dialog_content = "찾았다! 탈주범이 여기 있다! 우리가 포위했다!",
  ui_story_5089_50891101_130_dialog_content = "탈주범 수중에는 무기가 없다! 어서 잡아라!",
  ui_story_5089_50891101_131_dialog_content = "모르는 모양이구나.",
  ui_story_5089_50891101_132_dialog_content = "검객은 손에 무기가 없어도 모든 것을 검으로 삼을 수 있다.",
  ui_story_5089_50891101_133_dialog_content = "<color=#e8d9bb>그녀가 몸을 돌리자 어둠이 녹아들었다. 그리고──</color>",
  ui_story_5089_50891101_134_dialog_content = "<color=#e8d9bb>꽃잎 날아가고</color>",
  ui_story_5089_50891101_135_dialog_content = "이...이게... 무슨...",
  ui_story_5089_50891101_136_dialog_content = "<color=#e8d9bb>잎사귀를 따네</color>",
  ui_story_5089_50891101_137_dialog_content = "어이! 왜 그래? 아무 일도 없는데 갑자기 쓰러지고, 얼른... 으악!",
  ui_story_5089_50891101_138_dialog_content = "<color=#e8d9bb>대나무를 쓸고</color>",
  ui_story_5089_50891101_139_dialog_content = "비, 비켜! 얼른 비키라고! 으아아악──",
  ui_story_5089_50891101_140_dialog_content = "<color=#e8d9bb>번득이는 깊은 그림자</color>",
  ui_story_5089_50891101_141_dialog_content = "저기 있다! 받아라!",
  ui_story_5089_50891101_142_dialog_content = "뭐야? 그냥 피풍의잖아... 어디... 으윽...",
  ui_story_5089_50891101_143_dialog_content = "<color=#e8d9bb>찰나에 천군을 벨지니</color>",
  ui_story_5089_50891101_144_dialog_content = "이...이자는... 악귀다!",
  ui_story_5089_50891101_145_dialog_content = "아니, 나는 사람이야.",
  ui_story_5089_50891101_146_dialog_content = "요마와는 달라.",
  ui_story_5089_50891101_147_dialog_content = "겨우 그 도리를 납득하게 되었어. 그러니까 이제 비켜줄래?",
  ui_story_5089_50891101_148_dialog_content = "시간이 없거든.",
  ui_story_5089_50891101_149_dialog_content = "...쳐라!",
  ui_story_5089_50891101_150_dialog_content = "휴.",
  ui_story_5089_50891101_151_dialog_content = "<color=#e8d9bb>구는 허리를 굽혀 쓰러진 경위군의 곁에 떨어진 장창을 집어 들었고,\n그것을 부러트려 검의 형태로 만들었다.</color>",
  ui_story_5089_50891101_152_dialog_content = "비켜라.",
  ui_story_5089_50891101_153_dialog_content = "나는──",
  ui_story_5089_50891101_154_dialog_content = "전하 곁으로 돌아갈 것이다!",
  ui_story_5089_50891201_1_dialog_content = "PlayerName 공자, 호련의 위치는 찾았느냐.",
  ui_story_5089_50891201_2_dialog_content = "바로 앞에 있어요!",
  ui_story_5089_50891201_3_dialog_content = "쳇.",
  ui_story_5089_50891201_4_dialog_content = "그 많은 수로도 너흴 못 막다니.",
  ui_story_5089_50891201_5_dialog_content = "역시 인간은 기관수보다 못하다니까.",
  ui_story_5089_50891201_6_dialog_content = "허나 그 기관수 또한 우리가 산산이 조각내지 않았더냐.",
  ui_story_5089_50891201_7_dialog_content = "그리고 우리 쪽은 곧 원군이 올 거니까 지금 항복하는 게 좋을걸.",
  ui_story_5089_50891201_8_dialog_content = "원군? 무서워라.",
  ui_story_5089_50891201_9_dialog_content = "하지만 원군이 아무리 많이 온들, 어차피 인간의 육신인데, 정말 산사태에 맞서 싸울 생각이야?",
  ui_story_5089_50891201_10_dialog_content = "그런 힘 뺄 시간이 있으면 가서 사람들이나 대피시키지 그래?",
  ui_story_5089_50891201_11_dialog_content = "내가 방금 좀 계산해 봤거든. 저 산이 무너지면 이 지역의 농토 전체가 폐허로 변할 거야.",
  ui_story_5089_50891201_12_dialog_content = "어쩐지 나한테 이런 엉뚱한 일을 시킨다 했어.",
  ui_story_5089_50891201_13_dialog_content = "여긴 업나라에서 가장 중요한 곡창지대잖아? 보아하니 올해는 쌀 한 톨도 수확하기 힘들겠어.",
  ui_story_5089_50891201_14_dialog_content = "소문으론 제나라가 업나라의 식량에 손을 대고 있다던데, 잘못하면 기근이 찾아올걸.",
  ui_story_5089_50891201_15_dialog_content = "너도 업나라 사람이잖아! 왜 이런 짓을 하는 거야?!",
  ui_story_5089_50891201_16_dialog_content = "내가 말했을 텐데, 내 기관술을 인정하는 사람이 곧 내 주인이라고.",
  ui_story_5089_50891201_17_dialog_content = "PlayerName 공자, 저자의 말에 휘말릴 필요 없다.",
  ui_story_5089_50891201_18_dialog_content = "저자는 시간을 끌고 있을 뿐이다... 호련, 비채는 어디에 있는 것이냐!",
  ui_story_5089_50891201_19_dialog_content = "하하, 아쉽게 됐네. 좀 늦게 발견했거든.",
  ui_story_5089_50891201_20_dialog_content = "저 멀리 있는 불빛 보여?",
  ui_story_5089_50891201_21_dialog_content = "비채의 공격 준비가 끝났어. 촉음화의 동력원이 전개되면 저 산은 이제 곧 꽃잎처럼── 펑!",
  ui_story_5089_50891201_22_dialog_content = "이렇게 터질 거야.",
  ui_story_5089_50891201_23_dialog_content = "미친 게로구나. 만약 정말 그러하다면, 여기에 있는 너 또한 죽을 게다.",
  ui_story_5089_50891201_24_dialog_content = "난 내 목숨 건사할 능력은 있어.",
  ui_story_5089_50891201_25_dialog_content = "중요한 건 이번이 비채가 부활하고 나서 처음으로 하는 전력 공격이니까,\n나도 당연히 가장 가까운 곳에서 효과를 관측해야지.",
  ui_story_5089_50891201_26_dialog_content = "기뻐해도 좋아. 이런 광경은 아무나 볼 수 있는 게 아니거든.",
  ui_story_5089_50891201_27_dialog_content = "...PlayerName 공자, 일단 저자는 내버려두고 비채를 막아야 한다!",
  ui_story_5089_50891201_28_dialog_content = "이미 늦었어.",
  ui_story_5089_50891201_29_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5089_50891201_30_dialog_content = "<color=#e8d9bb>눈부신 광선이 육중한 산을 뚫고 나가자, 크고 작은 자갈들이 비 오듯 하늘에서 쏟아졌다.</color>",
  ui_story_5089_50891201_31_dialog_content = "경위군! 어서 후... 대왕 전하을 모셔라!\n그리고 주변에 남은 백성이 있는지 수색하고, 구조하여 철수하라!",
  ui_story_5089_50891201_32_dialog_content = "대화 중인 상대를 내팽개치는 건 군주의 예의가 아닐 텐데.",
  ui_story_5089_50891201_33_dialog_content = "<color=#e8d9bb>부서진 자갈에 섞여 든 기관수 한 마리가 단당을 습격했다.</color>",
  ui_story_5089_50891201_34_dialog_content = "조심해요──!",
  ui_story_5089_50891201_35_dialog_content = "이 앞은 지금 위험하니 지나갈 수 없다.",
  ui_story_5089_50891201_36_dialog_content = "어휴, 있는 대로 다 말씀드렸는데 왜 믿지를 않으십니까?",
  ui_story_5089_50891201_37_dialog_content = "소생의 괘상에 따르면, 이 방위는 하늘과 땅이 무너지는 재난이 닥칠 수도 있습니다.",
  ui_story_5089_50891201_38_dialog_content = "어서 이 검을 주인에게 빨리 보내야만 기울어진 대세를 만회할 수 있고,\n무너지는 처마를 받들 수 있단 말입니다.",
  ui_story_5089_50891201_39_dialog_content = "정말 일이 생기더라도 경위군이 해결할 것이니, 지나갈 수 없다.",
  ui_story_5089_50891201_40_dialog_content = "아이고, 그냥 좀 쉽게 쉽게 가시지...",
  ui_story_5089_50891201_41_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5089_50891201_42_dialog_content = "사...산이 어떻게...!",
  ui_story_5089_50891201_43_dialog_content = "거 보십쇼, 소생이 말씀드리지 않았습니까.",
  ui_story_5089_50891201_44_dialog_content = "시간은 사람을 기다리지 않으니, 소생 먼저 가겠습니다!",
  ui_story_5089_50891201_45_dialog_content = "어이, 잠깐...!",
  ui_story_5089_50891201_46_dialog_content = "<color=#e8d9bb>그 순간, 마치 검은 바람이 휘몰아치며 지나간 듯했다.</color>",
  ui_story_5089_50891201_47_dialog_content = "...방금 누가 지나갔나?",
  ui_story_5089_50891201_48_dialog_content = "「꽃이여, 흐드러지게 피어라!」",
  ui_story_5089_50891201_49_dialog_content = "으윽!",
  ui_story_5089_50891201_50_dialog_content = "바다에서보다 꽤 강해졌네.",
  ui_story_5089_50891201_51_dialog_content = "누구나 너처럼 가진 것만 쥐고 제자리에 머무르진 않는 법이다.",
  ui_story_5089_50891201_52_dialog_content = "훗, 말은 잘하네.",
  ui_story_5089_50891201_53_dialog_content = "전부 나와!",
  ui_story_5089_50891201_54_dialog_content = "그럼 어디 내가 「가진 것」들한테서 살아남을 수 있는지 볼까?",
  ui_story_5089_50891201_55_dialog_content = "!",
  ui_story_5089_50891201_56_dialog_content = "(단당 씨는 이미 억지로 버티고 있어. 계속 소모전을 펼치는 건 곤란해.)",
  ui_story_5089_50891201_57_dialog_content = "(하지만 저 산은 아직도 반 정도는 흔들리면서 무너지지 않고 있어... 어떡하지?!)",
  ui_story_5089_50891201_58_dialog_content = "<color=#e8d9bb>스윽──</color>",
  ui_story_5089_50891201_59_dialog_content = "<color=#e8d9bb>깊은 밤의 어둠을 한 줄기 벼락이 갈라냈다.</color>",
  ui_story_5089_50891201_60_dialog_content = "구 씨!",
  ui_story_5089_50891201_61_dialog_content = "너무 늦지 않았느냐!",
  ui_story_5089_50891201_62_dialog_content = "군주 전하, 상황을 헤아려 주십시오, 전 제가 낼 수 있는 가장 빠른 속도로 왔습니다.",
  ui_story_5089_50891201_63_dialog_content = "다만 죄송하다는 말씀은 드리겠습니다.",
  ui_story_5089_50891201_64_dialog_content = "제가 늦었습니다.",
  ui_story_5089_50891201_65_dialog_content = "알면 되었느니라.",
  ui_story_5089_50891201_66_dialog_content = "쳇, 귀찮은 녀석이 왔잖아.",
  ui_story_5089_50891201_67_dialog_content = "근데 너희 셋으로 공방의 기관수를 상대할 수 있을까?!",
  ui_story_5089_50891201_68_dialog_content = "끼기긱──",
  ui_story_5089_50891201_69_dialog_content = "나 혼자면 충분하다.",
  ui_story_5089_50891201_70_dialog_content = "전하와 PlayerName 님께 다가가려거든, 내 검에게 먼저 물어라!",
  ui_story_5089_50891201_71_dialog_content = "(이어지는 전투는 「눈부시다」는 말로밖에 표현할 수 없었다.)",
  ui_story_5089_50891201_72_dialog_content = "(앞뒤로 달려드는 기관수, 그리고 끝없이 떨어지는 낙석 앞에서도\n구 씨는 단 한 발짝도 움직이지 않았다.)",
  ui_story_5089_50891201_73_dialog_content = "(땅에 떨어진 무기, 나뭇가지, 잎사귀, 돌멩이, 심지어 기관수의 잔해까지...)",
  ui_story_5089_50891201_74_dialog_content = "(주변에 보이는 모든 것들이 구 씨의 손에 쥐어지면 마치 칼날이 된 듯\n그 무엇도 적수가 되지 못했다.)",
  ui_story_5089_50891201_75_dialog_content = "「그 검광 해를 쏘는 후예와 같고, 그 자태 천신 타는 비룡과 같도다.」",
  ui_story_5089_50891201_76_dialog_content = "「벽력같은 기세로 검무를 펼치고, 대해의 물결처럼 고요히 거두네.」",
  ui_story_5089_50891201_77_dialog_content = "원하는 검을 찾았느냐.",
  ui_story_5089_50891201_78_dialog_content = "끼긱, 끼기기긱──",
  ui_story_5089_50891201_79_dialog_content = "야, 이거 사기 아냐? 인간의 육체가 이 지경에 이를 리가 없잖아!",
  ui_story_5089_50891201_80_dialog_content = "아직 안 끝났어──!",
  ui_story_5089_50891201_81_dialog_content = "<color=#e8d9bb>그러나 그녀가 기관수를 더 불러들이기 전에, 구가 먼저 그녀의 뒤로 다가왔다.</color>",
  ui_story_5089_50891201_82_dialog_content = "움직이지 마라.",
  ui_story_5089_50891201_83_dialog_content = "!",
  ui_story_5089_50891201_84_dialog_content = "흥, 날 잡는다고 뭐가 달라질 줄 알아?",
  ui_story_5089_50891201_85_dialog_content = "「천명」에서 비채를 회수하고, 내 최강의 기관수는 여전히 전장에서 위세를 떨칠 거야!",
  ui_story_5089_50891201_86_dialog_content = "게다가 네가 아무리 강한들, 이 산이 무너지는 건 이제 막을 수 없어!",
  ui_story_5089_50891201_87_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5089_50891201_88_dialog_content = "<color=#e8d9bb>광산에서 압착된 층암이 알 수 없는 소리를 내고,\n거대한 바위덩어리가 대지를 부술 기세로 추락했다.</color>",
  ui_story_5089_50891201_89_dialog_content = "안 되겠어요! 단당 씨, 구 씨, 우리도 빨리 가요!",
  ui_story_5089_50891201_90_dialog_content = "그렇게 할 수밖에 없겠구나. 백성들은 경위군 쪽에서 이미 대피시켰을 게야.",
  ui_story_5089_50891201_91_dialog_content = "나머지 일은 이후에 다시 이야기하자꾸나.",
  ui_story_5089_50891201_92_dialog_content = "구야, 거기서 뭘 멍하니 있는 것이냐?",
  ui_story_5089_50891201_93_dialog_content = "제가 막을 수 있습니다.",
  ui_story_5089_50891201_94_dialog_content = "뭐라?",
  ui_story_5089_50891201_95_dialog_content = "「경정검」은 산과 바다를 가를 수 있는 검이라고 사부님께서 말씀하셨습니다.",
  ui_story_5089_50891201_96_dialog_content = "근데 구 씨 사부님은 그거 안 가르쳐주셨다면서요!",
  ui_story_5089_50891201_97_dialog_content = "가르쳐 주실 수 없다고 하셨지요. 그때 저는 사부님께서 핑계를 대시는 줄로만 알았습니다.",
  ui_story_5089_50891201_98_dialog_content = "하지만 이제는 조금 알 것 같습니다. 사부님의 말씀이 옳았습니다.",
  ui_story_5089_50891201_99_dialog_content = "「경정검」을 가르칠 수 없는 것은 그것이 실제 검초가 아니기 때문입니다.",
  ui_story_5089_50891201_100_dialog_content = "그것은 검심입니다.",
  ui_story_5089_50891201_101_dialog_content = "그렇다고 쳐도 지금은 그 검도 없잖아요!",
  ui_story_5089_50891201_102_dialog_content = "여러분! 어, 얼른 소생 좀 도와주십시오!",
  ui_story_5089_50891201_103_dialog_content = "아이고, 아이고야, 이 많은 돌을 어떻게 피하란 말입니까!",
  ui_story_5089_50891201_104_dialog_content = "이천간! 이럴 때 또 무슨 소란을 피우려는 것이냐!",
  ui_story_5089_50891201_105_dialog_content = "소생이 점을 치지 않았습니까! 아이고, 안 되겠습니다. 더는 못 갑니다.",
  ui_story_5089_50891201_106_dialog_content = "구 소저! 소생이 소저의 검을 가져왔습니다! 받으세요!",
  ui_story_5089_50891201_107_dialog_content = "그렇게는 안 되지!",
  ui_story_5089_50891201_108_dialog_content = "!",
  ui_story_5089_50891201_109_dialog_content = "<color=#e8d9bb>검이 날아오자, 동시에 여러 마리의 불게가 단당을 향해 달려들었다.</color>",
  ui_story_5089_50891201_110_dialog_content = "<color=#e8d9bb>구도 발을 붙잡혔고, 마지막 불게 한 마리가 검을 낚아챈 후\n낙석이 가장 많이 떨어지는 곳으로 뛰어들었다.</color>",
  ui_story_5089_50891201_111_dialog_content = "<color=#e8d9bb>불게는 순식간에 납작해졌고, 검도 구석으로 떨어지고 말았다.</color>",
  ui_story_5089_50891201_112_dialog_content = "...제가 주워 올게요!",
  ui_story_5089_50891201_113_dialog_content = "PlayerName 공자!\nPlayerName 님!",
  ui_story_5089_50891201_114_dialog_content = "(감응!)",
  ui_story_5089_50891201_115_dialog_content = "(돌의 낙하지점을 제때 판단할 수만 있다면... 뚫고 갈 수 있어!)",
  ui_story_5089_50891201_116_dialog_content = "잡았다!",
  ui_story_5089_50891201_117_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5089_50891201_118_dialog_content = "<color=#e8d9bb>땅이 요란하게 흔들리고, 휘청거리며 버텨오던 광산은 마침내 완전히 무너졌다.</color>",
  ui_story_5089_50891201_119_dialog_content = "(안 돼! 너무 많아서 못 피하겠어──!)",
  ui_story_5089_50891201_120_dialog_content = "<color=#e8d9bb>그 순간, 금빛이 번쩍였다.</color>",
  ui_story_5089_50891201_121_dialog_content = "(...돌이... 다 막혔어?)",
  ui_story_5089_50891201_122_dialog_content = "<color=#e8d9bb>익숙한 금빛 연꽃의 허상이 하늘에 드리워져 있었고, 모든 위험을 연잎 밖으로 막아낸 뒤였다.</color>",
  ui_story_5089_50891201_123_dialog_content = "(주머니 안에 뭔가 뜨거운 게 있는데...? 여기 넣은 건 진예가 준... 나뭇잎...?)",
  ui_story_5089_50891201_124_dialog_content = "<color=#e8d9bb>그것은 되는대로 딴 나뭇잎이 아니었다.</color>",
  ui_story_5089_50891201_125_dialog_content = "<color=#e8d9bb>바로 찬란하게 빛나는 용의 비늘이었다.</color>",
  ui_story_5089_50891201_126_dialog_content = "(...고마워, 진예.)",
  ui_story_5089_50891201_127_dialog_content = "(다시 만나면 간식은 얼마든지 사줄게.)",
  ui_story_5089_50891201_128_dialog_content = "구 씨! 검을 받아요──!",
  ui_story_5089_50891201_129_dialog_content = "감사합니다.",
  ui_story_5089_50891201_130_dialog_content = "<color=#e8d9bb>높은 산이 무너지는 모습은 마치 거인이 넘어지고, 천지가 기울어지는 것만 같았다.</color>",
  ui_story_5089_50891201_131_dialog_content = "<color=#e8d9bb>그러나 주변의 소란이 끊이지 않음에도, 구는 눈을 감고 모든 것을 마음에서 배제했다.</color>",
  ui_story_5089_50891201_132_dialog_content = "(사부님, 저는 이제야 검이란 무엇인지 진정으로 알게 된 것 같습니다.)",
  ui_story_5089_50891201_133_dialog_content = "대도를 이룸에 있어 무수한 하늘의 안배가 있으나, 인간 스스로 열 길은 오직 하나뿐이라.",
  ui_story_5089_50891201_134_dialog_content = "도리를 논치 않는 천상조차 인간의 길을 막지 않거늘,\n너는 무엇을 구실로 스스로에게 족쇄를 채운단 말이더냐!",
  ui_story_5089_50891201_135_dialog_content = "굳이 기한을 정해야 한다면, 음...",
  ui_story_5089_50891201_136_dialog_content = "구 씨가 더는 은혜를 갚거나 복수를 하기 위해 검을 휘두를 필요가 없어질 때까지요.",
  ui_story_5089_50891201_137_dialog_content = "구 소저, 질문 하나 할게.",
  ui_story_5089_50891201_138_dialog_content = "사람과 요마의 가장 큰 차이점이 뭐라고 생각해?",
  ui_story_5089_50891201_139_dialog_content = "(선극 님, 저는 역시 너무 우둔해서, 결국 그 문제의 뜻을 이해하지 못했습니다.)",
  ui_story_5089_50891201_140_dialog_content = "(하지만 다행히도, 제가 망망할 때 저를 이끌어줄 수 있는 사람이 제 곁에 있습니다.)",
  ui_story_5089_50891201_141_dialog_content = "(그리고 이것이 제 답입니다.)",
  ui_story_5089_50891201_142_dialog_content = "(사람과 요마의 가장 큰 차이는, 우리가 본능과 명령에 의해 조종당하는\n도구가 아니라는 것입니다.)",
  ui_story_5089_50891201_143_dialog_content = "(우리는 그것들이 없다 하여 공허함만이 남는 존재가 아닙니다.)",
  ui_story_5089_50891201_144_dialog_content = "(길을 잃어도, 나락으로 떨어져도, 어리석게 스스로를 속박하더라도,\n여전히 수많은 따스한 호의를 만날 수 있습니다.)",
  ui_story_5089_50891201_145_dialog_content = "(그 마음들은 우리를 좁은 그늘에서 벗어나...)",
  ui_story_5089_50891201_146_dialog_content = "(태양 아래 당당하게 살아가도록 할 것입니다!)",
  ui_story_5089_50891201_147_dialog_content = "<color=#e8d9bb>그녀는 눈을 떴고, 거의 보이지 않는 동작으로 검을 휘둘렀다.</color>",
  ui_story_5089_50891201_148_dialog_content = "<color=#e8d9bb>그와 함께, 산과 돌이 갈라지고, 천지가 함께 울부짖었다.</color>",
  ui_story_5089_50891201_149_dialog_content = "<color=#e8d9bb>그것은 지극히 맹렬하면서도, 지극히 경쾌한 검초였다.</color>",
  ui_story_5089_50891201_150_dialog_content = "이 검은 은혜나 복수를 위한 것이 아닙니다.",
  ui_story_5089_50891201_151_dialog_content = "<color=#e8d9bb>그것은 그녀에게 따스함을 주었던 모든 이들을 위한 선물이었다.</color>",
  ui_story_5089_50891201_152_dialog_content = "<color=#e8d9bb>검광은 암석과 산을 휘감았고, 맞설 수 없는 검의는 모든 것을 분쇄했다.</color>",
  ui_story_5089_50891201_153_dialog_content = "대단해...",
  ui_story_5089_50891201_154_dialog_content = "<color=#e8d9bb>다시 고개를 들었을 때는, 요란하게 무너지던 산이 먼지투성이가 되어 있었다.</color>",
  ui_story_5089_50891201_155_dialog_content = "<color=#e8d9bb>「서리 칼날 하늘로 치솟고, 일검에 벽력이 우는도다.」</color>",
  ui_story_5089_50891201_156_dialog_content = "<color=#e8d9bb>먼 곳의 산</color>",
  ui_story_5089_50891201_157_dialog_content = "선극 사저... 방금 그 공격, 다시 오진 않겠죠?",
  ui_story_5089_50891201_158_dialog_content = "아마 그럴걸.",
  ui_story_5089_50891201_159_dialog_content = "나도 저 사람 검이 이렇게 강한 위력을 낼 줄은 몰랐어.",
  ui_story_5089_50891201_160_dialog_content = "이 비채... 이렇게 멀리서도 두 동강이 나다니... 어라?",
  ui_story_5089_50891201_161_dialog_content = "사저... 저기 저거... 설마 촉음화는 아니죠?!",
  ui_story_5089_50891201_162_dialog_content = "어허, 기교사는 매사에 엄격해야 한다고 내가 늘 말했잖아?",
  ui_story_5089_50891201_163_dialog_content = "이젠 이쪽은 초그, 이쪽은 음화라고 해야지.",
  ui_story_5089_50891201_164_dialog_content = "지금 이 상황에서 농담이 나와요?!",
  ui_story_5089_50891201_165_dialog_content = "이건 우리 종문의 귀중한 보물이잖아요! 이젠! 반으로! 똑! 쪼개졌다구요──!",
  ui_story_5089_50891201_166_dialog_content = "정확하게 딱 중간에서 이등분이 됐네.",
  ui_story_5089_50891201_167_dialog_content = "구 소저, 정말 큰 도움이 됐어.",
  ui_story_5089_50891201_168_dialog_content = "대체 그게 무슨 소리인데요?! 이제 종문에다가는 뭐라고 해명하냐구요!",
  ui_story_5089_50891201_169_dialog_content = "이건 내가 알아서 처리할게. 걱정하지 마.",
  ui_story_5089_50891201_170_dialog_content = "자, 얼른 내려가서 다른 동문들한테도 알려.\n이쪽 기관수는 해결됐으니 저쪽 일을 도우라고 말이야.",
  ui_story_5089_50891201_171_dialog_content = "우리 종문의 배신자가 저지른 일도 수습해야 되고 말이야.",
  ui_story_5089_50891201_172_dialog_content = "네...",
  ui_story_5089_50891201_173_dialog_content = "후우...",
  ui_story_5089_50891201_174_dialog_content = "구 씨... 괜찮아요?",
  ui_story_5089_50891201_175_dialog_content = "괜찮습니다, 그저 기운이 조금 빠졌을 뿐입니다...",
  ui_story_5089_50891201_176_dialog_content = "잠깐만요, 온몸이 피투성이잖아요! 이런 몸으로 싸웠던 거예요?!",
  ui_story_5089_50891201_177_dialog_content = "빨리 가서 치료부터 받아요!",
  ui_story_5089_50891201_178_dialog_content = "마음 써 주셔서 감사합니다, PlayerName 님.\n허나 지금 저는 한 가지 더 해야 할 일이 있습니다.",
  ui_story_5089_50891201_179_dialog_content = "이런 꼴로 또 뭘 할 건데요?!",
  ui_story_5089_50891201_180_dialog_content = "단당 씨! 단당 씨도 뭐라고 말 좀 해 봐요!",
  ui_story_5089_50891201_181_dialog_content = "PlayerName 공자, 이번엔 내버려두거라.",
  ui_story_5089_50891201_182_dialog_content = "이제는 모든 것을 끝낼 때가 되었으니 말이야.",
  ui_story_5089_50891201_183_dialog_content = "대체 뭘... 아, 알겠어요.",
  ui_story_5089_50891201_184_dialog_content = "결정한 모양이네요.",
  ui_story_5089_50891201_185_dialog_content = "왔군.",
  ui_story_5089_50891201_186_dialog_content = "네.",
  ui_story_5089_50891201_187_dialog_content = "여봐라, 내 검을 가져와라.",
  ui_story_5089_50891201_188_dialog_content = "대왕 전하! 옥체를 상하셨으니 거동을 삼가셔야 하옵니다!",
  ui_story_5089_50891201_189_dialog_content = "가져오란 말이다.",
  ui_story_5089_50891201_190_dialog_content = "과인은 저 아이에게 빚이 있다.",
  ui_story_5089_50891201_191_dialog_content = "<color=#e8d9bb>구는 품에서 가면을 꺼내 얼굴에 썼다.</color>",
  ui_story_5089_50891201_192_dialog_content = "한 수 배우겠습니다.",
  ui_story_5089_50891202_1_dialog_content = "<color=#e8d9bb>챙──!</color>",
  ui_story_5089_50891202_2_dialog_content = "<color=#e8d9bb>두 사람의 몸이 마지막으로 교차한 후, 가짜 업왕의 검이 공중으로 날아올랐다.</color>",
  ui_story_5089_50891202_3_dialog_content = "콜록... 콜록콜록...",
  ui_story_5089_50891202_4_dialog_content = "대왕 전하! 대왕 전하! 이제 그만 뜻을 거두어 주시옵소서!",
  ui_story_5089_50891202_5_dialog_content = "승부는 이미 정해졌다.",
  ui_story_5089_50891202_6_dialog_content = "내가 졌다.",
  ui_story_5089_50891202_7_dialog_content = "......",
  ui_story_5089_50891202_8_dialog_content = "<color=#e8d9bb>툭.</color>",
  ui_story_5089_50891202_9_dialog_content = "<color=#e8d9bb>그러나 구의 가면도 검기에 반으로 잘려 바닥으로 떨어졌다.</color>",
  ui_story_5089_50891202_10_dialog_content = "피차의 은원은 이것으로 끝입니다.",
  ui_story_5089_50891202_11_dialog_content = "좋다.",
  ui_story_5089_50891202_12_dialog_content = "가거라.",
  ui_story_5089_50891202_13_dialog_content = "<color=#e8d9bb>구는 검을 거둔 후, 멀리 서 있는 단당을 향해 가볍게 절을 올리고는 돌아섰다.</color>",
  ui_story_5089_50891202_14_dialog_content = "<color=#e8d9bb>그리고 다시는 돌아보지 않았다.</color>",
  ui_story_5089_50891300_1_dialog_content = "<color=#e8d9bb>제나라 왕궁</color>",
  ui_story_5089_50891300_2_dialog_content = "아바마마, 아바마마! 제 정혼자가 물건을 보내왔다면서요?!",
  ui_story_5089_50891300_3_dialog_content = "그러하다.",
  ui_story_5089_50891300_4_dialog_content = "볼래요! 보여주세요!",
  ui_story_5089_50891300_5_dialog_content = "바로 이 황금이다.",
  ui_story_5089_50891300_6_dialog_content = "어라? 이건 제가 그 사람한테 준 선물이잖아요?",
  ui_story_5089_50891300_7_dialog_content = "설마 제 선물이 마음에 안 들었대요?\n아, 역시 제 대영웅은 이런 속된 재물은 안 좋아할 줄 알았다니까요.",
  ui_story_5089_50891300_8_dialog_content = "아무래도 선물 준비에 더 신경 써야겠어요. 지금 당장 고르러 갈래요!",
  ui_story_5089_50891300_9_dialog_content = "어휴...",
  ui_story_5089_50891300_10_dialog_content = "그 젊은이는 이 금으로 저희 사람들이 업에서 사들인 식량과 맞바꾸었습니다.\n그 의도가 실로 분명하군요.",
  ui_story_5089_50891300_11_dialog_content = "전하, 준비는 어떻게 되어가고 있는지요.",
  ui_story_5089_50891300_12_dialog_content = "PlayerName 그자는 과인이 친히 약조한 제나라의 벗이다.\n호진성을 구해 준 은정을 아직 못 갚지 않았는가.",
  ui_story_5089_50891300_13_dialog_content = "그자가 개입한 이상, 과인은 응당 그자의 체면을 세워주어야겠지.",
  ui_story_5089_50891300_14_dialog_content = "다만 다음에 업이 재차 도발하거든, 그때는 과인도 봐주지 않을 것이다.",
  ui_story_5089_50891300_15_dialog_content = "지당한 말씀입니다.",
  ui_story_5089_50891300_16_dialog_content = "<color=#e8d9bb>휘이잉──</color>",
  ui_story_5089_50891300_17_dialog_content = "<color=#e8d9bb>사람들이 드나드는 부두에서, 또 한 척의 큰 배가 돛을 올리고 출항했다.</color>",
  ui_story_5089_50891300_18_dialog_content = "결국 그 뒤로 구 씨는 안 돌아왔어요?",
  ui_story_5089_50891300_19_dialog_content = "내 손으로 자유롭게 해 준 이상, 어떤 선택을 하든 존중해야 마땅하지.",
  ui_story_5089_50891300_20_dialog_content = "설령 다시는 돌아오지 않더라도, 한때 다행히도 그러한 벗이 있었음을 내 잊지 않을 것이야.",
  ui_story_5089_50891300_21_dialog_content = "PlayerName 공자는 앞으로 어찌할 생각이냐.",
  ui_story_5089_50891300_22_dialog_content = "네? 우리 지금 제나라로 가고 있잖아요.",
  ui_story_5089_50891300_23_dialog_content = "그리고 단당 씨가 그랬잖아요. 「천명」은 우리 모두의 적이니까,\n제나라와 업나라가 잠시 싸움을 멈추도록 설득해야 한다고요.",
  ui_story_5089_50891300_24_dialog_content = "마침 저도 가서 남은 금을 돌려줘야 하고 말이죠.\n아참, 후풍경... 아니, 업나라 국왕님한테 돈 대신 갚아준 거 고맙다고 인사도 못 했네요.",
  ui_story_5089_50891300_25_dialog_content = "근데... 그 사람 계속 왕으로 지내게 둬도 괜찮은 거예요?",
  ui_story_5089_50891300_26_dialog_content = "이 또한 어쩔 수 없는 일이다.",
  ui_story_5089_50891300_27_dialog_content = "숙부께서는 정신이 혼미하시고, 형님은 아직 일국을 주관할 준비가 되지 않았다.\n작금의 업나라는 약간의 동요라도 감당할 수 없는 형편이다.",
  ui_story_5089_50891300_28_dialog_content = "후풍경은 비록 다소 자만하는 자이나, 진심으로 업나라를 위해 도모하고 있다.",
  ui_story_5089_50891300_29_dialog_content = "게다가 지금은 선기경과 백공원을 비롯한 조정 세력의 견제도 있으니,\n그자도 당분간은 무슨 풍파를 일으키진 못할 게야.",
  ui_story_5089_50891300_30_dialog_content = "내가 그대에게 묻고자 하는 것은 이 일이 아니라, 앞으로의 계획이다.",
  ui_story_5089_50891300_31_dialog_content = "그렇네요. 그럼 호진성도 갔고, 경양성도 갔으니까, 용주의 다른 곳들도 가 보고 싶어요.",
  ui_story_5089_50891300_32_dialog_content = "근데 아스트라를 떠난 지도 오래됐으니까, 아무래도 한번 돌아가는 게 좋겠죠?\n아니면 바이스랑 카렌이 걱정할 테니까요.",
  ui_story_5089_50891300_33_dialog_content = "단당 씨는 어떻게 생각하세요?",
  ui_story_5089_50891300_34_dialog_content = "공자가 내게 농을 하는구나.",
  ui_story_5089_50891300_35_dialog_content = "그대는 새장에 갇힌 새도 아니고, 사로잡힌 짐승도 아니거늘,\n내 어찌 그대의 미래를 안배할 수 있겠느냐.",
  ui_story_5089_50891300_36_dialog_content = "이것도 아니고, 저것도 아니면, 단당 씨 눈에 전 뭔데요?",
  ui_story_5089_50891300_37_dialog_content = "글쎄다...",
  ui_story_5089_50891300_38_dialog_content = "<color=#e8d9bb>아침 햇살 아래, 그녀는 가볍게 웃으며 눈을 치켜들었고,\n정중한 두 눈에는 반짝이는 빛이 가득했다.</color>",
  ui_story_5089_50891300_39_dialog_content = "그대는 대붕조다.",
  ui_story_5089_50891300_40_dialog_content = "끝내는 가장 높은 하늘까지 날개짓을 할 것이야.",
  ui_story_5089_50891300_41_dialog_content = "그거 평가가 너무 후한 거 아니에요?",
  ui_story_5089_50891300_42_dialog_content = "그럴 리가 없지 않느냐.",
  ui_story_5089_50891300_43_dialog_content = "어이! 저기 바다 좀 봐! 사, 사람이 배를 쫓아오고 있어!",
  ui_story_5089_50891300_44_dialog_content = "자네 잠이 덜 깼구만. 바다에 어떻게... 으헉! 진짜네! 뭐가 어떻게 된 거야?!",
  ui_story_5089_50891300_45_dialog_content = "저기 선원들이 뭐라고 떠드는데... 우와!",
  ui_story_5089_50891300_46_dialog_content = "저거 구 씨 아니에요?!",
  ui_story_5089_50891300_47_dialog_content = "<color=#e8d9bb>배는 이미 해안가를 한참 떠났지만, 한 줄기 그림자가 수면 위를 밟으며 빠르게 달려왔다.</color>",
  ui_story_5089_50891300_48_dialog_content = "<color=#e8d9bb>잠시 후, 그녀는 갑판에 다가와 무수한 비명을 지나 훌쩍 뛰어올랐다.</color>",
  ui_story_5089_50891300_49_dialog_content = "<color=#e8d9bb>시원한 물기와 함께, 구가 두 사람의 앞에 착지했다.</color>",
  ui_story_5089_50891300_50_dialog_content = "군주 전하께서 타국 출행에 호위 하나 데려가지 않으시는 것은 너무 부주의한 일이 아닐는지요.",
  ui_story_5089_50891300_51_dialog_content = "결정한 것이냐.",
  ui_story_5089_50891300_52_dialog_content = "만약 또 나를 따라오다 일전과 같은 일이 또 벌어지거든,\n그때는 내 이리 너그럽지 않을 것이야.",
  ui_story_5089_50891300_53_dialog_content = "결정했습니다.",
  ui_story_5089_50891300_54_dialog_content = "이번에는 결코 사명을 욕되지 않게 하겠습니다.",
  ui_story_5089_50891300_55_dialog_content = "하면 가자꾸나.",
  ui_story_5089_50891300_56_dialog_content = "지금 「천명」은 온 조나라를 위협하고 있다.\n우리는 제나라에 간 후, 다른 제후국에도 가서 상황을 알아보아야 한다.",
  ui_story_5089_50891300_57_dialog_content = "정세가 불안한데 전하께서 직접 위험을 감수하실 필요가 있습니까?\n다른 제후국은 명을 내려 사람을 보내도 되지 않겠습니까.",
  ui_story_5089_50891300_58_dialog_content = "천하를 누비고 종횡으로 유세하는 것은 많은 이들이 원해도 얻을 수 없는 기회이니라.",
  ui_story_5089_50891300_59_dialog_content = "내 어릴 적부터 이 뜻을 품었거늘, 어찌 숨은 위기 때문에 이를 포기할 수 있겠느냐.",
  ui_story_5089_50891300_60_dialog_content = "게다가 곤과 붕은 자유로우니, 천지 어디라도 못 갈 곳이 없다.",
  ui_story_5089_50891300_61_dialog_content = "만약 내가 천하를 누빌 담력조차 없다면, 언젠가 붕새가 곁에 함께하길 바랄 수 있겠느냐?",
  ui_story_5089_50891300_62_dialog_content = "앞으로는 아직 기나긴 여정이 남아 있을 것이야.",
  ui_story_5089_50891300_63_dialog_content = "<color=#e8d9bb>어딘가의 다관</color>",
  ui_story_5089_50891300_64_dialog_content = "...이렇게 하여, 작화군주와 이방인은 다시 각자의 여정을 떠났습니다.",
  ui_story_5089_50891300_65_dialog_content = "이 무대에서 보여지는 변화무상함도 조금은 평온해졌다 할 수 있겠지요.",
  ui_story_5089_50891300_66_dialog_content = "소생은 이참에 게으름이나 좀 피우고, 이 기이한 일화도 들려드리면서,\n겸사겸사 동전 몇 닢을 받아 새들도 먹일 생각입니다.",
  ui_story_5089_50891300_67_dialog_content = "예? 이게 소생이 지어낸 소설 아니냐고요? 아이고, 그리 말씀하시면 정말 억울합니다.",
  ui_story_5089_50891300_68_dialog_content = "방금 들려드린 일은 구구절절 사실입니다. 증거가 되는 시조도 있단 말입니다.",
  ui_story_5089_50891300_69_dialog_content = "「방주는 바다 갈라 물결 빛을 그리고, 찬란한 해당화는 한없이 피어나니.」",
  ui_story_5089_50891300_70_dialog_content = "「춘삭 밤 물고기와 용이 춤추고, 만균의 풍뢰에 대해도 고요하네.」",
  ui_story_5089_50891300_71_dialog_content = "「서리 칼날 천둥처럼 간담이 서늘하여, 요사한 나찰도 연기로 돌아가매.」",
  ui_story_5089_50891300_72_dialog_content = "「갇힌 새 우리 깨어 구천을 흔들고, 이로써 소요하며 넓은 천지 누비리.」",
  ui_story_5089_50891300_73_dialog_content = "이 「작화행」이라는 이야기는 이렇게 끝이 났습니다.",
  ui_story_5089_50891300_74_dialog_content = "물론 주인공의 여정이 이렇게 끝나는 것은 아닙니다.\n만약 다음 이야기에도 관심이 있으시다면──",
  ui_story_5089_50891300_75_dialog_content = "<color=#e8d9bb>탁!</color>",
  ui_story_5089_50891300_76_dialog_content = "<color=#e8d9bb>격탁 소리가 울리자, 끝까지 넘겨진 책들이 서서히 거두어졌고, 촛불이 꺼지며 막이 내려왔다.</color>",
  ui_story_5089_50891300_77_dialog_content = "다음 시간에 뵙겠습니다.",
  ui_story_5089_50891400_1_dialog_content = "이제 결심하셨습니까.",
  ui_story_5089_50891400_2_dialog_content = "다음 발걸음을 내디딘다는 것은, 이제 현재의 모든 이들과 작별한다는 것을 의미합니다.",
  ui_story_5089_50891400_3_dialog_content = "당신이 어렵게 이룬 유대 관계는 모두 사라질 것입니다.",
  ui_story_5089_50891400_4_dialog_content = "하지만 그럼에도 당신은 그녀를 위해 「먼 곳」으로 향하려 하는 것입니까.",
  ui_story_5089_50891400_5_option_content = "맞아.",
  ui_story_5089_50891400_6_option_content = "응, 결정했어.",
  ui_story_5089_50891400_7_dialog_content = "......",
  ui_story_5089_50891400_8_dialog_content = "용주에 다녀온 뒤로, 당신은 더욱 단호해졌군요.",
  ui_story_5089_50891400_9_dialog_content = "자, 그렇다면 가서 작별 인사를 하십시오.",
  ui_story_5089_50891400_10_dialog_content = "마지막 순간, 모든 친구들에게 말입니다.",
  ui_story_5089_50891400_11_dialog_content = "그럼 마지막으로 아스트라를 한 바퀴 날아볼까?",
  ui_story_5089_50891400_12_dialog_content = "처음 시작했을 때처럼, 자유롭게 여행해 보는 거야!",
  ui_story_5089_50891400_13_dialog_content = "고작 작별 인사를 하겠다고 그 먼 길을 온 거냐?",
  ui_story_5089_50891400_14_dialog_content = "하여튼 못 말린다니까. 또 돌아올 거지?",
  ui_story_5089_50891400_15_option_content = "나도 잘 모르겠어.",
  ui_story_5089_50891400_16_option_content = "응...",
  ui_story_5089_50891400_17_dialog_content = "휴, 이리 와라.",
  ui_story_5089_50891400_18_dialog_content = "긴 말 필요 없어. 사나이끼린 이렇게 한 번 안아주면 그걸로 된 거다.",
  ui_story_5089_50891400_19_dialog_content = "알아, 너도 나름의 이유가 있겠지.",
  ui_story_5089_50891400_20_dialog_content = "...고맙다. 그동안 참 많이 도와줘서.",
  ui_story_5089_50891400_21_dialog_content = "언젠가 돌아오게 되면 와서 얼굴 좀 비추고.",
  ui_story_5089_50891400_22_dialog_content = "힘들 땐 기억해. 여기 네 자리도 있다는 거.",
  ui_story_5089_50891400_23_dialog_content = "응, 꼭 기억할게.",
  ui_story_5089_50891400_24_dialog_content = "젠장, 너 이 자식, 나까지 슬프게 만들고 말이야.",
  ui_story_5089_50891400_25_dialog_content = "자, 이제 가서 이브랑 다른 녀석들한테도 인사하라고.",
  ui_story_5089_50891400_26_dialog_content = "잘 있어, 사메야마.",
  ui_story_5089_50891400_27_dialog_content = "...또 보자, PlayerName.",
  ui_story_5089_50891400_28_dialog_content = "왜 갑자기... 오랫동안 떠나는 건데?",
  ui_story_5089_50891400_29_dialog_content = "아... 완전히 정해진 건 아냐. 근데 언제 돌아올 지도 아직은 잘 모르겠거든...",
  ui_story_5089_50891400_30_dialog_content = "우, 울지 마! 사메야마가 보면 나 끝장날 거야!",
  ui_story_5089_50891400_31_dialog_content = "그치만...",
  ui_story_5089_50891400_32_dialog_content = "그래도 언젠간 다시 만날 거야!",
  ui_story_5089_50891400_33_dialog_content = "언젠가 내가 다시 「돌아올」 때가 되면...",
  ui_story_5089_50891400_34_dialog_content = "그땐 내가 아스트라에선 볼 수 없는 것들을 잔뜩 가르쳐 줄게.",
  ui_story_5089_50891400_35_dialog_content = "약속이야.",
  ui_story_5089_50891400_36_dialog_content = "응, 약속할게!",
  ui_story_5089_50891400_37_dialog_content = "손가락 걸까?",
  ui_story_5089_50891400_38_dialog_content = "응!",
  ui_story_5089_50891400_39_dialog_content = "참, 나랑 같이 다른 사람들한테도 인사하러 가자.",
  ui_story_5089_50891400_40_dialog_content = "다들 계속 너 보고 싶어 했거든.",
  ui_story_5089_50891400_41_dialog_content = "네가 소개해 준 그 「아가씨」 가 여기서 어떻게 지내는지 못 봤지?",
  ui_story_5089_50891400_42_dialog_content = "아, 그리고 「불사조 아탈」 언니도...",
  ui_story_5089_50891400_43_dialog_content = "...이브.",
  ui_story_5089_50891400_44_dialog_content = "미안, 울지 않겠다고 약속해놓고...",
  ui_story_5089_50891400_45_dialog_content = "그치만... 너랑 겪었던 일들이 갑자기 잔뜩 생각나 버려서...",
  ui_story_5089_50891400_46_dialog_content = "그러게, 참 오래됐잖아.",
  ui_story_5089_50891400_47_dialog_content = "동료도 어느새 잔뜩 생겼고, 다들 많이 변했고 말이야.",
  ui_story_5089_50891400_48_dialog_content = "역시 난 여길 참 좋아하나 봐.",
  ui_story_5089_50891400_49_dialog_content = "꼭 용주의 훠궈 같거든.",
  ui_story_5089_50891400_50_dialog_content = "그러니까 난 이브가 괜찮을 거라고 믿어.",
  ui_story_5089_50891400_51_dialog_content = "다들 여전히 저렇게 이브 곁에 있잖아.",
  ui_story_5089_50891400_52_dialog_content = "아, 알겠어...",
  ui_story_5089_50891400_53_dialog_content = "그럼 돌아올 때까지 기다릴게. 모두와 같이 웃으면서...",
  ui_story_5089_50891400_54_dialog_content = "응, 그럼 같이 인사하러 가자.",
  ui_story_5089_50891400_55_dialog_content = "사정은 이미 들었습니다.",
  ui_story_5089_50891400_56_dialog_content = "바이스와 관계된 일인 이상, 저도 당신들을 막진 않을 겁니다.",
  ui_story_5089_50891400_57_dialog_content = "바이스의 휴가는 이미 승인해 두었습니다. 또 필요한 게 있다면 얼마든지 말하세요.",
  ui_story_5089_50891400_58_dialog_content = "괜찮아요, 그거면 충분해요. 히이로 씨랑 라인하르트 씨한테는 정말 고마워요.",
  ui_story_5089_50891400_59_dialog_content = "하지만 이번 여정은 「미지」를 향한 여행이에요.",
  ui_story_5089_50891400_60_dialog_content = "사람 몇 명 더 데려간다고 해결될 문제는 아닐 거예요.",
  ui_story_5089_50891400_61_dialog_content = "그렇다곤 해도, 당신에게 도움을 줄 수 있다면 좋을 겁니다.",
  ui_story_5089_50891400_62_dialog_content = "당신이 없다면 다들 쓸쓸해하겠죠.",
  ui_story_5089_50891400_63_dialog_content = "특히 집에만 박혀 있는 바튼은 더 외로울 겁니다.",
  ui_story_5089_50891400_64_dialog_content = "그로누보고 바튼 씨랑 게임 좀 많이 하라고 하는 건 어떨까요?\n싸움이 없을 때 집에만 있으면 바튼 씨한테 안 좋을 거예요.",
  ui_story_5089_50891400_65_dialog_content = "훗, 농담이었습니다.",
  ui_story_5089_50891400_66_dialog_content = "그 사람은 자기 옛 상관한테 붙잡혀서 할 일이 넘치니 괜찮습니다.",
  ui_story_5089_50891400_67_dialog_content = "히이로 씨가 저한테 농담을 하실 줄은 생각도 못 했네요...",
  ui_story_5089_50891400_68_dialog_content = "어쩌면 이런 게 바로 당신이 우리에게 준 변화일지도 모르죠.",
  ui_story_5089_50891400_69_dialog_content = "대원수님조차 당신의 영향을 받았으니, 저는 말할 것도 없을 겁니다.",
  ui_story_5089_50891400_70_dialog_content = "......",
  ui_story_5089_50891400_71_dialog_content = "부디 몸조심하세요.",
  ui_story_5089_50891400_72_dialog_content = "네!",
  ui_story_5089_50891400_73_dialog_content = "여기 있군!",
  ui_story_5089_50891400_74_dialog_content = "PlayerName! 나도 왔어.",
  ui_story_5089_50891400_75_dialog_content = "작별 인사 하러.",
  ui_story_5089_50891400_76_dialog_content = "그 콜로서스는 왜 하필 이럴 땐 그렇게 빨리도 가는 건지 원.",
  ui_story_5089_50891400_77_dialog_content = "어이! PlayerName!",
  ui_story_5089_50891400_78_dialog_content = "하루 세끼 제때 잘 챙겨 먹고, 다닐 때도 잊지 말고 몸조심해라!",
  ui_story_5089_50891400_79_dialog_content = "바이스도 잘 데려오고.",
  ui_story_5089_50891400_80_dialog_content = "응! 바이스랑 돌아올 테니까 기다리고 있어!",
  ui_story_5089_50891400_81_dialog_content = "꼭 안전하게 같이 돌아올게!",
  ui_story_5089_50891400_82_dialog_content = "저 녀석... 바이스는 우리 일루미나인인데, 툭하면 데려간단 말이지...",
  ui_story_5089_50891400_83_dialog_content = "작별인사도 안 하실 건가요?",
  ui_story_5089_50891400_84_dialog_content = "됐어.",
  ui_story_5089_50891400_85_dialog_content = "녀석은 자유로운 날개가 있다. 내가 굳이 더 부담을 줄 필요는 없겠지.",
  ui_story_5089_50891400_86_dialog_content = "지금부터는 「PlayerName」 자신의 이야기이자, 자신의 여정이다.",
  ui_story_5089_50891400_87_dialog_content = "친구로서 내가 할 수 있는 건 그저 묵묵히 저 날개를 축복하는 것뿐이겠지.",
  ui_story_5089_50891400_88_dialog_content = "...이제 가자고. 우리도 아직 내려야 할 결단이 있으니 말이야.",
  ui_story_5089_50891400_89_dialog_content = "작별 인사인 거구나...",
  ui_story_5089_50891400_90_dialog_content = "......",
  ui_story_5089_50891400_91_dialog_content = "지금은 빅토리아 님도 파로마도, 파솔로도 없는데...",
  ui_story_5089_50891400_92_dialog_content = "그래도 넌 있잖아.",
  ui_story_5089_50891400_93_dialog_content = "그럼 적어도 너랑은 직접 만나서 인사한 거니까.",
  ui_story_5089_50891400_94_dialog_content = "다행이야.",
  ui_story_5089_50891400_95_dialog_content = "말도 못 하고 가면 왠지 허전할 것 같거든.",
  ui_story_5089_50891400_96_dialog_content = "?!",
  ui_story_5089_50891400_97_dialog_content = "파로마를 못 보고 가는 건 아쉽긴 하지만...",
  ui_story_5089_50891400_98_dialog_content = "그래도 빅토리아 씨는 엄청난 힘이 있으니까, 어쩌면 대신 전해줄 수도 있지 않을까? 하하...",
  ui_story_5089_50891400_99_dialog_content = "정 안 되면...",
  ui_story_5089_50891400_100_dialog_content = "은둔 수행의 대가님── 제 말 들리시죠──?",
  ui_story_5089_50891400_101_dialog_content = "빅토리아 씨랑 다른 사람들한테 제 말 좀 전해 주세요──",
  ui_story_5089_50891400_102_dialog_content = "...누구한테 말하는 거야?",
  ui_story_5089_50891400_103_dialog_content = "하하하, 누군가는 알 거야.",
  ui_story_5089_50891400_104_dialog_content = "......",
  ui_story_5089_50891400_105_dialog_content = "저기...",
  ui_story_5089_50891400_106_dialog_content = "그럼... 무사히 돌아오길 바랄게.",
  ui_story_5089_50891400_107_dialog_content = "물론 그래야지.",
  ui_story_5089_50891400_108_dialog_content = "그럼 잘 있어.",
  ui_story_5089_50891400_109_dialog_content = "응, 또 봐.",
  ui_story_5089_50891400_110_dialog_content = "...물건은 이것들이 전부예요.",
  ui_story_5089_50891400_111_dialog_content = "이건 움브라톤 총상회, 그리고... 「테르테르」가 당신에게 줄 수 있는 지원이에요.",
  ui_story_5089_50891400_112_dialog_content = "그냥 한번 들른 건데 물자를 이렇게 잔뜩 공짜로 받을 줄은 몰랐어...",
  ui_story_5089_50891400_113_dialog_content = "좀 미안한걸.",
  ui_story_5089_50891400_114_dialog_content = "자네는 언제나 움브라톤의 친구이자, 우리의 친구일 것이다.",
  ui_story_5089_50891400_115_dialog_content = "마음 편히 받아라.",
  ui_story_5089_50891400_116_dialog_content = "으앗! 깜짝 놀랐잖아요!",
  ui_story_5089_50891400_117_dialog_content = "하하하, 앞으로 자네가 가려는 곳에는 자네를 지켜줄 그림자가 없을 거다.",
  ui_story_5089_50891400_118_dialog_content = "늘 조심해라.",
  ui_story_5089_50891400_119_dialog_content = "네.",
  ui_story_5089_50891400_120_dialog_content = "...베델, 나머지는 네게 맡기마.",
  ui_story_5089_50891400_121_dialog_content = "......",
  ui_story_5089_50891400_122_dialog_content = "루크 단장, 스모키 양, 제네비브 양, 그리고 나로세르 장로님이 당신을 기다리고 있어요.",
  ui_story_5089_50891400_123_dialog_content = "역시 당신은 아스트라의 인기인이라니까요.\n모두가 당신과 작별 인사를 하고 싶어 한다니 말이에요.",
  ui_story_5089_50891400_124_dialog_content = "응...",
  ui_story_5089_50891400_125_dialog_content = "그래서 나도 꼭 모두와 인사를 하고 싶어.",
  ui_story_5089_50891400_126_dialog_content = "그리고 너, 베델도.",
  ui_story_5089_50891400_127_dialog_content = "......!",
  ui_story_5089_50891400_128_dialog_content = "...정말 그렇게 오래 떠나 있을 건가요?",
  ui_story_5089_50891400_129_dialog_content = "나도 모르겠어. 어쩌면 돌아오지 못할 수도 있겠지.",
  ui_story_5089_50891400_130_dialog_content = "하지만 난 모두를 잊지 않을 거야.",
  ui_story_5089_50891400_131_dialog_content = "돌아올 수만 있다면, 최선을 다할게.",
  ui_story_5089_50891400_132_dialog_content = "PlayerName...",
  ui_story_5089_50891400_133_dialog_content = "꼭 몸조심하세요.",
  ui_story_5089_50891400_134_dialog_content = "도중에 재미있는 소설이 보이면 갖다줄게.",
  ui_story_5089_50891400_135_dialog_content = "그땐 카페에서 다 같이 읽자!",
  ui_story_5089_50891400_136_dialog_content = "그럼...",
  ui_story_5089_50891400_137_dialog_content = "잘 있어, 베델.",
  ui_story_5089_50891400_138_dialog_content = "찾았어, 저기 있네.",
  ui_story_5089_50891400_139_dialog_content = "PlayerName 씨~",
  ui_story_5089_50891400_140_dialog_content = "잘 다녀와~",
  ui_story_5089_50891400_141_dialog_content = "아...",
  ui_story_5089_50891400_142_dialog_content = "잘 있어──",
  ui_story_5089_50891400_143_dialog_content = "부디 너희의 앞길에 노래와 희망이 함께하길 바랄게...",
  ui_story_5089_50891400_144_dialog_content = "...다시 만나자.",
  ui_story_5089_50891400_145_dialog_content = "뭐? 같이 가고 싶다고?",
  ui_story_5089_50891400_146_dialog_content = "그, 그렇게 막 엄청 같이 가고 싶은 건 아니거든?",
  ui_story_5089_50891400_147_dialog_content = "그치만 「환상의 땅」인지 뭔지를 탐험한다니... 왠지 재미있을 것 같단 말이야.",
  ui_story_5089_50891400_148_dialog_content = "심지어 안토니 씨조차도 끌렸다고 했는걸.\n난 안토니 씨보다는 한가하니까, 관심이 생기는 것도 당연한 거 아냐?",
  ui_story_5089_50891400_149_dialog_content = "후후, 마지막 순간에서조차 진심을 전하지 않으면 나중에 후회하게 될걸.",
  ui_story_5089_50891400_150_dialog_content = "......",
  ui_story_5089_50891400_151_dialog_content = "아스트라의 샛별인 그대를 이렇게 여행길에 오르게 하면 마음이 편치 못한 것도 당연한 일이다.",
  ui_story_5089_50891400_152_dialog_content = "헤에? 아니면 이건 어때?",
  ui_story_5089_50891400_153_dialog_content = "조종사 씨가 명령만 하면 내가 부하 다섯을 더 데려와 줄게.",
  ui_story_5089_50891400_154_dialog_content = "어떤 속성이든 다 있고, 어떤 길도 다 갈 수 있을 거라구...",
  ui_story_5089_50891400_155_dialog_content = "허나 내게는 그대의 미래가 보인다.",
  ui_story_5089_50891400_156_dialog_content = "그대는 그곳에서도 무한한 빛을 가질 수 있을 것이다.",
  ui_story_5089_50891400_157_dialog_content = "어쩌면 그곳이야말로 그대가 진정으로 싸워야 할 의미를 지닌 곳일지도 모른다.",
  ui_story_5089_50891400_158_dialog_content = "그 무엇보다 현실적이면서도 환상으로 충만한 그곳에서,\n그대는 더 나은 모든 것을 위해 싸우게 될 것이다.",
  ui_story_5089_50891400_159_dialog_content = "그것은 그대 자신의 길이다.",
  ui_story_5089_50891400_160_dialog_content = "비록 우리는 많은 염려를 품고 있으나, 오직 축복만을 그대에게 전할 것이다.",
  ui_story_5089_50891400_161_dialog_content = "고마워요, 그런 축복을 받는 것만으로도 전 이미 안심이 되는걸요.",
  ui_story_5089_50891400_162_dialog_content = "하아? 진짜로 우리가 모험하고 레벨업해서 팬텀을 베어버리는 후속 전개의 가능성은 없는 거야?",
  ui_story_5089_50891400_163_dialog_content = "지루해 죽을 것 같단 말이야.",
  ui_story_5089_50891400_164_dialog_content = "근데 프레야는 여기서 즐겁게 지내고 있었잖아?",
  ui_story_5089_50891400_165_dialog_content = "뭐, 그렇긴 해...",
  ui_story_5089_50891400_166_dialog_content = "예전의 고향도 가 봤고, 가문의 「보물」을 확인했고, 새 옷도 받았으니까...",
  ui_story_5089_50891400_167_dialog_content = "깨어나고 보니까 갑자기 무슨 편애를 받는 느낌이었다구.",
  ui_story_5089_50891400_168_dialog_content = "하지만 이 프레야 님은 고작 이 정도로 만족하진 않거든?",
  ui_story_5089_50891400_169_dialog_content = "기껏 와서 새로운 얘길 잔뜩 늘어놓고는, 정작 우리한텐 못 가게 하고 말이야.",
  ui_story_5089_50891400_170_dialog_content = "주먹이 근질근질해서 참을 수가 없잖아...",
  ui_story_5089_50891400_171_dialog_content = "아니면 조종사 씨, 내가 한 손으로 상대해 줄 테니까 싸워볼래?",
  ui_story_5089_50891400_172_dialog_content = "안 그래도 내 꿈은──",
  ui_story_5089_50891400_173_dialog_content = "잘 있어, 프레야.",
  ui_story_5089_50891400_174_dialog_content = "......",
  ui_story_5089_50891400_175_dialog_content = "네가 그렇게 즐겁게, 「진짜」로 웃는 걸 보고 나니까...",
  ui_story_5089_50891400_176_dialog_content = "나도 이제 안심했어.",
  ui_story_5089_50891400_177_dialog_content = "...다른 사람들한테도 잘 인사하고 가.",
  ui_story_5089_50891400_178_dialog_content = "그럴게.",
  ui_story_5089_50891400_179_dialog_content = "베들레헴 씨, 잘 있어요.",
  ui_story_5089_50891400_180_dialog_content = "잘 가거라.",
  ui_story_5089_50891400_181_dialog_content = "그대가 만나려는 이들은 궁전 밖에 있다.",
  ui_story_5089_50891400_182_dialog_content = "그들에게 가 보거라, PlayerName.",
  ui_story_5089_50891400_183_dialog_content = "잘 있어, 자리야.",
  ui_story_5089_50891400_184_dialog_content = "<size=28>...나도 가고 싶어.</size>",
  ui_story_5089_50891400_185_dialog_content = "응?",
  ui_story_5089_50891400_186_dialog_content = "아니, 아무것도 아냐.",
  ui_story_5089_50891400_187_dialog_content = "또 만나...",
  ui_story_5089_50891400_188_dialog_content = "아이참... 자, 이리 와. 이 노인네가 너한테 삶의 철학을 전수해 줄 테니까.",
  ui_story_5089_50891400_189_dialog_content = "야!",
  ui_story_5089_50891400_190_dialog_content = "흔히 오는 기회가 아니라구.\n네가 소녀 노릇할 수 있는 것도 여왕이나 산의 정령 같은 노인네들 앞뿐이잖아?",
  ui_story_5089_50891400_191_dialog_content = "프─레─야──!",
  ui_story_5089_50891400_192_dialog_content = "...그럼, 여기가 마지막 장소구나.",
  ui_story_5089_50891400_193_dialog_content = "PlayerName 씨... 꼭 돌아오셔야 합니다.",
  ui_story_5089_50891400_194_dialog_content = "응, 잘 있어, 레인. 다른 사람들한테도 인사 전해 줘.",
  ui_story_5089_50891400_195_dialog_content = "어머, 이제 무대를 주인공에게 남겨줄 시간이네.",
  ui_story_5089_50891400_196_dialog_content = "다들 가자.",
  ui_story_5089_50891400_197_dialog_content = "......",
  ui_story_5089_50891400_198_dialog_content = "......",
  ui_story_5089_50891400_199_dialog_content = "왜 그래? 작별 인사하러 온 거 아니었어?",
  ui_story_5089_50891400_200_dialog_content = "왠지 모르게... 말을 꺼내기가 조금 힘드네...",
  ui_story_5089_50891400_201_dialog_content = "그럼 마야가 말할래!",
  ui_story_5089_50891400_202_dialog_content = "어? 마야?",
  ui_story_5089_50891400_203_dialog_content = "뭐야, 왜 아킬레스 씨가 마야 목소리로 말해요?!",
  ui_story_5089_50891400_204_dialog_content = "...그 아이가 내 뒤에서 말한 것이다.",
  ui_story_5089_50891400_205_dialog_content = "PlayerName 네가 떠난다길래 마야는 바로 널 찾으러 와 봤어!",
  ui_story_5089_50891400_206_dialog_content = "근데 마야는 오다가 길을 잃었거든. 이 친절한 오빠가 여기까지 데려다줬어.",
  ui_story_5089_50891400_207_dialog_content = "어쩐지 너 찾으러 갔을 때 없더라니...",
  ui_story_5089_50891400_208_dialog_content = "너 그렇게 막 다니면 제노랑 엘비스가 걱정할걸.",
  ui_story_5089_50891400_209_dialog_content = "크흠.",
  ui_story_5089_50891400_210_dialog_content = "아, 아니, 그 엘빈슨인가 하는 꼬맹이 있지 않았어?",
  ui_story_5089_50891400_211_dialog_content = "엘비스 오빠 맞아.",
  ui_story_5089_50891400_212_dialog_content = "크흠!",
  ui_story_5089_50891400_213_dialog_content = "결정한 것인가.",
  ui_story_5089_50891400_214_dialog_content = "우리의 도움 없이 이곳을 떠나기로.",
  ui_story_5089_50891400_215_dialog_content = "네, 여러분한테 계속 의존할 수만은 없으니까요.",
  ui_story_5089_50891400_216_dialog_content = "......",
  ui_story_5089_50891400_217_dialog_content = "여러분에겐 이미 새로운 미래가 있어요...",
  ui_story_5089_50891400_218_dialog_content = "전 여러분이 저마다 원하는 삶을 살아갔으면 좋겠어요.",
  ui_story_5089_50891400_219_dialog_content = "그렇다면 만약, 우리 중 누군가가 원하는 삶이 곧 「너와 함께하는 것」이라면\n어떻게 할 셈이냐.",
  ui_story_5089_50891400_220_dialog_content = "네? 그건...",
  ui_story_5089_50891400_221_dialog_content = "네가 우리에게 선택의 권리를 주고자 한다면,\n네가 저마다의 생각에도 주의를 기울여 주길 바란다.",
  ui_story_5089_50891400_222_dialog_content = "아마 누군가는 널 떠나길 원치 않을 것이다.",
  ui_story_5089_50891400_223_dialog_content = "또 누군가는 아직 너와의 여행을 차마 단념하지 못했을 것이다.",
  ui_story_5089_50891400_224_dialog_content = "그리고 그런 사람이 네 옆에 있을지도 모른다.",
  ui_story_5089_50891400_225_dialog_content = "훗, 어쩌면 네 콜로서스를 가득 메울지도 모르지.",
  ui_story_5089_50891400_226_dialog_content = "지, 진짜예요?",
  ui_story_5089_50891400_227_dialog_content = "그럼 마야도 갈래.",
  ui_story_5089_50891400_228_dialog_content = "마야 자리가 없으면 마야는 선조님한테 데리고 다녀 달라고 하면 돼.",
  ui_story_5089_50891400_229_dialog_content = "그럼 아쿠아리움은 어떡하고?",
  ui_story_5089_50891400_230_dialog_content = "으에엑?!",
  ui_story_5089_50891400_231_dialog_content = "마야는 PlayerName 일을 걱정하느라 잠깐 잊어버렸어!",
  ui_story_5089_50891400_232_dialog_content = "으으...",
  ui_story_5089_50891400_233_dialog_content = "무리하지 않아도 돼, 마야.",
  ui_story_5089_50891400_234_dialog_content = "이건 단번에 결정할 수 있는 문제가 아냐.",
  ui_story_5089_50891400_235_dialog_content = "급하게 선택할 필요는 없어.\n네가 같이 안 간다고 해서 우리가 덜 친하다고 생각하진 않을 거니까.",
  ui_story_5089_50891400_236_dialog_content = "진짜?",
  ui_story_5089_50891400_237_dialog_content = "그래, 진짜야.",
  ui_story_5089_50891400_238_dialog_content = "그럼... 마야는 아쿠아리움에서 기다릴게.",
  ui_story_5089_50891400_239_dialog_content = "응, 약속이야.",
  ui_story_5089_50891400_240_dialog_content = "좋아! 마야는 지금 당장 가서 제노 오빠, 엘비스 오빠한테 말해줄래!",
  ui_story_5089_50891400_241_dialog_content = "크, 크흐으음──",
  ui_story_5089_50891400_242_dialog_content = "이미 이해하게 된 모양이군.",
  ui_story_5089_50891400_243_dialog_content = "「작별」은 일시적인 이별을 의미한다.",
  ui_story_5089_50891400_244_dialog_content = "그러나 그것이 반드시 영원한 것은 아니다.",
  ui_story_5089_50891400_245_dialog_content = "네가 언젠가는 다시 돌아오길 원하는 것이라면,\n「작별」을 가장 무거운 생각 속에 담을 필요는 없다.",
  ui_story_5089_50891400_246_dialog_content = "차마 꺼낼 수 없는 「작별 인사」를 억지로 자신에게 강요할 필요도 없다.",
  ui_story_5089_50891400_247_dialog_content = "네 이야기는 아직도 계속되고 있다.",
  ui_story_5089_50891400_248_dialog_content = "잘 선택해서, 이 이야기가 네 마음속 완벽한 결말로 향할 수 있게 해 봐라.",
  ui_story_5089_50891400_249_dialog_content = "아킬레스 씨...",
  ui_story_5089_50891400_250_dialog_content = "다시 만나자, PlayerName.",
  ui_story_5089_50891400_251_dialog_content = "「아이테르」여, 더욱더 광활한 저 하늘로 날아가라.",
  ui_story_5089_50891400_252_dialog_content = "......",
  ui_story_5089_50891400_253_dialog_content = "......",
  ui_story_5089_50891400_254_dialog_content = "카렌, 난...",
  ui_story_5089_50891400_255_dialog_content = "스카이워커호가 왔어.",
  ui_story_5089_50891400_256_dialog_content = "출발할 시간이 된 거겠지?",
  ui_story_5089_50891400_257_dialog_content = "응.",
  ui_story_5089_50891400_258_dialog_content = "...꼭 처음 그때 같네.",
  ui_story_5089_50891400_259_dialog_content = "스카이워커, 나, 너, 그리고 바이스가 백야성에서...",
  ui_story_5089_50891400_260_dialog_content = "......",
  ui_story_5089_50891400_261_dialog_content = "잘...",
  ui_story_5089_50891400_262_dialog_content = "같이 가자, 카렌.",
  ui_story_5089_50891400_263_dialog_content = "...처음 그때처럼?",
  ui_story_5089_50891400_264_dialog_content = "그래, 처음 그때처럼.",
  ui_story_5089_50891400_265_dialog_content = "......",
  ui_story_5089_50891400_266_dialog_content = "...응, 갈게! PlayerName!",
  ui_story_5089_50891400_267_dialog_content = "너무 느리잖아, PlayerName.",
  ui_story_5089_50891400_268_dialog_content = "난 여기서 엄청 바빴는데.",
  ui_story_5089_50891400_269_dialog_content = "바이스, 나...",
  ui_story_5089_50891400_270_dialog_content = "올 줄 알았어.",
  ui_story_5089_50891400_271_dialog_content = "이렇게 오래 걸릴 줄은 몰랐지만.",
  ui_story_5089_50891400_272_dialog_content = "사람을 갑자기 데려가는 게 보통 일은 아니잖아...",
  ui_story_5089_50891400_273_dialog_content = "나도 마찬가지 아냐?",
  ui_story_5089_50891400_274_dialog_content = "너 진짜, 이렇게 오래 함께한 사이인데 아직도 어색한 거야?",
  ui_story_5089_50891400_275_dialog_content = "사람 속상하게, 바보.",
  ui_story_5089_50891400_276_dialog_content = "아...",
  ui_story_5089_50891400_277_dialog_content = "내가 도울 일은 없을까?",
  ui_story_5089_50891400_278_dialog_content = "이제 별거 없어. 목적지만 설정하면 끝이야.",
  ui_story_5089_50891400_279_dialog_content = "목적지는... 전에 발견했던 「환상의 땅」 맞지?",
  ui_story_5089_50891400_280_dialog_content = "응, 날 부르고 있고, 바이스의 기억 조각이 날아갔던 그 균열 너머.",
  ui_story_5089_50891400_281_dialog_content = "미자드 씨, 빅토리아 씨, 성녀님, 그리고 여러 사람들한테 확인을 받았어.\n저 너머에는 또 다른 세계가 있어.",
  ui_story_5089_50891400_282_dialog_content = "폭주하는 N물질의 세계라고 들었는데.",
  ui_story_5089_50891400_283_dialog_content = "맞아, 지극히 현실적인 세계고, 허구를 상징하는 X물질은 거의 감지할 수 없는 곳이라고 해.",
  ui_story_5089_50891400_284_dialog_content = "아마 무척 안전하겠지만, 신비로움도 가득할 거야.",
  ui_story_5089_50891400_285_dialog_content = "그래서 남들까지 나 때문에 그런 위험을 무릅쓰게 만들 순 없었어.",
  ui_story_5089_50891400_286_dialog_content = "...뭐... 모두가 내겐 더는 「남」이 아니긴 하지만.",
  ui_story_5089_50891400_287_dialog_content = "아, 근데 그러면 왜 아직도 거길 「환상의 땅」이라고 부르는 건데?",
  ui_story_5089_50891400_288_dialog_content = "음... 제일 마지막에 베들레헴 씨가 그러셨거든.",
  ui_story_5089_50891400_289_dialog_content = "거긴 우리 세계와 비교했을 때 현실적일지도 모르지만...",
  ui_story_5089_50891400_290_dialog_content = "허나 그곳과 아스트라는 끊을 수 없는 기묘한 연결을 이루고 있다.",
  ui_story_5089_50891400_291_dialog_content = "때문에 바이스의 기억은 끝내 그곳으로 흘러 들어갔고,\n아이테르가 찾고자 하는 진상 또한 그곳에 있다.",
  ui_story_5089_50891400_292_dialog_content = "어쩌면 그 현실 속에는 상응하는 허구 또한 존재할지도 모르지.",
  ui_story_5089_50891400_293_dialog_content = "이는 「현실」의 세계일지라도, 사람들은 여전히 아름다운 「꿈」을 공상한다는 것을 뜻한다.",
  ui_story_5089_50891400_294_dialog_content = "「그들」이 허구에 전한 사념은 결국 두 세계의 연결을 초래했지.",
  ui_story_5089_50891400_295_dialog_content = "...하지만 우린 그 환상을 끝내러 가는 게 아냐.",
  ui_story_5089_50891400_296_dialog_content = "그리고 꼭 가서 완전한 「현실」을 받아들일 필요도 없어.",
  ui_story_5089_50891400_297_dialog_content = "우린 그저 새로운 여정을 시작하고, 미지 속에서 우리의 사념이 엮인\n「아름다운 꿈」을 찾을 뿐이야.",
  ui_story_5089_50891400_298_dialog_content = "설령 이런 일들을 현실 속에서 하게 되더라도, 난 언젠가는 분명히 해낼 거라고 믿어.",
  ui_story_5089_50891400_299_dialog_content = "그때가 되면... 우리 다시 아스트라로 돌아오자!",
  ui_story_5089_50891400_300_dialog_content = "사실 난 네 생각이 그렇게 잘 이해가 되진 않아.",
  ui_story_5089_50891400_301_dialog_content = "그치만 우리가 이렇게 다시 여행할 수 있게 돼서 정말 기뻐.",
  ui_story_5089_50891400_302_dialog_content = "나도 그래.",
  ui_story_5089_50891400_303_dialog_content = "비록 제 대사는 거의 없지만, 부디 절 잊지 말아 주십시오.",
  ui_story_5089_50891400_304_dialog_content = "잊을 리가 없잖아?",
  ui_story_5089_50891400_305_dialog_content = "우리가 얼마나 고생해서 널 되찾아왔는데!",
  ui_story_5089_50891400_306_dialog_content = "그렇다면 어서 좌표를 설정하십시오.",
  ui_story_5089_50891400_307_dialog_content = "바이스.",
  ui_story_5089_50891400_308_dialog_content = "카렌 너도 같이 연주해 볼래?",
  ui_story_5089_50891400_309_dialog_content = "난 할 줄 모르잖아...",
  ui_story_5089_50891400_310_dialog_content = "뭐 어때, 마지막 환상은 이제 얼마 안 남았는걸.",
  ui_story_5089_50891400_311_dialog_content = "그래, 맞아. 네가 네 감정을 담으면, 나랑 바이스가 이끌어 줄게.",
  ui_story_5089_50891400_312_dialog_content = "...알겠어.",
